window.__D("text/maamarei-tzemach-tzedek/c000",{"p":[[4101400076,"<h3>בזהר פ' וירא כו' והוא מסיבות מתהפך</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>בזהר</b> פ' וירא ד' ק\"ט ע\"א והוא מסיבות מתהפך בתחבולותיו לפעלם כו' קוב\"ה מסבב סיבובין ואייתא עובדין בעלמא לאתקימא, ולבתר דחשיבו בני נשא דיתקימון אינון עובדין מהפך להון כו' כהאי אומנא כו' דההיא טקלא אסתחרת קמי', לפעלם אי מטיבין ב\"נ עובדיהון כו' יעו\"ש.\n<b>הנה</b> תוכן המאמר הוא דהקב\"ה מסבב סיבות מסיבות שונות וכ\"ז הוא לפי הפועל של ב\"נ, למשל אם בר\"ה היו כל ישראל יראי' את ה' כו' ונכתב להם שיהי' השפעת הטוב כו' ואם אח\"כ יקלקלו מעשיהם ח\"ו לא יהיה בעיניהם שיהא ג\"כ השפעת הטוב כמו שנכתב להם כן בר\"ה כ\"א כו' וכמ\"ש בפרש\"י ע\"פ זה באיוב ל\"ז וזהו לפעלם כמ\"ש הזהר כו' ופי' בתחבולותיו הוא דתחבולות נק' הע\"ס שהם תחבולותיו שע\"י מתנהג העולם וכמאמ' כולם לאחזאה איך מתנהג עלמא כו' וגם תחבולות נק' עומק המחשבה כמשל למטה מי שצריך לעשות איזה תחבולה אזי מעמיק בשכלו איך לעשותה כו' וכמ\"כ יובן למעלה שפנימיות החכ' נק' בשם תחבולה כו'.\n<b>והנה</b> המל' לפעמי' מקבלת מספירת החסד ולפעמי' מספירת הג' כו' וזהו לפעלם, כשבנ\"א מטיבין מעשיהם למטה ועובדי' את ה' באמת כו' אזי המל' מקבלת מספירת החסד ומקבלי' השפעת החסד כו' ואם ח\"ו מקלקלי' מעשיהם אזי המל' מקבלת מספירת הג' (כי האדם אינו יכול להגיע בעבודתו וביראתו כ\"א לבחי' המל' ולא יותר לפי ששרשו הוא מבחי' מל' דאצי' מקור דבי\"ע ואם שמקבלי' ההשפעה מבחי' הגבוה יותר מבחי' המל' כמו אם מטיבין מעשיה' מקבלי' מספירת החסד, אך זה אינו בהעלאת מ\"ן מלמטה כ\"א שהעלת מ\"ן דלמטה אינו מגיע כ\"א עד בחי' המל' דאצי' לפי שהנבראי' נפעלו מבחי'"],[4101400077,"מל' מידת מלכותו ית' כנ\"ל רק אם מטיבין מעשיהם אזי המל' מקבלת מבחי' החסד או להיפוך אבל האדם בעצמו אינו יכול להגיע באתעדל\"ת שלו לבחי' החסד כ\"א לבחי' מידת המל' כנ\"ל).\n(ב) <b>וזהו</b> מ\"ש הזהר כהאי אומנא כו' דהאי טקלא אסתחרת קמי' שהוא בחי' מל' שמתנענע לכאן ולכאן כפי פעלם דבני אנשא אם מטיבין מעשיהם כו' כנ\"ל והסובב ומהפך הגלגל היינו בחי' הטקלא הנ\"ל הוא בחי' קו המדה שמודדת לפי פעלם דבנ\"א אם מטיבין מעשיהם כו', והנה ע\"ד הקבלה נק' קו המידה זו בשם גבורה דע\"י בחי' בוצינא דקרדוניתא כו' וזהו מ\"ש והוא מסיבות מתהפך בתחבולתיו כו' והוא דא עתיקא כו' וכמ\"ש בזהר כאן הוא המהפך ומסבב סבות מסיבות שונות בהאי טקלא לפי פעלם דב\"נ וזהו כמ\"ש אי' שוקל אי' סופר כו' שבחי' אי' בעצמו הוא השוקל והסופר, וידוע דפעם כתי' מלכהא\"כ ופעם כתי' אי' מקום כבודו וכמ\"ש במ\"א שהמלאכי' שואלי' אי' שאינו מושג להם בחי' זו ולכן שואלי' אי' שאינו מושג כו' כנ\"ל והנה בחי' אי' זה הוא השוקל והסופר כו' ואינו בחי' נפרד כו' ולכן אי' שוקל ואי' סופר שבחי' אי' בעצמו הוא השוקל והסופר כנ\"ל והוא בחי' עיגול הגדול שהוא בחי' סוכ\"ע שקמי' כחשוכא כאורה שווין כו' וכמ\"ש בת\"א [פ' שמות] בד\"ה אי' שוקל אי' סופר, יעו\"ש.\n(ג) <b>הנה</b> הסיבות הוא כדי לברר בירורין כמו אברהם נולד מתרח ששרשו נפל בשה\"כ ולכן כדי שיולד אברהם הי' צריך להיות מתחלה הפרדת הרע מהטוב וזהו שהי' תרח רע גמור והטוב שנפרד מהרע הי' בחי' אברהם וכדוגמא זו הוא שכדי שיצא יצחק מאברהם הי' צ\"ל עוד בירור (שיצחק הי' עולה תמימה) דהיינו שמתחלה ישמעאל מאברהם ואח\"כ יצא יצחק שהוא בירור אחר בירור כו' וזהו ענין הסיבה שאברהם יקח את הגר לאשה ויוליד ממנה את ישמעאל ואח\"כ יוצא ממנו יצחק שזהו ענין הבירורי' הנ\"ל וכמ\"ש בזהר ת\"ח קוב\"ה גרם סיבובין ועובדין בעלמא כו' אקריב אברהם לגבי ונפק מיני' ישמעאל דלא הוה אברהם גזיר כו' ואתגזיר אברהם כו' כיון דרזא אישתלים ואתגזיר נפק מיני' יצחק יעו\"ש והוא ענין הבירורי' הנ\"ל.\n(ד) <b>ובד\"כ</b> יש שני בחי' עילות העילות וסיבות הסיבות כו' והנה ההפרש שבין עילת העילות לסיבות הסיבות הוא דהנה עילת העילות הוא בחי' השתלשלות של' עילת העילות הוא ל' עילה ועלול שעילה משגת עילתה וזהו בחי' השתלשלות וסיבות הסיבות הוא בחי' שלמעלה מהשתלשלות, ויובן כ\"ז עד\"מ למטה כשזורעי' איזה תבואה ואח\"כ מצמיח זהו בחי' השתלשלות אבל אם למשל כשצריך להרחיק נדוד ולנסוע למרחקי' לקנות סחורה משם ולמוכרם במרחקי' ג\"כ זה השפע לא בא בסדר השתלשלות כ\"א מלמעלה מסדר השתלשלות וההדרגה משם נמשך מה שהוא מסבב סיבות שיצטרך"],[4101400078,"לנסוע למרחקי' כו' (בעת שהי' כ\"פ בלאדי) (ועוד אפ\"ל שמה שמשתכר בסחורה והיינו משל הנ\"ל נק' בחי' עילות העילות שנק' בחי' ההשתלשלות, אבל אם למשל שמצא איזה אוצר שיש בו מעות הרבה אשר לא יגע ולא טרח אליהם כלל זהו מלמעלה מסדר השתלשלות והדרגה) וכן הנס נק' ג\"כ מלמעלה מסדר השתלשלות כמשל נס דפורי' שמתחלה הי' צריך להיות סיבה שיהרוג אחשורוש את ושתי ואח\"כ יקח את אסתר וב\"כ יגדל את המן וכ\"ז הוא כדי שאח\"כ יהי' הנס לישראל שינצלו מגזירת אחשורוש ע\"י עצת המן הרע, וזהו בחי' סיבה וכמו סיבה היתה מאת ה', אבל בחי' ההשתלשלות נק' בשם עילת העילות כנ\"ל וד\"ל."],[4101400079,"<h3>להבין ביאור הדברי' ע\"פ מי יעלה</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>להבין</b> ביאור הדברי' ע\"פ מי יעלה לנו השמימ' ושע\"י מילה ממשיכין בחי' מקיפי' של הנשמה בחי' ח\"י, ולהבין כ\"ז צריך להקדי' ב' הקדמות הא' הוא להבין ענין מקיפי' ופנימי' הנה שמי' נק' אור מקיף שהוא מקיף על הארץ כי הארץ הוא כגרגר חרדל לגבי שמי' והשמי' מקיפם מכל צד והארץ נק' בשם א\"פ, וע\"ד הקבלה שמי' נק' ז\"א וארץ נק' מל' והנה ז\"א הוא בחי' מידות ומל' נק' דיבור וכמשל למטה באדם אנו רואי' שהמידות מקיפים את הדיבור מכל צד כמו אם צריך לגלות איזה אהבה אזי המידה מקפת את הדיבו' מכף ראשו ועד רגלו (רק שההתגלות לזולתו אינו כ\"א הדיבור) וכן במידת הכעס (וכידוע ששורש הדיבור הוא מהמידות) וכמ\"כ יובן למעלה שז\"א היינו מידות עליונות בחי' שמי' נק' בשם מקיפי' שמקיפי' את הארץ שנק' א\"פ כמובן מתוך משל הנ\"ל שהמידות מקיפי' את הדיבור, והנה כתי' השמי' שמי' לה' ואיתא בזהר השמי' שמי' ב' בחי' שמי' שמי' עילאין ושמי' תתאין, שמי' תתאין נק' ז\"א וארץ תתאה נק' בשם מל' כנ\"ל ושמי' וארץ עילאין הם חו\"ב כי בינה נק' בשם ארץ שהוא אור פנימי (אך לא הבינה עצמה כ\"א בחי' תבונה שהוא אותיות בן"],[4101400080,"ובת מקור לז\"א משא\"כ הבינה עצמה היא עם החכ' ונק' תרין ריעין דלא מתפרשי' לעלמין וזהו יו\"ד של שם הוי' שהוא בחי' חכ' והנה המילוי ו\"ד שעולה ג\"כ מספר יו\"ד וזהו בחי' בינה שהמילוי הוא בחי' בינה כמ\"ש בכהאריז\"ל נמצא שבחי' בינה כלולה בחכ' וזהו והבן בחכ' כו') וחכ' נק' בשם אור מקיף בחי' חי' כמ\"ש והחכ' תחי' וזהו בחי' שמי' וארץ עילאין, וכתי' הן לה' אלוקינו השמי' ושמי השמי' השמי' קאי על ב' בחי' שמי' הנ\"ל שמי' תתאין ושמי' עילאין, ושמי השמי' קאי על בחי' כתר בחי' יחיד' שבנשמה, והנה במילה כתי' מי יעלה לנו השמי' ר\"ת מילה והנה השמימה הוא ל' רבי' שכולל כל הבחי' שמי' הנ\"ל שמים תתאין ושמי' עילאין ושמי השמים בחי' כתר כי ע\"י המילה הוא גילוי יסוד אבא ויסוד א\"א ב' בחי' שמי' ושמי השמי'.\n(ב) <b>והקדמה</b> הב' שצריך להבין ענין הבירורי' דהנה לפעמי' מצינו שהמל' הוא המברר כמ\"ש ותתן טרף לביתה טרף רפ\"ח עם הכולל שהמל' הוא המברר רפ\"ח ניצוצין שנפלו בשבירה, ולפעמי' מצינו שחכ' הוא המברר וכמאמר בחכ' אתברירו, והענין הוא דהנה יש שני בחי' מ\"ן ומ\"ד, בתחלה העלאת מ\"ן ואח\"כ המשכת המ\"ד וכמ\"כ יובן למעלה שבתחילה העלאת מ\"ן בלילה ואח\"כ ביום הוא בחי' המשכת המ\"ד שיהי' בחכ' אתברירו, והנה כמו למטה ע\"י העלאת מ\"ן והמשכת מ\"ד נעשה הולדה כמ\"כ למעלה ע\"י העלאת מ\"ן והמשכת המ\"ד בחכ' איתברירו נולדי' נשמות ומלאכי' דהנה יש מלאכי' שנק' בשם יוצר משרתי' והיינו שנולדי' בכל יום ע\"י היחוד מ\"ן ומ\"ד, ויש מלאכי' שנק' אשר משרתיו שעומדין מכבר כמו מיכאל וגבריאל וההפרש שבין מלאכי' ונשמות הוא שהתהות הנשמות הוא מפנימיות ומלאכי' עיקר התהוותם מחיצוניות כו' כידוע.\n<b>קיצור</b> מב' הסעיפי', שמי' מקיפי' חי' וארץ א\"פ נר\"נ, ושמי' וארץ תתאין זו\"נ ושמי' וארץ עילאין חו\"ב בינה נק' נשמה אך לא בינה כ\"א תבונה ובחי' יחידה שמי השמי'.\n<b>ענין</b> [הבירורים] מ\"ן ומ\"ד יוצר משרתי' מהמ\"ן א\"א שיתהוה כ\"א ע\"י המשכת המ\"ד דוקא נולדי' נשמות ומלאכי', נשמות מפנימיות ומלאכי' מחיצוניות.\n(ג) <b>והנה</b> כדי שיתהוו נשמות חדשות צ\"ל המשכה חדשה מאוא\"ס ב\"ה שלמעלה מאצי' דוקא כי אצי' היא אורות בכלי' והוא רק כדי לחדש הישינות, דהיינו שיומשך בבי\"ע, אבל הולדת נשמות חדשות הוא שיומשך גם בעולם האצי' (וזהו סוד אין כל חדש תחת השמש), והנה עיקר המשכה זו היא לע\"ל שיהי' גילוי פנימיות ע\"י וזהו בחי' יחידה שבנשמה כידוע שנרנח\"י המה כנגד ה' מדריגות ע\"י וא\"א ואו\"א וז\"א ומל' וכמ\"ש בכהאריז\"ל שעדין לא זכה"],[4101400081,"שום אדם לגילוי בחי' יחידה שדוד זכה לבחי' נפש כמ\"ש לדוד כו' נפשי ואלי' זכה לבחי' רוח וכתי' בו ל' רוח ואדם הראשון לבחי' נשמה וכמ\"ש ויפח באפיו נשמת, ומשה זכה לבחי' חי' ע\"ש ובחי' יחידה יתגלה למשיח דוקא שיהי' לע\"ל שעליו נאמר הפסוק הנה ישכיל עבדי ירום ונשא וגבה מאד שהוא בחי' ה' מדריגות ישכיל ירום ונשא וגבה מאד מאוד היא בלי גבול בכל מאדך ועי\"ז יתגלה בחי' פנימיות ע\"י ובעוה\"ז א\"א להיות גילוי פנימיות ע\"י ואפי' העלי' שביוהכ\"פ שהיא בע\"י אינה כ\"א בבחי' חיצוניות ע\"י אבל לא בפנימיות ע\"י וכעת הגילוי הוא רק ממוחין דאו\"א, ולע\"ל וגבה מאד שהוא התגלות אור הכתר והוא כי לע\"ל יתגלה בחי' מקיפי' (וי\"ל שהוא מהעיגול שלפני הקו שקו הוא א\"פ ע\"ד נר\"נ בי\"ע, וכללות נשמות חדשות הוא מסוכ\"ע שלמעלה מהקו מקיף הכללי, וכדוגמא שמצינו שבימי התנאי' הי' קצת נשמות מבחי' מקיפי' כמו ר\"מ שהי' אומר על טמא טהור ומראה לו פנים, או ר\"א שאמר מן השמי' יוכיחו ויצא ב\"ק ואמרו הלכה כר\"א, והשיב ר\"י אין משגיחין בב\"ק לא בשמי' היא, והענין הוא דהנה התורה משמי' לארץ בבחי' א\"פ וזהו שהתורה ניתנה במ\"ט פנים כנגד מ\"ט שערי בינה שנמשכי' בז\"א, וא\"כ לא בשמי' היא דהיינו בבחי' מקיפי' אכן נשמת ר\"מ ממקור האור מהמקיף בחי' חי' שהוא בחי' חכ' (ומה שמבואר במ\"א שמצד המשפיע יכולי' אוה\"ע ג\"כ לקבל רק אם נמשך דרך צמצום החכ' אז אין אוה\"ע יכולי' לקבל כי בחכ' אתברירו ונמצא שהחכ' הוא בחי' פנימיות ע\"ש בסידור בד\"ה מזמור לתודה, י\"ל שזהו רק בחי' מל' שבחכ' אבל ט\"ס דחכ' המה בבחי' מקיפי' כמ\"ש כאן) וכמשארז\"ל על ר\"מ לא ר\"מ שמו אלא ר' נהוראי שמו וקראו שמו מאיר על שהי' מנהיר עיני חכמי' בהלכה והוא מפני שהי' ממקור האור, ולכן הי' יכול לאמור על טמא טהור ומראה לו פנים, כי מצד המקיף אינו תופס מקום כלל ומה גם שאין בו התחלקות כלל כמשל העיגול כמ\"ש במ\"א. ואפ\"ל עוד כמו השכל יכול להפוך לזכות ולחוב כמו אמחה כו' ואח\"כ לא אוסיף כו' מטעם א'."],[4101400082,"<b>[הנחת כ\"ק אדמו\"ר מהר\"ש]\nבס\"ד</b>"],[4101400083,"<h3>ראה קראתי</h3>\n<b>ראה</b> קראתי בשם בצלאל וגו', במד\"ר פ' כי תשא פמ\"א איתא הראה הקב\"ה למשה בספרו של אדם הראשון שבצלאל יבנה המשכן ויעשה כליו יע\"ש והנה בפ' תרומה בציוי משה לבצלאל כתי' שיעשה הארון תחלה ואח\"כ הכלי' ואח\"כ המשכן וארז\"ל מה השיב בצלאל למשה הלא דרך האדם בונה בית ואח\"כ מכניס לתוכן כלי' וכו'. ולהבין כ\"ז הנה כתי' ושכנתי בתוכם בתוכו לא נאמר אלא בתוכם (בשם המגיד נ\"ע) והיינו שיש בכאו\"א מישראל בחי' משכן וכליו, ולהבין איך שייך שיש בכאו\"א בחי' משכן וכליו הנה כתי' וידעת היום והשבות אל לבבך, שיש שני לבבות, היינו חיצוני' הלב ופנימיות הלב והם כנגד שני המזבחות פנימי וחיצון, חיצוניות הלב נגד מזבח החיצון, שעליו מקריבין פרי' אלי' וכבשי', וכמ\"כ הוא בבחי' חיצוני' הלב שמקריבין הנה\"ב ומעלי' אותה למקור חוצבה, ובחי' פנימיות הלב כנגד מזבח הפנימי שעליו מקריבין קטורת (ביוהכ\"פ).\nב) <b>והנה</b> כמו שהי' במשכן גם בחי' מקיפי' כמ\"כ י\"ל בנפש האדם והוא מ\"ש וידעת היום שהוא בחי' דעת שנק' מקיף וכמשל ההתבוננות הוא במוח הדעת ואח\"כ נצמח מזה איזה מידה לאלקות, אמנם כ\"ז שההתבוננות היא במוח הדעת איך שאני הוי' לא שניתי הוא רק בבחי' מקיף ואח\"כ באה בבחי' פנימי' וזהו וידעת היום תחלה ואח\"כ והשבות אל לבבך והמכוון הוא כי ה' הוא האלקי' כמ\"ש במ\"א.\nג) <b>והנה</b> במשכן הי' ד' בחי' תכלת וארגמן תולעת שני ושש, וכנגדן ד' כלי' מנורה ושולחן ומזבח וארון כי מדריגות אלו ישנם במקיפי' וגם בפנימי' ולהבין זה בנפש האדם הנה תכלת היא בחי' אהבה מל' תכלה שהוא בחי' כליון ואהבה להשם ית' ותולעת שני הוא בחי' אדמומי' שהיא בחי' גבורה"],[4101400084,"יראה, וארגמן הוא בחי' התכללות חו\"ג, וזהו שארגמ\"ן ר\"ת משמות המלאכי' הממוני' על ד' חיות המרכבה מיכאל גבריאל אוריאל כידוע שהיא בחי' התכללות, ושש הוא בחי' בד שעולה יחידי וגם הוא גוון לבן שהוא עצמי' שאין תערובות והוא בחי' לבנוני' ובחי' זו היא כנגד אהבה המסותרת שיש בכאו\"א מישראל שהיא אהבה טבעי'.\nד) <b>והנה</b> ד' בחי' תכלת וארגמן ותולעת שני ושש שהי' במשכן הי' מבחי' מקיפי' וכמ\"כ יש בבחי' פנימי' והם הד' כלי' שהיו במשכן ארון ושולחן ומנורה ומזבח, כי הנה שולחן בצפון ומנורה בדרום והנה אף שהמנורה היא בדרום שהוא בחי' חסד אעפ\"כ המנורה היא בחי' גבורה שהיא בחי' אש וטבע האש לעלות למעלה ושולחן אף שהי' בצפון בחי' גבורה אעפ\"כ היא בחי' חסד שהוא השפעת החסדי', והמזבח הי' עומד באמצע היינו כנגד בחי' ארגמן, והארון כנגד בחי' שש, והנה הפרש שבין ד' בחי' מקיפי' לפנימי' שהפנימי' כל מדריגה בפ\"ע משא\"כ במקיפי' אף שהם ד' מדריגות אעפ\"כ הם כלולי' יחד (ולכן הי' בכל חוט מד' מדריגות כידוע). והנה בצלאל אמ' שיעשה כסדר הפסוק וידעת היום בחי' מקיף תחלה ואח\"כ והשבות אל לבבך בחי' פנימי.\nה) <b>ומעתה</b> צ\"ל מ\"ש משה שיעשו הארון והכלי' תחלה ואח\"כ המשכן דלכאו' נהפוך הוא וצ\"ל כוונת משה. והענין הוא דהנה יש פלוגתא בגמ' אם שמי' קדמו אם ארץ קדמה ובאמת בסדר הבריאה שמי' קדמו אבל עיקר המכוון הוא בחי' ארץ דוקא שבמחשבה קדמה ארץ לשמי' שהיא עיקר המכון כמ\"ש ואדם עלי' בראתי, וכמ\"כ יובן כאן שבציוי הקב\"ה למשה הי' תחלה המשכן ואח\"כ הארון וכליו אבל במחשבה הארון קדם לזה אמר משה שיעשה הארון תחלה לפי שקדם במחשבה אף שיצא בדיבור אחרון והוא כמשל חותם המתהפך או ע\"ד משארז\"ל נכנס ראשון יצא אחרון וכמשל צמיחת התבואה שעיקר היא התבואה ואעפ\"כ צומחין הקש והתבן תחלה.\nו) <b>דוגמא</b> לפלוגתא זו מצינו פלוגתא אם שמי' קדמו אם אור קדם כי הנה כתי' בראשית ברא השמי' והארץ ואח\"כ יהי אור וי\"א להיפוך ע\"ד מ\"ש עוטה אור כשלמה נוטה שמי' כיריעה בתחלה אור ואח\"כ שמי', וד\"ל."],[4101400085,"<h3>משנה ג' רפ\"ק דמגילה איזהו עיר גדולה</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>משנה</b> ג' רפ\"ק דמגילה איזהו עיר גדולה כל שיש בה עשרה בטלני', פי' עשרה אנשי' שבטלי' ממלאכתם ועוסקין בתורה, וע\"ד הקבלה עשרה בטלני' הם ע\"ס ופי' עיר הוא מל' כידוע, והפי' הוא כשע\"ס מאיר במל' אז נקראת עיר גדולה כידוע ממ\"ש אימתי הוא גדול כשהוא בעיר אלקינו (עמ\"ש ע\"פ קול דודי מדלג (תרי\"ג) ב' פירושים ע\"פ גדול ה') וכשמאיר בבחי' עיר מבחי' גדול ה', אז נק' העיר היינו בחי' מל' בשם עיר גדולה מה גם כשמאיר כל הע\"ס במל' אז המל' הוא מל' דאצי' משא\"כ בעשי' אינו מאיר כל הע\"ס.\n<b>[הנחת כ\"ק אדמו\"ר מהר\"ש]\nב\"ה</b>"],[4101400086,"<h3>א-ל הוי' ויאר לנו אסרו חג בעבותים</h3>\n<b>אל</b> ה' ויאר לנו א\"ח בעבותי' עד קרנות המזבח וארז\"ל כל העושה איסור לחג מעלה עליו הכתוב כאילו בנה מזבח והקריב עליו קרבן. ופי' רש\"י איסור לחג היינו שמענג את החג באכילה ושתי' (פי' בעבותי' פרות שמינות) ובפי' שני פי' שהוא ביום שאחר יו\"ט מה שאנו קורין אסרו חג. ולהבין כ\"ז צריך להבין תחלה מפני מה נק' יו\"ט הנה ארז\"ל עשר קדושות הן ירושלי' קדושה ראשונה כו' עד ק\"ק קדושה עשירית, ולכאור' צ\"ל מאחר שק\"ק היא הקדושה היותר נעלה מכולן דהיינו שמאיר בק\"ק גילוי אלקותו ית\"ש מהו הקדושה בירושלי' למט', וגם צ\"ל מה שידוע שיש כמה מיני עולמות כמו עולם המלאכי' עולם הנשמות עולם האצי' וכולם מדריגות חלוקות זמ\"ז וגם בכל עולם יש מדריגות חלוקות כמו בעולם העשי' יש דצח\"מ ועד\"ז בכל העולמות והנה כולם נתהוו מאתו ית' והלא הוא ית' הוא אחדות פשוט בתכלית הפשיטות וכתי' אני ה' לא שניתי, אך הענין הוא דהנה ידוע שיש שני בחי' ממכ\"ע"],[4101400087,"וסוכ\"ע פי' סוכ\"ע הוא כמשל הגלגל שאין בו מעלה ומטה כך פי' סוכ\"ע שסובב ומקיף כל העולמות בהשואה א' אצי' כמו עשי', וכמשל השמי' שמקיפי' את הארץ הנה מצד השמי' אין מעלה ומטה כלל (ולכן אנשי אמעריקע שלפי דעתינו הולכי' בראשם למטה וברגליהם למעלה אך באמת אינו כן מטעם הנ\"ל כמשי\"ת במ\"א) וזהו בחי' סוכ\"ע, אבל בחי' ממכ\"ע הוא בציור אדם וכמשארז\"ל מה הנשמה ממלא את הגוף כך הקב\"ה ממלא את כל העולם פי' כמו שבאדם יש מדריגות חלוקות דהיינו שבלב הוא משכן המידות ובמוח החכ', משא\"כ ברגלי' כמו\"כ בחי' ממכ\"ע הוא מדריגות חלוקות זמ\"ז, ובזה יובן דמה שיש עולמות חלוקות זמ\"ז זהו מצד בחי' ממכ\"ע כנ\"ל, משא\"כ מצד בחי' סוכ\"ע, אך איך נתהוה בחי' ממכ\"ע מאתו ית' שהוא אח\"פ זהו ע\"י צמצום שצמצם אורו ית' בצמצום אחר צמצום, עד שנתהוה בחי' ממכ\"ע.\n(ב) <b>אך</b> הנה עיקר עבודת האדם הוא להמשיך שיהי' גילוי אלקותו ית' למטה כמו למעלה כמו שהי' בבהמק\"ד גילוי אלקות, וע\"י מה ממשיכי' הוא ע\"י תומ\"צ כי הנה המצות נק' בשם זריעה כמ\"ש זרעו לכם לצדקה כו' זורע צדקות, והנה הזריעה יש בה שני הבחי' בתחילה צריך להסיר הקוצים והברקני' ואח\"כ צריך לזרוע וכמ\"כ הוא במצות שהוא מ\"ע ומל\"ת מל\"ת הוא להסיר המונעי' ובערת הרע ומצות עשה היא הזריעה, והצמיחה היא לע\"ל, אך אעפ\"כ ביו\"ט יש קצת גילוי מהצמיחה כי הנה כל המצות שעושי' מיו\"ט ליו\"ט מתעלי' ביו\"ט ולכן נמשך הארה מהצמיחה ולכן נק' היו\"ט בשם יום טוב כי טוב הוא אור כמ\"ש וירא אלקי' את האור כי טוב (מחמת האור והשמחה שנמשך ביו\"ט שלכן נק' מועדי' לשמחה נק' בשם יום טוב והנה השמחה שביו\"ט צריך למשוך אותה בעבודה כי בעבודה כתי' ג\"כ שמחה כמ\"ש עבדו את ה' בשמחה.\n<b>וע\"י</b> מה ממשיכין בחי' זו הוא ע\"י מצות שנק' עבותות ע\"ד עבותות אהבה וכמו אהבה דוחקת את הבשר כמ\"כ המצות מצד שרשם הם גבוהי' מאד וירדו למטה בגשמיות מצה או שא\"ד זהו מצד האהבה אהבה דוחקת כו'. וזהו אל ה' ויאר לנו א\"ח בעבותי' פי' שכדי שיהי' אל ה' ויאר לנו היינו שיהי' גילוי אלקותו ית' למטה זהו ע\"י אסרו חג בעבותי' ע\"י המצות וזהו שארז\"ל כל העושה איסור לחג פי' שמענג את היו\"ט דהיינו שממשיך התגלות התענוג בהשמחה עי\"ז נעשה גילוי למטה קצת.\n<b>עד</b> קרנות המזבח, פי' כי קרנות המזבח הי' כנגד ד' אותיות הוי' וד' אותיות דשם אדני והי' גילוי אלקות בבהמק\"ד כמו למעלה כמ\"כ ימשיך האדם ע\"י עבודתו בתומ\"צ שיהי' ג\"כ למטה כמו למעלה וד\"ל."],[4101400088,"<h3>בזוהר פ' תזריע ע\"פ ואיש כי ימרט כו' וראיתי אני</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>בזוהר</b> פ' תזריע דמ\"ז א ע\"פ ואיש כי ימרט פר\"ח וראיתי אני שיש יתרון לחכ' מן הסכלות, האי קרא אית לאסתכלא בי' אמאי וראיתי אני וכי שאר בני עלמא לא ידעין ולא חמאין דא, אפי' מאן דלא ידעי חכ' ולא אשגח בי' ידעי' כו' והוא שבח גרמי' ואמר וראיתי אני. הנה כתי' כה אמר ה' מלך ישראל וגואלו אני ראשון ואני אחרון כו' וידוע דפי' אני הוא מל' ובכאן כתי' ב\"פ אני. הנה החכ' מאין תמצא שבחי' אי\"ן הוא מקור ומוצא החכ' ואי\"ן אני שבחי' אנ\"י מלובש בבחי' אי\"ן שהוא בחי' מל' דא\"ק שמלובש בבחי' אי\"ן דאצי' שהוא מקור ומוצא החכ' דאצי', ובד\"כ מלובש מל' דא\"ק בבינה כי התגלות עתיק בבינה וזהו בחי' אני ראשון, ובחי' אני אחרון היא מל' דאצי' שמלובש ג\"כ בבחי' אי\"ן דבריאה שהוא כח\"ב היכל ק\"ק דבריאה, והנה כתי' את השמי' ואת הארץ אני מלא ולכאו' י\"ל שבחי' אני ראשון מאיר בבחי' שמי' ובחי' אני אחרון מאיר בבחי' ארץ כי בד\"כ נק' שמי' בשם אצי' וארץ בשם בי\"ע, אבל באמת אינו כן שפי' את השמי' ואת הארץ אני מלא שמאיר בשמי' ובארץ בשוה ממש מבחי' אני ראשון ע\"ד בחי' סוכ\"ע שמאיר בהשואה ממש למטה כמו למעלה, וזהו כה אמר ה' מלך ישראל וגואלו ה' צבאות אני ראשון ואני אחרון, כי מלך ישראל הוא בחי' מל' ית' השוכן ומתלבש בתחתוני' בהשתלשלות וירידת המדריגות מאור א\"ס, וגואלו של מלך פי' שיגאל ויפדה מדת מל' ית' מהתלבשות בק\"נ ולהיות בבחי' את השמי' ואת הארץ אני מלא בבחי' שמי' וארץ בשוה להיות הגילוי למטה כמו למעלה ואז אני ראשון ואני אחרון בשוה וע' בלק\"ת שה\"ש ד\"ה נאוו לחייך בתורי' פ\"ג, והנה שלמה הי' מבחי' מל' דאצי' בחי' אני אחרון ולכן וראיתי אני בחי' מל' דאצי' דוקא כידוע דעיקר הבירור הוא במל' דאצי' דוקא וזהו פי' הפסוק וראיתי אני בחי' מל' דאצי' שיש יתרון לחכ' היינו חכ' התורה מן הסכליות היינו שכל אנושי שהוא בחי' שאר החכ' הנמצאי' חוץ מחכ' התורה.\n<b>אלא</b> הכי תנא מאן חכי' כשלמה דבשבעה דרגין דחכ' אתקריא כגונא דלעילא שית יומין לעילא שביעאה עילאה עלייהו שית יומין לתתא שביעא' עליהו שית דרגין לכורסיא כו' שבעה כתרין דיומין לעילא וכדין לקבליהון שבעה שמהן לשלמה כו' ע\"ש. פי' שית יומין לעילא היינו ו\"ק דאצי' שביעאה עילאה עלייהו בחי' בינה, שית יומין לתתא היינו ו' היכלות דבריאה שביעאה עלייהו פי' היכל ק\"ק דבריאה, שית דרגין לכורסי' ו\"ק דבריאה, וכסא"],[4101400089,"עצמו הוא אור המל' שמתלבש בכחב\"ד דבריאה, ז' כתרין לעילא פי' ו\"ק ובינה וכנגדן ז' שמות לשלמה פי' כי שלמה הוא מל' דאצי' כנ\"ל הי' לו ז' שמות היינו בחי' ו' מידות שביעאה כנגד בינה פי' שקהלת היא נגד בחי' בינה כי קהלת מל' קהלה והיינו בחי' בינה שהוא בחי' שבת ולכן אומרי' בשבת בויכולו ג\"פ ביום השביעי ואיתא בכהאריז\"ל הראשון בחי' בינה כנ\"ל שני יסוד פי' דרך השפעה למטה יסוד היא שביעי שלישי מל' פי' כשמוני' מחסד אז המל' הוא שביעי, וזהו שאמר שלמה ז\"פ הבל פי' הבל הוא מילוי דשם ס\"ג (בחי' בינה) כמ\"ש במ\"א ע\"פ ויהיו חיי שרה עיקר שנותיה של שרה ל\"ז שנה כמנין ויהיו וכמנין הבל והוא מפני שהבל מילוי דשם ס\"ג ושרה היא בחי' מל' ועיקר קיום המל' הוא מבינה.\n<b>[הנחת כ\"ק אדמו\"ר מהר\"ש]\nבס\"ד</b>"],[4101400090,"<h3>כי תבואו אל הארץ כו' ושבתה</h3>\n<b>כי</b> תבואו אל הארץ כו' ושבתה הארץ שבת לה'. וידוע מה שיש לדקדק בזה הוא כי משמעות הפסוק מיד כי תבואו אל הארץ אזי ושבתה הארץ קודם שש שנים. ויובן בהקדם ענין תורה ותפלה דלפעמי' מצינו שהתורה גבוה מתפלה כמשארז\"ל ות\"ת כנגד כולם, ולפעמי' מצינו שיש יתרון בתפלה כנגד בחי' התורה כמאמר והלואי יתפלל אדם כל היום כולו, הנה כתי' וכל בניך למודי ה' וארז\"ל אל תקרא בניך אלא בוניך (אלו ת\"ח שעוסקי' כו') ולהבין זה י\"ל תחלה מארז\"ל בעשרה מאמרות נברא העולם והלא במאמר אחד יכול להבראות ויש בזה שני פרושי' הא' הוא כי פי' מאמר א' הוא מאמר בראשית כי בראשי' נמי מאמר הוא ופי' כי אם הי' נברא העולם במאמר א' היינו בחי' מאמר בראשי' הי' העולם באופן אחר היותר נעלה והיינו שהי' בחי' ביטול יותר (וע' בת\"א בד\"ה מזוזה מימין מענין חפץ ע\"ש) מאשר כעת שנברא בעשרה מאמרות כי אף כעת שנברא בי\"מ מאמר בראשית הוא היותר נעלה שכולל כל הי\"מ, ויש מפרשי' בהיפוך והוא גם ע\"פ דרך הפשוט כי מה שנברא בע\"מ הוא היותר נעלה מאשר אם הי' נברא במאמר א' כי מאמר א' היינו בחי' מל' ועתה"],[4101400091,"שנברא בעשרה מאמרות הרי יש בה ג\"כ מבחי' חכ' וכתר כו' ולכן אור שנברא ביום ראשון הי' אדם מביט כו' וע\"ד הקבלה שבעת ימי בראשית המה ז\"ת דע\"ק.\n<b>ולכן</b> כתי' אלה תולדות השמי' והארץ מלא בשני ואוי\"ן משא\"כ בכל התורה כ\"א אלה תולדות פרץ ג\"כ מלא, והוא כי העולם על מילואו נברא' ואח\"כ חסר כו' כידוע ולימוה\"ש יעמוד העולם על מילואה ג\"כ וזהו תולדות פרץ מלא ואווי\"ן.\n<b>והנה</b> תחלת הבריאה היתה מצד בחי' כי חפץ חסד הוא אבל כעת כתי' ויניחהו בג\"ע לעבדה ולשמרה שצריך להמשי' בחי' ע\"מ וזהו וכל בניך א\"ת בניך אלא בוניך שע\"י עסק התורה ממשיכי' בחי' ע\"מ כמשי\"ת לקמן אי\"ה, ולהבין לעבדה ולשמרה צ\"ל תחלה פי' וענין ג\"ע, פי' ג\"ע הוא זיו השכינה, ופי' זיו הוא הארת פנים כמ\"ש במ\"א, וע\"ד הקבלה זיו בחי' יסוד ולכן כתי' ביוסף יפה תואר ויפה מראה, והנה ארז\"ל סריס אין לו הדרת פנים ולהבין מהו השייכות בחי' זיו להדרת פנים יובן בהקדם ענין מלאכי' ונשמות דלכאו' צ\"ל מה שבנשמות יש בחי' הולדה משא\"כ במלאכי' שאין שייך לומר כלל בהם בחי' הולדה שממלאך א' לא יתהווה עוד מלאך כ\"א נק' עומדי' כו', והענין הוא כי הנה המלאכי' עיקר התהוותם הוא מבחי' חיצוני' משא\"כ הנשמות המה מבחי' פנימיות ולכן יש בנשמות בחי' כח המוליד כו' כמ\"ש במ\"א וזהו השייכות בחי' זיו להדרת פנים כי זיו הוא יסוד בחי' משפיע וההשפעה נמשך מבחי' פנימיות החכ' ולכן זהו הארת פנים שמאיר בחי' חכ' בפניו כמ\"ש חכמות אדם תאיר פניו והמ\"י.\n<b>והנה</b> צריך להמשיך בחי' זו בג\"ע והוא ע\"י לעבדה ולשמרה פי' אתכפיא ואתהפכא כי עי\"ז יתברר בחי' ב\"ן ועיקר העבודה בעולה\"ז לברר בחי' ב\"ן שנפל בשבירה כי פי' שבה\"כ הוא כמשל הרב שאומר איזה שכל לתלמידו כשהתלמיד מקבל השכל אזי מקבל השכל עם האותיות משא\"כ כשאינו מקבל השכל אזי אותיות השכל משתברי' ומתפרדי' כו' וכמ\"כ הוא בחי' שבה\"כ שנתפרדו ונפלו ונפל שם ב\"ן למטה ועיקר העבודה לברר בחי' שם ב\"ן ולהעלותו למקור חוצבו שבשרשו הוא היותר נעלה אף מבחי' שם ס\"ג.\n<b>והנה</b> המברר ב\"ן הוא בחי' שם מ\"ה וזהו וכל בניך א\"ת בניך אלא בוניך שהיא בחי' תורה שבתורה מבררי' בחי' שם ב\"ן שנפל בשבירה כי בחכ' אתברירו אך איך יגיע למעלת ומדריגות שם מ\"ה שיוכל אח\"כ ע\"י עבודתו בתורה לברר שם ב\"ן שנפל בשבירה הוא ע\"י מעלת התפילה, כי תפילה היא בחי' קול דממה דקה וגם כריעות והשתחואות בחי' ביטול ומתחלה צריך להקדי' פסוד\"ז ובק\"ש וק\"ש שעי\"ז יגיע לבחי' תפילה וזהו בחי' שם מ\"ה"],[4101400092,"כמארז\"ל ע\"פ לא תאכלו על הדם קודם שתתפללו על דמכם, שקודם התפילה נק' דם משא\"כ אחר התפילה נק' אדם א' דם שממשיכי' בחי' א' בדם, ועולה מ\"ה ואתם קרוי' אדם בחי' מ\"ה, וזהו שיש יתרון המעלה בתפילה נגד התורה וכמ\"כ בהיפוך יש יתרון בתורה נגד התפילה, מעלת התורה היא שבה וע\"י מבררי' בחי' שם ב\"ן שנפל בשבירה, ומעלת התפילה שע\"י התפילה יגיע לבחי' שם מ\"ה שאח\"כ יכול לברר ע\"י התורה בחי' שם ב\"ן שנפל בשבירה, וזהו וכל בניך למודי הוי' א\"ת בניך אלא בוניך בניך הוא בחי' תפילה ובוניך הוא בחי' התורה, ופי' שע\"י בניך בחי' תפילה יגיע לבחי' שם מ\"ה ואח\"כ ע\"י בוניך בחי' תורה יברר בחי' שם ב\"ן כי בחכ' אתברירו כו'.\n<b>וזהו</b> ושבתה הארץ, כי הנה משה אמר האזינו השמי' ואדברה ותשמע הארץ אמרי פי, וישעי' אמר בהיפוך שמעו שמי' והאזיני ארץ כי פי ה' דבר, ואיתא בזוהר פ' האזינו דרפ\"ו, זכאה חולקי דמשה יתיר מכל נביאי עלמא כו' שמעו שמי' ישעי' דהוה יתיר רחיק ממלכא אמר שמעו שמי', משה דהוה יתיר קרוב לגבי מלכא כתי' האזינו השמי' כו' ר' יוסי אמר תו מה בין משה לישעי' משה אמר האזינו השמי' השמים שמי' עילאין אינון דאשתמודעין דאקרון שמא דהקב\"ה, ותשמע הארץ ארץ עילאה ההיא דאשתמודעא ואיהי ארץ החיים, בישעי' כתי' שמעו שמי' ולא השמי', האזיני ארץ ולא הארץ, ואינון שמי' וארץ תתאין כו', והענין הוא דהנה נבואת ישעי' הי' בבי\"ע לכן אמ' שמעו שמי' שהוא מרחוק כנ\"ל בזוהר והאזיני בארץ וגם אמ' שמי' וארץ ולא השמי' והארץ, והוא מפני שנבואתו הי' מבי\"ע והשמי' והארץ בה\"א הידוע מורה על שמי' וארץ דאצי' שהם ז\"א ומל', אבל משה הי' נבואתו מאצי' לכן אמר השמי' והארץ בה\"א הידוע וגם שהי' מקרוב כמ\"ש הזוהר לכן אמר ל' האזינו בשמי', וזהו ושבתה הארץ בה\"א הידוע, כי קודם שבאו בנ\"י לא\"י קיבלה הארץ מבי\"ע משא\"כ כי תבואו אל הארץ מיד ושבתה הארץ בה\"א הידוע שתקבל מבחי' מל' דאצי' ול' ושבתה היא כי הארץ היא בבחי' רצוא שתשוקתה לקבל מבחי' ארץ עילאה אבל אח\"כ כי תבואו כו' ושבתה שתנוח מהרצוא הנ\"ל ובזה מתורץ הקושיא הראשונה, דבאמת מיד כי תבואו ושבתה פי' שיגרמו היחוד זו\"נ ואינו קאי על שמיטה כ\"א כנ\"ל וד\"ל.\n<b>[הנחת כ\"ק אדמו\"ר מהר\"ש]\nבס\"ד</b>"],[4101400093,"<h3>זהר פ' אחרי תניא אמר ר\"י זמנא חדא</h3>\n<b>זהר</b> ח\"ג פ' אחרי מות דנ\"ט ע\"ב תניא אמר ר\"י זמנא חדא הוי צריכא עלמא למיטרא, אתו חבריא לקמי' דר\"ש ר' ייסא ור' חזקיא ושאר חברי' כו' פתח ואמר מה טוב ומה נעי' שבת אחי' גם יחד כו' ע\"ש ואתי מטרא וע\"ש, והקשה (אא\"ז הגאון ר' הזקן) דבימי התנאי' כשהיו צריכין למטרא הי' מתענים י\"ג תעניות כדאיתא במס' תעניות ע\"ש והכא מיד כשפתח ר\"ש בדרוש מה טוב ומה נעי' אתא מיטרא, ויובן בהקדם ענין תורה ותפלה, הנה תפלה נק' חיי שעה ותורה נק' חיי עולם פי' חיי שעה בחי' זמן שהוא החיות הנמשך לבחי' מל' אבל בחי' חיי עולם היא מדריגה היותר נעלה ומה גם כי חיי עולם פירושו בלי הפסק עולם מל' נצחיות ושרשו ממקום גבוה מאד כמ\"ש ואתה מרום לעולם ה' פי' שבחי' עולם היא מבחי' מרום ונמשך מבחי' אני ה' לא שניתי שבחי' עולם הוא אשר אין בו שינוים (בל\"א אוביק) שתמיד נמשך וזהו מבחי' לא שניתי כו', משא\"כ בחי' חיי שעה שהוא בחי' זמן (שיש בו שינוי' פעם כך כו' וע' בד\"ה קודש ישראל מענין הזמן ע\"ש).\n<b>ולהבין</b> ההפרש שבין תורה ותפלה הוא כמשל שני ב\"א זה עומד בגובה ההר וזה עומד בשפולי יש שני אופנים באופן יחודם היינו שזה שעומד למעלה ירד למטה או שיעלה זה שעומד למטה (כמ\"ש משל זה בשה\"ת ובד\"ה ואתחנן אל ה' ע\"ש באורך) וז\"ע תורה ותפלה כי הנה ע\"י התפלה יכול להיות עלי' מלמטלמ\"ע והיינו שיעלה התחתון לגבי העליון משא\"כ ע\"י עסק התורה הוא למעלה רק שצריך להמשיך מלמעלמ\"ט, וזה יותר בנקל להמשיך מלמעלמ\"ט משיתעלה מלמט\"ע וזה הי' בקשת מרע\"ה כמ\"ש בדרוש ואתחנן שהבאתי לעיל ע\"ש שרצה להמשיך כח בנש\"י שיוכלו להמשיך מלמעלמ\"ט ולא בדרך העלאה כי בדרך העלאה כתי' מי יעלה בהר ה' ומי יקום כו' נקי כפי' דוקא ובר לבב כו' ע\"ש והנה משה לא פעל בקשתו כמ\"ש שם כ\"א רק מי שתורתו אומנתו דוקא כגון רשב\"י וחביריו ע\"ש כו', דוגמא לזה יש ג\"כ הפרש בין ברכה לתפלה ברכה היא המשכה מלמעלמ\"ט כמ\"ש בברכת כהני' יברכך ה' וישמרך שהוא ל' ציוי שהכהני' מצוי' כביכול לה' שיברך וישמור את"],[4101400094,"ישראל והוא מפני כי בחי' ומדריגות הכהן הוא יותר גבוה מבחי' שם הוי' כידוע שאהרן הי' נצח דאבא ושם הוי' הוא ז\"א ולכן בחי' נצח דאבא מצוה לבחי' ז\"א, משא\"כ בחי' תפלה שהיא בבחי' העלאה כנ\"ל וד\"ל.\n<b>ומעתה</b> יובן מה שבימי התנאי' הי' גוזרין י\"ג תעניות כשהי' צריכין למיטרא כו' כי י\"ג תעניות הי' נגד ע\"ס דאצי' וג' עולמות בי\"ע ולכן ג' תעני' הראשוני' הי' אוכלי' משחשיכה משא\"כ עשרה תעניות האחרוני', כי ג' תעני' הראשוני' הם נגד בי\"ע משא\"כ עשרה תעני' האחרוני' הם נגד ע\"ס דאצי' (והוא ההעלאה מעשי' עד סוף האצי') וכ\"ז הוא מחמת שהי' בבחי' תפלה מלמטלמ\"ע אבל בחי' תורה שהוא מלמעלה למטה אינו צריך לכ\"ז ולכן מיד כשאמר דרוש מה טוב ומה נעים פי' שהמשיך בחי' ומדריגות התורה מיד אתהדרו אנפין באנפין, ופי' מה טוב, טוב הוא השפעה מבחי' ז\"א, ונעי' השפעה מבחי' בינה, שבת אחים יחוד דכר ונוקבא, גם יחד פי' שיומשך זה למטה בבי\"ע, ומעתה עדיין צ\"ל מה הי' צריך לבוא כל החבריא לר\"ש כי הי' יכול מצד עצמו כו' והוא כדי שיוכל להמשיך מלמעלמ\"ט הי' צריכין לרומם אותו ולהגביהו לשרשו ומקורו, והוא כדוגמת העלאת מ\"ן, וד\"ל.\n<b>[הנחת כ\"ק אדמו\"ר מהר\"ש]\nבס\"ד</b>"],[4101400095,"<h3>בהעלותך את הנרות</h3>\n<b>בהעלותך</b> את הנרות, הנה נש\"י נק' בשם נרות כמ\"ש נר מצוה ותורה אור והוא על שם כי הנר מאירה כו' וכמ\"כ בנש\"י הנה הנפש מאיר בהגוף, וגם כי הנר מתנענ' למעלה תמיד וכמ\"כ בנמשל הוא ענין הרצוא ושוב שחיות הנפש היא תמיד ברצוא ושוב. והנה יש ז' נרות והם כנגד הפסוק לך ה' הגדולה והגבורה והתפארת והנצח וההוד כו' שהם ז' מידות כו', ולהבין תחלה מדת הגדולה וע\"י מה ממשיכין בחי' גדולה יש בזה ג' אופנים הא' הוא ע\"י מדת הענוה כי במקום גדולתו שם אתה מוצא ענותנותו (והיינו מה שנק' בשם"],[4101400096,"גדולה זהו שאצלינו הוא בשם גדולה משא\"כ לפניו ית' זהו בחי' ענוה שמשפיל כו') וא\"כ צריכין לעורר מדת הענוה והוא ע\"י מדת הענוה למטה עי\"ז מעוררי' למעלה מדת הענוה וזהו מדת הגדולה שקורין למטה כו' כנ\"ל (והיא היא) והאופן הב' ע\"י מה ממשיכין מדת הגדולה הוא ע\"י דברי' שנקראין ג\"כ בשם גדול כמו מעשה גדול וגדול תלמוד שמביא לידי מעשה כמ\"ש במ\"א כי גדול הוי' ומהולל מאד וע\"י גדול זה ממשיכים בחי' גדולה (וכ\"ז צריך להיות בבחי' ביטול דוקא שילמוד לשמה כו' ולא בבחי' גדלות ח\"ו שהוא היפוך כו') ועי\"ל אופן ג' שע\"י ממשיכים ג\"כ בחי' גדולה כי הנה כתי' גדול הוי' ומהולל מאד בעיר אלקינו, והנה עיר אלקינו הוא צירופי אותיות התפילה וכידוע ממשל העיר שמצורף מכמה בתים ובית מהרבה אבני' שנק' אותיות וכמ\"ש בס\"י שתי אבני' בונות שתי בתים שלש אבני' בונות ששה בתי' כו' ע\"ש וזהו בחי' אותיות התפלה שנק' אבני' ובצירוף הרבה אבני' יחד עד שנעשה בחי' עיר וכתי' גדול כו' בעיר אלקינו היינו שבבחי' עיר אלקינו שורה בחי' גדול הוי' כו' ולכן כשעושי' בחי' עיר היינו ע\"י אותיות התפלה עי\"ז ממשיכי' בחי' גדולה (ויתכן לומר יותר אותיות התפלה (מאותיות התורה)\nכי עיר אלקינו היינו בחי' ירושלי' שהי' בה עיקר העבודה ע\"י הקרבנות דוקא ותפלות כנגד תמידין תקנו כו' לזה יתכן יותר לומר אותיות התפלה כו' וד\"ל).\n<b>והגבורה</b>, הנה ארז\"ל איזהו גיבור הכובש את יצרו שנאמר טוב א\"א מגיבור ומושל ברוחו מלוכד עיר כי הנה יש באדם מדות טבעי' וע\"י עבודתו כו' צריך להפוך אותה זהו בחי' גיבור כו' שכובש את יצרו והופך אותו כו' והנה ארז\"ל ביומא דף ס\"ט ע\"ב שגם הוא ית' כובש את יצרו כביכול (ובע\"י הגי' כעסו), ולכאורה יפלא איך שייך ל' כובש את יצרו למעלה והענין הוא כי יצרו קאי על מדת הגבורה והנה מתחלה צ\"ל מ\"ש הכובש את יצרו שנאמר טוב א\"א מגיבור דלכאור' זה אינו גבורה כלל כי אם אדרבה כובש את יצרו שהוא מדת הגבורה כו' וקושי' זו הקשה המדרש שמואל, והענין הוא דהנה מדת הגבורה הוא מדת הדין שהוא בחי' צמצום והנה למעשה מדת הצמצום היא היותר ועיקר המכון שיהפוך המידה כו' והיינו אף שהיא מדת הגבורה אעפ\"כ תתהפך כו' וזהו טוב א\"א מגיבור כו' והיינו בחי' מאריך אף (אף לרשעי') וממשיך מבחי' ומדריגות היותר נעלה כו' כידוע. וראי' לזה היא ממ\"ש ימי שנותינו בהם שבעי' שנה ואם בגבורות שמונים שנה ולכאו' יפלא איך שייך לו' שדרך שאר בני אדם לחיות שבעי' שנה ואם שנמשך מבחי' גבורה יכול לחיות פ' שנה הלא זה היפך ממדת הגבורה כו' והענין הוא כי ע' שנה כ\"א כלול מיו\"ד אבל בחי' פ' שנה היא למעלה מהמידות שהיא התגלות בחי' בינה שבה מאיר בחי' ע\"י וא\"א, וזהו אם בגבורות פ' שנה פי' כמ\"ש לעיל שפי' גבורה היינו בחי' מאריך אף כו' ולכן נמשך גם למטה השפעה יותר ולכן יכול לחיות שמונים שנה וד\"ל וכמ\"כ צריך האדם ג\"כ להאריך אף פי' להפוך המידות טבעי' כו'."],[4101400097,"<b>והתפארת</b>, זהו ענין לאסתכלא ביקרא דמלכא דהיינו שיתבונן ביקר תפארת גדולתו ית' וצריך לעורר ר\"ר והוא ע\"י התבוננותו על ריחוקו מהש' כי בי\"ה הוי' צור עולמי' וכמשל ב' אותיות לגבי הדיבור וכ\"ש לגבי כח המחשבה וכשיתבונן שלגבי דבר ה' כו' עי\"ז יתמרמר מאד על ריחוקו מאתו ית' כי הנשמה קודם התלבשותה בגוף האדם היתה עומדת לפניו ית' כו' משא\"כ כשנתלבשה בגוף כו' וצריך לעורר ר\"ר ע\"ז וע\"ז נופל רחמנות ביותר וכמשל העשיר שנעשה עני כו' שנופל עליו רחמנות יותר מעל שאר עניים כו' כמ\"ש מאחר שהנשמ' קודם התלבשותה בגוף הייתה עומדת לפניו ית' ועכשיו כו' וע\"ז נופל רחמנות יותר כו', וכשיתבונן בכ\"ז יהי' אצלו תשוקה נפלאה ליכלל אליו ית', וגם תפארת הוא שם הוי' כי הנה כתי' אל אלקי' הוי' שבחי' שם אל בחסד ושם אלקי' בגבורה ובחי' שם הוי' בתפארת קו האמצעי ואני הוי' לא שניתי כו', וגם תפארת ל' התכללות כו' בכמה גווני' ובריח התיכון המבריח מן הקצה אל הקצה כו'.\n<b>והנצח</b>, פי' גדולה היא בחי' אהבה כמ\"ש באברהם ואגדלה שמך שהוא בחי' אהבה כו' ונצח ענף האהבה והוד ענף הגבורה ושרשם גבוה מבחי' חו\"ג כו' שהם בחי' נו\"ה החדשים כמ\"ש בלק\"ת שה\"ש, וזהו בהעלותך את הנרות ויש בזה ב' פרושי' הא' בחי' העלאה כי לך הוי' הגדולה והגבורה כו' שמידת הגדו' והג' בטלי' לך ממש כו' כמ\"ש במ\"א וזהו בהעלותך את הנרות שצריך להעלות מידות אלו והפי' הב' כי הנה כתי' הבו גודל לאלקינו שצריכין להמשיך בחי' גודל היינו בחי' גדולה וגבורה כו' וצריך להבין איך שייך לומר שצריך לגדולה כו' והענין כי הנה יש פלוגתא בין המקובלי' הראשוני' והאחרוני' הראשוני' קורין מידת החסד בשם גדולה והאחרוני' קורין אותה בשם חסד והאריז\"ל הכריע שלפני האצי' נק' בשם גדולה ובאצי' נק' חסד וזהו הבו גודל לאלקינו שצריך להמשיך בחי' גדולה בחסד והיינו שצריך להמשיך ממידות שבכתר לז\"א, וזהו בהעלותך את הנרות כו'."],[4101400098,"<h3>ויאמר ה' אל אהרן כו' וילוו עליך</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>ויאמר</b> ה' אל אהרן אתה ובניך ובית אביך תשאו כו' וילוו עליך וישרתוך כו', כי הלוים היו טפלים לכהנים כמ\"ש נתונים נתונים המה כו' כי הלוים היו בבחי' העלאה יש להבין זה. והנה כמו שיש ירידה צורך עלי' כמ\"כ יש עלי' צורך ירידה. ירידה צורך עלי' היינו כמו הנשמה בגוף האדם כו' כידוע והעלי' צורך ירידה יובן מענין הזמן שבכל יום מאיר הארה חדשה מאתו ית', והוא ע\"י עליות הארה שהאיר ביום זה עי\"ז יורד הארה חדשה כמשי\"ת אי\"ה. וכמ\"כ למעלה ג\"כ מאיר בבחי' זמן הארה חדשה בכל יום כו' כי למעלה יש ג\"כ זמן כמ\"ש אלף שנים בעיניך כיום אתמול כו'.\n<b>ולהבין</b> איך שייך בחי' זמן למעלה כו' הענין הוא דהנה בבי\"ע יש זמן כו' כידוע וקודם האצי' אינו שייך לומר בחי' זמן כלל כו' ואיך יהי' בחי' זמן בבי\"ע הוא ע\"י אצילות שנק' סדר זמנים והוא ע\"ד מה דאיתא במדרש מכלל שיש סדר זמנים קודם לכן ויש שרצו להוכיח מכאן שדעת המדרש כמו דעת האומרים שהזמן אינו מחודש, אך באמת אינו כן כי הזמן הוא מחודש ויש ע\"ז כמה ראיות כמ\"ש במ\"א. והענין שקאי על בחי' אצי' שנק' סדר זמנים שהוא מקור ושרש לבחי' הזמן דבי\"ע ואינו בבחי' זמן ח\"ו והוא בחי' ששה מדות דאצי'. והנה ע\"כ כיון שיש מדת החסד א\"א שיהי' גם מדת הגבורה בנושא א', כ\"א שמתחלה חסד ואח\"כ גבורה, כמו שמצינו בנין בהמ\"ק הוא מדת החסד והיפוכו הוא חורבן בהמ\"ק בבחי' הגבורה וא\"א להיות שניהם בנושא א'. ולכן דור אנוש אף שהיו עוכומ\"ז אעפ\"כ היו ניזונים בחסדו של הקב\"ה והיינו מפני שהי' מאיר מדת החסד כל אלף שנים הראשוני' שהם נגד יום א' כמ\"ש אלף שנים בעיניך כיום אתמול. והיינו שיום א' אלף שנים, ולכן היו אלף שנים הראשונים שהם נגד יום א' שמאיר בו מדת החסד כידוע, הי' כל כולו חסדים (היינו כל אלף שנים) ולהיפוך אלף שנים הב' היו בו גבורות קשות עד מאד. כמו מי המבול ודור הפלגה והפיכת סדום. והוא מפני שהם נגד יום ב' שמאיר בו מדת הגבורה. ולכן הי' כולו גבורו'. וכמ\"כ בשאר הימים כמו יום השלישי הי' מ\"ת, והנה מצינו שארז\"ל שהתורה קדמה לעולם אלפים שנה שנאמר ואהי' אצלו שעשועים יום יום ויומו של הקב\"ה אלף שנה, הנה בחי' יום זה הוא מדריגה היותר נעלה, כי התחלת השייכות לעולמות הוא מבחי' חסד ולמטה כמ\"ש כי אמרתי עולם חסד יבנה, ובחי' יום זה הוא קאי על חו\"ב שנקראי' ג\"כ יום יום, ואינו כמו בחי' יום של אלף שנה שמבחי' חסד"],[4101400099,"ולמטה, כי אינו שייך לעולמות כלל, ואעפ\"כ נק' ג\"כ יום יום (ואפשר שקאי על יחוד חו\"ב חיצוני כו') והנה מבואר שכל מדה בפ\"ע לכן היא השרש והמקור דבחי' זמן כי בחי' זמן הוא מוגבל שביום זה כך וביום זה כך (בל\"א וואש פריער איז ניט שפעטיר) וזה שמדות דאצילות נק' בשם סדר זמנים שהם סדר ומקור לבחי' זמן ובכל יום העליות ההארה שהאיר ביום זה והוא כדי שיומשך ביום מחר הארה חדשה נמצא שהירידה צורך עלי' (וכמו\"כ בכל שעה וגם בכללות השנים ג\"כ עליות המל' בר\"ה כדי שיומשך הארה חדשה לשנה הב' כידוע) והארה הנמשכת ביום מחר אינו הארה זו עצמה שהאיר ביום שלפני יום זה כ\"א הארה חדשה וגבוה מבחי' הארה שהאיר ביום אתמול, אך היא ג\"כ מבחי' ומדרגה זו שהאיר ביום אתמול, כי יש כמה אלפים רבבות מדרגות בספי' זו, כמו שבשבת מאיר ממוחין דאבא, ובשבת הבא היא ג\"כ הארה ממוחין דאבא, אך עכ\"פ היא היותר נעלה על הארה שהאיר בשבת שלפניה, ומ\"מ הוא ג\"כ בחי' מוחין דאבא והוא לפי שבבחי' זו יש ג\"כ כמה חילוקי מדרגות, וכמו\"כ יובן גם ביום א' אף שמאיר בכל יום הארה חדשה אעפ\"כ הוא ממדת החסד, וכמו\"כ ביום ב' ושאר הימים כו').\n<b>וזהו</b> ענין לוים וכהנים שעליות הלוים הוא כדי שיהי' המשכת הכהנים ע\"י עבודתם כמשי\"ת לקמן אי\"ה. כי הלוים הי' בבחי' העלאה מלמטה למעלה בחי' שיר כמ\"ש ועבד הלוי הוא שמחבר עלמא דאתגלי' בעלמא דאתכסי' (וזהו לוי מלשון לויתן זה יצרת לשחק בו שהוא לשון חיבור כו') כי הנה כתיב אתה הוי' לבדך פי' לבדך שאין עוד כו' וצריך להיות ברעש מאחר שהוא לבדך ואין עוד, וזהו מעלת ומדרגת הלוים, כי הנה יש אנשים אף שאומרים אתה הוי' לבדך, אעפ\"כ אינם מתפעלים מזה כלל מחמת שהן בבחי' קרירות, משא\"כ הלוים שמתבונני' בבחי' לבדך כו', וההתפעלות נמשך מבחי' השיר והניגון, וכמשל הניגון אף שאינו דבר חדש אעפ\"כ כשמשוררים הניגון מתפעלים יותר מכמה שהי' קודם הנגינה, כמו\"כ הלוים ע\"י שירם וזמרם היו מתפעלים מאד, ואין אומרים שירה אלא על היין שהוא בחי' בינה, כי היין הי' מתחלה כנוס בענבים ואח\"כ יוצא מהעלם אל הגילוי כמו\"כ יוצא ההתפעלות מהעלם אל הגילוי שמתפעל ממה שאתה הוי' לבדך, והוא מדרגה גבוה מאד (וזהו הי' טעות של קרח שחשב שזה הוא מדרגה היותר נעלה אף מבחי' כהנים שעבודתם בחשאי כמשי\"ת), ועבודת הכהנים בחשאי דוקא ואינו בבחי' קרירות ח\"ו, אלא שזהו מדרגה היותר נעלה שעבודת הכהנים בחשאי פי' בחי' פנימיות הלב שהוא בחי' שפיכת הנפש (וכמו ותתפלל חנה על הוי' וכמ\"ש במ\"א) שהוא ביטול הנוגע לעצמות נקודת נפשו ולא הי' צריכים להתעוררות הניגון כמו למשל למי צריך לעורר היינו מי שאינו נוגע לו כ\"כ לעצמותו משא\"כ מי שנוגע לו בנקודת פנימיותו אין צריך לנגינה כלל כ\"א שמתעורר מצד עצמו, ולכן נאסר בחי' יין לכהנים שאין צריכים להתעוררות וגם כי הם במדרגה היותר נעלה כו' כמ\"ש לעיל וזה הי' עיקר המכוון כי נתאווה הקב\"ה להיות לו"],[4101400100,"דירה בתחתונים דוקא כידוע, ועיקר המשכה למטה הוא ע\"י הכהנים דוקא, אך כדי שיהי' ההמשכה ע\"י בחי' כהנים צ\"ל תחלה עלי' מבחי' לוים שהעלי' הלוים גורם המשכת כהנים וזהו ענין תפלה ותורה, תפלה הוא בחי' העלאה מלמטה למעלה ותורה המשכה מלמעלה למטה ואעפ\"כ הלוים בטלים וטפלים לכהנים כמ\"ש נתונים נתונים כו' וילוו עליך וישרתוך כי העלי' של הלוים הוא ג\"כ ע\"י הכהנים כי אהרן הי' צריך לסדר להם סדר משאם כו' כמ\"ש ולא יבואו לראות כבלע את הקודש כו', ובעבודה זה שצריך להיות קודם התפלה בחי' מצות כמו לבישת טו\"ת כי בלא טו\"ת לא יהי' ההעלאה ע\"י התפלה כדוגמת שלצורך עליות הלוים צריך להיות תחלה בחי' כהנים, ואח\"כ ע\"י עליות הלוים גורם המשכת הכהנים, וזהו עלי' צורך ירידה כו' וד\"ל."],[4101400101,"<h3>קדש ישראל לה'</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>קדש</b> ישראל לה' ראשית תבואתה. וצ\"ל מהו ענין התבואה ושישראל נק' ראשית תבואתה וע\"ז כתיב בתחלת הפסוק קודש כו'. הנה התורה נק' בשם תבואה כי חטה גימ' ך\"ב אתוון דאורייתא וגם נק' לחם כמ\"ש לכו לחמו בלחמי וגם נק' שמן וחלב כו' הרי נק' התורה בשם תבואה וישראל הם ראשית התבואה, דהנה כל או\"א מישראל צריך לקיים תרי\"ג מצות וכדי שיקיים אף מצות שנאמרו בכהן צריך להיות בגלגול עליהם כו' והנה המצות הם לבושים (וכשחסר מצוה א' חסר לבוש א') ויש שני בחי' בעשיי' המצות, והיינו עשיית המצוה וכוונת המצוה, והוא כי בעשיית המצוה נעשה לבושי' לג\"ע התחתון ובכוונת המצות נעשה לבושי' לג\"ע העליון כו', והנה המצות נקרא בשם זריעה כמ\"ש זרעו לכם לצדקה, זורע צדקות. ולהבין מהו שייך לשון זריעה במצות הנה ארז\"ל נתאוה הקב\"ה להיות לו דירה בתחתונים ולכאורה צ\"ל הלא את השמים ואת הארץ אני מלא. וכדוגמת זה צ\"ל מ\"ש ועשו לי מקדש ושכנתי בתוכם שיהי' השראת אלקות בבהמ\"ק בקדה\"ק, ולכאורה גם בזה צ\"ל הלא"],[4101400102,"מכה\"כ לית אתר פנוי מיני' ומה ההתחדשות שיהי' כבוד ה' מלא את המשכן הלא בלא\"ה מכה\"כ את השמים ואת הארץ אני מלא כו', כי הנה אנו רואים שהנפש שורה במוח, והנה אעפ\"כ אנו רואים שאם רוצה להלוך ברגל הנה תיכף הוא הולך ואם הי' השראת הנפש בלבד הי' צריך להיות שיהוי איזה זמן מה, והענין הוא דהנה הנפש שורה בכל רמ\"ח איברים אף ברגל ג\"כ ולכן מיד כשעולה ברצונו להלוך אינו צריך שיומשך הרצון לרגל ע\"י העורקים כ\"א מיד הוא מהלך והוא מפני שברגל יש ג\"כ כח הנפש שמתפשט בה כו'. והנה עכ\"ז אנו רואים שעיקר השראת הנפש המשכלת על דבר שיהי' כך כו' הוא במוחו דוקא משא\"כ ברגל כמו אם צריך לחשוב איזה דבר הנה הוא מחשב במוחו ויכול לחשוב גם בגדולת אלקותו ית', וכמ\"כ בעניני מסחור משא\"כ ברגל כו'.\n<b>ולהבין</b> זה הנה יש שני אופנים בזה דהנה אף שהנפש מתפשטת בכל הרמ\"ח איברים אעפ\"כ אינו מאיר כ\"א בבחי' העלם כמו בבהמה אף שיש בה ג\"כ נפש אעפ\"כ אינו יכולה להשכיל ע\"ד וזה מה שבה נפש הבהמה אבל באדם אף שיתפשט נפש השכליות אעפ\"כ אינו אלא בחי' העלם, משא\"כ מה שמאירת במוח היא בבחי' גילוי ולכן מצינו בספר הגלגולים שבאיזה חטא נפש האדם מתגלגלת בבהמה ואף שבבהמה ודאי אינה יכולה להאיר בבחי' גילוי מאחר שאין בה הכלי להכיל גילוי אור הנפש אעפ\"כ מתגלגלת בה והיינו שאינו אלא בבחי' העלם, וכמו בתינוק קטן שמיד כשנולד יש בה הנשמה אעפ\"כ אין בו שכל כלל והוא מפני שאין הכלי שלו יכול להכיל אור הנפש וכמ\"כ יובן למעלה מ\"ש את השמים ואת הארץ אני מלא מלכה\"כ היינו כ\"א בבחי' העלם משא\"כ כשהי' מאיר בקה\"ק גילוי אלקותו ית' היה מאיר בבחי' גילוי כו' ומפני זה הי' מאיר גם בכל א\"י בחי' היותר נעלה מחו\"ל ולכן כתיב במשה וידבר ה' אל משה כו' פב\"פ אדבר בו כו' ובשאר הנביאים כתיב ואראה את הוי' והוא מחמת גילוי שבא\"י כו' רק משה נתנבא בזה וכל הנביאים נתנבאו בכה אספקלריא שאינה מאירה כמו דרך המראה משא\"כ משה נתנבא בזה אספקלריא המאירה כמו דרך זכוכית לבנה ובהירה כו', והנה נתאוה הקב\"ה להיות לו דירה בתחתונים דוקא והיינו שיהי' הגילוי כמו בבהמ\"ק גם למטה לזה צריך כאו\"א מישראל להמשיך בחי' זו מהעלם אל הגילוי. וזהו שצריך כאו\"א מישראל לברך מאה ברכות בכל יום כי ברכה היא המשכה מהעלם אל הגילוי, והנה כ\"ז הוא בבחי' דיבור משא\"כ בבחי' מעשה היינו עשיית המצוה גשמיי' עי\"ז ממשיכים יותר (ולכן המרגלים לא רצו לעלות לא\"י מפני כי רצו להמשיך בחי' ומדרגה זו ע\"י בחי' דבור ובחי' מחשבה ולכן רצו במדבר דוקא ולא בארץ כי מדבר לשון דבור ולא מעשה, וכוונתם בזה כי ע\"כ עשיי' המצוה כמו צדקה צריך להשפיל תחלה כמו לעשות איזה מסחור שהוא היפך מהמצוה אלא שאח\"כ עושה במה שמרויח איזה מצוה כמו צדקה ובין כך הוא משפיל א\"ע ויראו המרגלים שבין כך יכולים ליפול כו' כמ\"ש ארץ אוכלת יושביה (לפי פי' א') אבל באמת טעו בזה כי דוקא ע\"י עשיית המצוה גשמיי' עי\"ז ממשיך"],[4101400103,"בחי' ומדרגה היותר נעלה אף שמשפיל א\"ע אעפ\"כ אח\"כ בעשיית הצדקה כו' כנ\"ל), ולכאורה צ\"ל איך ע\"י מצוה גשמיי' כמו תפילין ממשיכים ד' מוחין והוא ע\"י שיש בהם ד' בתים שרומזים לבחי' חב\"ד (ודעת נחלק לחו\"ב).\n<b>והענין</b> הוא דזהו שנק' המצות בשם זריעה דהנה למשל הגרעין שזורעין אותו אין בו הציור מהאילן והפרי שצומח ממנו וכן אין בו כלל ריח וטעם הצומח ממנו כי רוב מיני זריעה הוא זרעונים גינה שאין נאכלין כלל וגם זרעוני תבואה הנאכלים אעפ\"כ ע\"י הזריעה ניתוסף התבואה כהנה וכהנה וכמ\"כ המצוה אף שאין בה כלל מענין וציור לדוגמתה שלמעלה אעפ\"כ עי\"ז ממשיכים בחי' ומדרגה זו והוא מפני שמרומז בה המדרגה הנ\"ל כמו המפה שמציין בה כל הארץ והנחלים ובארות הנה זה שלא בערך כלל ואעפ\"כ מבינים ממנה המבין בציור העולם כו', וכמו טפה הנמשכת ממוח האב הנה אין בה ציור הגוף כלל ואעפ\"כ נתהוה מטפה הנמשכת ממוח האב והאם כו' וכמ\"כ יובן למעלה אף שהמצות הם שלא בערך כלל ואינו ענין שלמעלה כלל אעפ\"כ ממשיכין עי\"ז כו'.\n<b>והנה</b> הזריעה צריך להיות בארץ דוקא, וגם יש הפרש בארץ גופא כי בארץ אשר אינה טובה לא יצמח בה כלל כמו במדבר לא יצמח כלל או בארץ יבשה פי' קשה כו' וכמ\"כ בנש\"י כתי' כי תהיו אתם לי ארץ חפץ פי' הארץ שבכם היא בבחי' חפץ שהיא בחי' פנימיות דהיינו בחי' ארץ הטובה שראוי לצמיחה וזהו קודש ישראל לה' ראשית תבואתה, פי' תבואתה הוא בחי' הנמשכת ע\"י תומ\"צ וראשית תבואתה היינו כמו שבחי' ארץ היא ראשית מהתבואה כי בלא הארץ לא יצמח כלל, כמו\"כ נש\"י הם ראשית מהתבואה כי ע\"י נש\"י דוקא נמשכים בחי' אלו (ולא ע\"י אחר שיניח תפילין למשל) והוא מפני שנש\"י הם בבחי' ביטול בחי' קבלת עומ\"ש וכמארז\"ל למה קדמה שמע לוהי' אם שמוע כדי שיקבל עומ\"ש תחלה ואח\"כ יקבל עול מצות, פי' שבתחלה צריך הקבלת עול מ\"ש שהוא בחי' ארץ בחי' ביטול ואח\"כ עול מצות היינו הצמיחה (מאי פירי מצוה) ונבוא לבחי' ביטול זה ע\"י שיתבונן שעצמותו ומהותו מובדל ומרומם מערך העולמות ואינו [אלא] מחמת שעלה ברצונו אנא אמלוך כו' לזה צריך להיות בטל רצונך כו'.\n<b>וזהו</b> קודש ישראל לה' ראשית תבואתה שנש\"י הם ראשית התבואה ולכן כתיב קודש ישראל ע\"ד מ\"ש כי עם קדוש אתה לה' אלקיך, פי' עם הוא כי אין מלך בלא עם שהעם הוא בחי' נפרד מהמלך כידוע שעל בחי' בן אינו שייך בחי' מלוכה מאחר שהוא אחד ואינו שייך כ\"א על עם נפרד כו' והנה פי' עם הוא ג\"כ מל' עוממות כמ\"ש בת\"א ע\"פ לא כהתה עינו ולא נס ליחו לא עממיא עיני וכן ע\"פ ותכהינה עיני יצחק ועממיא עיני (והוא ע\"ד יד כהה), כי הנה יש גחלי' לוחשות פי' שהשלהבת קשורה בהם וגחלי' עוממות היינו"],[4101400104,"שנפסקה השלהבת ואעפ\"כ הם בוערי' וכמ\"כ למעלה כתי' בס\"י ע\"ס בלי מ\"ה כשלהבת הקשורה בגחלת, אבל בחי' עוממות אינו כן וכמ\"כ בנש\"י אף שהם נפרדי' אעפ\"כ צריכין להיות בבחי' ביטול קבעמ\"ש ע\"ד כמו למעלה כתי' ומשם יפרד שהם נפרדי' ואעפ\"כ כתי' והשרפי' בוערות ואומרי' קדוש שרוצי' ליכלל פי' השרפי' שהם בעולם הבריאה ומשם יפרד אעפ\"כ צועקי' ורוצי' ליכלל וזהו בחי' רצוא וכמ\"כ נש\"י אף שהם בחי' עם נפרדי' אעפ\"כ צ\"ל בבחי' ביטול והיינו בחי' קבלת עול בחי' רצוא ואח\"כ השוב הוא בחי' מצות.\n<b>וז\"ש</b> קודש ישראל לה' ולכן הם ראשית תבואתה, וכ\"ז יהי' הגילוי לע\"ל ע\"י המצות אבל כעת אינו מאיר בגילוי אור המצות כמשארז\"ל שכר מצוה בהאי עלמא ליכא ואעפ\"כ מאירים בבחי' מקיף כמו שמצינו במארז\"ל ג\"כ מצוה מגיני ומצלי והוא מה שלע\"ל יהי' בבחי' גילוי מאיר כעת בבחי' מקיף, והיינו כי לע\"ל יבוא המקיף להיות בבחי' א\"פ, וזהו שהמשיל תחלה המצות ללבושים והיינו שהם בבחי' מקיף כמו הלבוש שהוא בבחי' מקיף ויש שני בחי' עשיית המצוה וכוונת המצוה לבושי' לג\"ע התחתון וג\"ע העליון פי' אף ששם הם ג\"כ בבחי' לבושים אעפ\"כ אינם כמו לבושי' שלמטה כ\"א מאירים מה שרואים דרך אספקלריא או כמו שאומרים משל לשכל שהמשל ענין זר אעפ\"כ מביני' השכל ממנו, נמצא ג' מיני לבושי' שבג\"ע העליון מאיר מבחי' לבושים המאירים מבחי' כוונת המצוה ובג\"ע התחתון ג\"כ מבחי' לבושים המאירים אבל מבחי' עשיית המצוה ובעוה\"ז השפל אינו מאיר כלל כ\"א בבחי' מקיף ולע\"ל כשיתגלה יהי' מצוה כמו פרי וכמ\"ש בת\"א בד\"ה הבאים ישרש כו' ע\"ש."],[4101400105,"<h3>קול מצהלות חתנים</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>קול</b> מצהלות חתנים מחופתן ונערים ממשתה נגינתם, וצ\"ל מ\"ש נערי' ל' רבי', הנה יהושע נק' נער כמ\"ש ומשרתו יהושע בן נון נער לא ימיש מתוך האהל, והנה מצינו ביהושע שהי' בו שני מדרגות הא' כמו שהי' מתחלה מקבל ממשה והב' הוא כשנעשה אח\"כ משפיע בפ\"ע והי' מנהיג את ישראל כמ\"ש וצו את יהושע וחזקהו ואמצהו, והנה אף שלכאו' הנה מדריגה הב' היינו"],[4101400106,"מה שנעשה אח\"כ לבחי' משפיע בפ\"ע היא יותר גבוה אך באמת המדריגה הא' מה שהי' מקבל תמיד ממשה רבו היא היותר נעלה כמשי\"ת אי\"ה, וזהו שארז\"ל הוי זנב לאריות ואל תהי ראש לשועלי' (פי' זנב לאריות היא כמו שהי' מקבל ממשה רבו וראש לשועלי' הוא כמו שהי' אח\"כ בחי' משפיע בפ\"ע).\n<b>והנה</b> דרך כלל משארז\"ל הוי זנב לאריות ואל תהי' ראש קאי על מל' דאצי' שיש בה ג\"כ שני מדריגות הנ\"ל היינו שהמל' הוא שורש ומקור לעולם הבריאה וכמ\"ש בכהאריז\"ל מל' דאצי' נעשה כת\"ר לבריאה, והב' הוא כמו שהוא באצי' קודם שנעשה ע\"י לבריאה, וע\"ז ארז\"ל הוי זנב לאריות ואל תהי ראש לשועלי' פי' שזה שהמל' היא זנב לאריות הוא יותר נעלה מכמו שנעשית אח\"כ ראש לשועלי' היינו ע\"י דבריאה, והטעם הוא לפי שהיא באצי' ואף שהיא מדריגה תחתונה היינו הספי' העשירי אעפ\"כ היא באצי' משא\"כ כשנעשי' ע\"י לבריאה כו'. ויובן ממשל זיו השמש אף שהיא מאיר לארץ ולדרי' עלי' אעפ\"כ בעת שהזיו כלול בשמש הוא יותר נעלה והיינו מפני שהוא כלול בעצם המאור, וכן יובן מענין יחוד שמשא וסהרא הנה בעת שהלבנה מקבלת הארתה מהשמש היא במדריגה היותר נעלה (מכמו אח\"כ שמאיר' על הארץ), שמתיחדת עם השמש ומקבלת הארה ממנה משא\"כ מה שמאיר' אח\"כ ונק' הארה דהארה כידוע, וכך למעלה הנה כתי' שמש ומגן ה' אלקי' וזה ששם אלקי' מקבל משם ה' הוא יותר גבוה כו' שנעשה יחוד ה' ואלקי' משא\"כ אח\"כ ע\"י שם אלקי' נראה העולם ליש ודבר נפרד כנ\"ל, וכמ\"כ יובן בענין יהושע שנק' נער כשהי' מקבל ממשה רבו הי' ג\"כ במדריגה היותר נעלה כי הנה ארז\"ל פני משה כפני חמה ופני יהושע כפני לבנה וכמו שהלבנה בעת שהיא מקבלת הארתה מהשמש היא במדריגה יותר גבוה כמ\"כ יהושע בעת שהי' מקבל ממשה רבו הי' יותר נעלה שהי' מקבל תמיד מבחי' משה שמש ה' כו', ואח\"כ כשנעשה משפיע בפ\"ע הי' ע\"ד כמו הלבנה בעת שהיא משפעת ומאיר' על הארץ ואינו דומה כו'.\n<b>והנה</b> למעלה נק' מלאך מט\"ט בשם נער כמ\"ש נער הייתי גם זקנתי וארז\"ל שרו של עולם אמרו, שהוא מט\"ט, וע\"ד הקבלה מט\"ט ו\"ק דיצירה, והנה יש בזה ג\"כ שני בחי' הא' היא היינו כשו\"ק דיצירה מקבלי' מאצי', והב' היינו כמו שהם עצמן ומשפיעין למטה כו' ולכן יש מיט\"ט מלא ביו\"ד אחר המ' (מיט\"ט) ויש בלא יו\"ד (מט\"ט) והיינו בעת שהוא מקבל מאצי' נק' מיט\"ט ביו\"ד (כי יו\"ד היא השפעה מאצי' יו\"ד חכ' כו', בפרד\"ס שער אבי\"ע פ\"ד המל' כשהיא כלולה מכל הע\"ס דאצי' נק' יו\"ד וכשמתלבש' במט\"ט אזי נק' מיט\"ט ביו\"ד) ובעת שהוא משפיע למטה נק' מט\"ט בלא יו\"ד (וכמ\"ש בזהר ח\"ב דפ\"ח ע\"א וכ\"כ בזהר ח\"ב דס\"ג ע\"ב דההוא יומא מתברכין מיני' כל שית יומין וכל חד יהיב מזונא לתתא כל חד ביומוי, מההי' ברכה דמתברכי' ביומא שביעאה, אלא שיש באצי' ג\"כ בחי' זו והיינו שג' מידות דאצי' מקבלי' מיומא שביעאה היינו"],[4101400107,"בחי' בינה, ופי' נער שההשפעה הוא בבחי' קטנות ע\"ד אתווין רברבין אתווין זעירין פי' שאתווין זערין הוא כמו אתווין רברבין אלא שהם בצמצום וכמ\"כ בחי' נער הוא שההשפעה בקטנות).\n<b>והנה</b> במשה כתי' הנה אנכי שולח מלאך כו' אל תמר בו כו' כי שמי בקרבו כו' כי ילך מלאכי לפניך (וארז\"ל שמי בקרבו זה מט\"ט ששמו כשם רבו, מט\"ט גימ' שד\"י) ולא רצה משה לקבלו כמ\"ש אם אין פניך הולכי' כו', פי' ששלח מלאך בחי' מט\"ט כמו שהוא מקבל מאצי', וזהו מלאכי, כי שמי בקרבו שם שדי בקרבו והיינו כמו שהוא מקבל מאצי', ואעפ\"כ לא רצה משה לקבלו והיינו לפי שפני משה כפני חמה שמש ה' היינו בחי' אצי' לכן לא רצה לקבל המלאך כי המלאך הי' מקבל מאצי' משא\"כ משה הי' בחי' שמש ה' בחי' אצי' עצמו שהיא מדריגה היותר נעלה כו'. אבל ביהושע (ה' י\"ד) כשבא אליו המלאך כתי' שר צבא ה' עתה באתי ויפול יהושע על פניו ארצה וישתחו, ופרש\"י עתה באתי לעוזרך אבל בימי משה רבך באתי ולא חפץ בי שנא' ע\"ש, פי' יהושע שהי' בחי' נער כמו שהוא בחי' משפיע (ולא כמו שהוא מקבל כנ\"ל) לזה כשבא אליו המלאך בחי' נער כמו שהוא מקבל מאצי' כמ\"ש שר צבא ה' קיבלו יהושע ואף שהמלאך הי' ג\"כ בחי' נער אעפ\"כ הי' בחי' נער כמו שהוא מקבל מאצי' וכנ\"ל.\n<b>וכ\"ז</b> הי' בימי משה ויהושע כו' אבל עכשיו כתי' (ישעי' ג' ד') ונתתי נערי' שריהם פי' נערי' קאי על מט\"ט וסנד\"ל. מט\"ט ביצירה וסנד\"ל בעשי' (כי בח\"ל אינו מאיר כ\"א מעשי' כידוע) ושני בחי' אלו הם רק מבחי' נער כמו שהוא בפ\"ע ולא כמו שהוא מקבל מאצי' כו'. אך מ\"מ השפעה זו היא גבוה מכל שאר ההשפעות כי שאר ההשפעות הוא מע' שרי' משא\"כ בחי' ההשפעה לישראל היא מבחי' מט\"ט שהוא כולל ע' שרי' ולכן נק' שרו של עולם שהוא הכולל כל השרי' כו' ולכן כתי' כי מלאכי' יצוה לך לשמרך שהם בבחי' שומרי' בחי' מקיפי' כמ\"ש אמר שומר אתא בוקר (ישעי' ך\"א י\"ב) ואיתא בזהר שקאי על מט\"ט, ששומר את ישראל כו'.\n<b>והנה</b> כתי' סולם מוצב ארצה וראשו מגיע השמימה והנה מלאכי אלקי' עולי' כו' פי' סולם נק' יעקב שיעקב ראה את הסולם (וגם כמו שהסולם מחבר כמ\"כ יעקב בריח התיכון בחי' מחבר) והנה עלית נש\"י הוא ע\"י הסולם ובהעלאתם מגביהים ג\"כ בחי' מט\"ט וסנד\"ל והוא מפני כי נש\"י מקבלי' ההשפעה ע\"י השרי' הנ\"ל לכן כשנ\"י מתעלי' מתעלי' ג\"כ השרי' וזהו והנה מלאכי אלקי' פי' בחי' מט\"ט וסנד\"ל עולי' דרך הסולם פי' בעלית נש\"י.\n<b>והנה</b> עיקר העלי' יהי' לע\"ל אעפ\"כ אין עליתן שוה והיינו שנש\"י מתעלי' יותר, וזהו קול מצהלות חתני' מחופתן חתן נק' נש\"י ע\"ש ביום חתונתו"],[4101400108,"זו מ\"ת וישראל קיבלו את התורה ועליתן היא לבחי' חופה וזהו מחופתן. וביאור הענין הנה איתא במדרש נש\"י עלו במחשבה ולכאו' צ\"ל מהו הרבותא שעלו במח' הלא מחשבה היא בחי' לבוש, והענין הוא דהנה מצינו שמח' נק' חכ' (וע' בד\"ה פתח אלי' בענין לית מח' תפיסא בי' ובזהר ח\"א דקכ\"ג ע\"א מח' ויובלא שהוא חו\"ב ע\"ש) ועלו במח' מקור המח' שהוא בחי' פנימיות החכ', ולכן עליות נש\"י הוא לבחי' מקיפי' דחכ' וזהו מחופתן, כי הנה כתי' כי על [כל] כבוד חופה כבו\"ד גימ' ל\"ב והוא ל\"ב נתיבות החכמה וחופה היא בחי' מקיף ולכן עליות נש\"י בבחי' מקיף דחכ' וזהו מצהלות חתני' מחופתן.\n<b>ונערי'</b> ממשתה נגינתם, פי' כי שרש הנערי' שהם המלאכי' הם מבחי' דיבור ושורש הדיבור הוא מבחי' בינה שנק' ספר (ואף כי שרש הדיבור הוא מחכ' אך י\"ל כי זהו ע\"ד מ\"ש בסש\"ב שחכ' הוא בחי' כח החכ' כו' ע\"ש) ולכן עליתן לבחי' מקיף דבינה וזהו ונערי' ממשתה נגינתם פי' משתה הוא משתה היין יין הוא בחי' בינה וכתי' נכנס יין יצא סוד, סוד ה' ליראיו, וע\"ז כתי' יין המשמח אלקי' ואנשי' אנשי' היינו בחי' מט\"ט וסנד\"ל ומשמח ג\"כ בחי' אלקי' כי יש יין המשכר ויש יין הנק' יין המשומר בענביו יין בחי' גילוי שם ה' סוד ה' ועי\"ז משמח אלקים כי אלקי' הוא בחי' הסתר וע\"י גילוי בחי' שם הוי' משמח אלקי' כי נכנס יין יצא סוד כו' כנ\"ל, אך יש בחי' יין המשומר בענביו משי\"ב שהוא בחי' מקיף דבינה (וכמ\"ש בע\"ח התגלות ע\"י בבינה), וזהו פי' ונערי' מט\"ט וסנד\"ל ממשתה נגינתם שעליתן הוא לבחי' משתה היין בחי' בינה יין המשומר בענביו כו'.\n<b>ובזה</b> יובן מארז\"ל ע\"פ עין לא ראתה (ברכות ל\"ד ע\"ב, פסחי' ס\"ח, חלק צ\"ט ע\"א) אריב\"ל זה יין המשומר בענביו משי\"ב, ר\"ש בר נחמני (או ר\"ל) אמר זה עדן שלא שלטה בו עין כל ברי' כו' שמא תאמר ג\"ן זה עדן ת\"ל ונהר יוצא מעדן, לדברי ריב\"ל שמפרש יין המשומר בענביו קאי על עלית הנערי' הנ\"ל ולר\"ש בר נחמוני שמפרש זה עדן קאי על עלית נש\"י כי עלית נש\"י הוא לבחי' מקיף דחכ' שהוא בחי' ח\"ס חכ' דכת\"ר וזהו ויטע ה' אלקי' גן בעדן מקדם קדם בחי' כתר בעדן מקדם היינו בחי' חכ' שבכת\"ר שהוא עליות נש\"י כנ\"ל וד\"ל."],[4101400109,"<h3>עלה ראש הפסגה</h3>\n<b>עלה</b> ראש הפסגה, פי' פסגה הוא הר גבוה כמ\"ש בת\"א רמתא, והנה בס' פנים יפות פי' פסגה הוא ס\"ג פ\"ה שעליית משה הי' בבחי' שם ס\"ג שהוא בחי' בינה כמשי\"ת, ופה הוא כי הנה אלקים גימטרי' פ\"ו, וידוע שהוי' בניקוד אלקים הוא ג\"כ בחי' בינה, והנה כתי' ותחסרהו מעט מאלקים שמשה לא השיג כל הנש\"ב כ\"א מ\"ט שע\"ב ולכן כתי' פסגה ס\"ג פ\"ה, משא\"כ אלקים גימ' פ\"ו, וזהו ותחסרהו מעט שחסר א'. וביאור הענין הוא, הנה ידוע שד' שמות ע\"ב ס\"ג מ\"ה ב\"ן הם בחכ' ובינה ז\"א ומל', שם ע\"ב בחכ' ופי' שם הוי' במילוי יודין, שם ס\"ג ג\"כ במילוי יודין רק שהוי\"ו הוא בא' בבינה, שם מ\"ה בז\"א במילוי אלפין, שם ב\"ן במל' במילוי ההין, והנה השבירה הי' בז\"ת דאימא דהיינו בשם ב\"ן וע\"י מ\"ה שמברר לב\"ן בחי' העלי' לשם ס\"ג ששם לא הי' השבירה כי השבירה לא הי' כ\"א בז\"ת דאימא אבל בג\"ר דבינה לא הי' שם שבירה כלל, והעלי' היא דוקא ע\"י בירור שם ב\"ן בחי' בהמה כמ\"ש בת\"א בד\"ה ונתתי לך מהלכים כו', והנה משה הי' בחי' מ\"ה כמ\"ש ונחנו מה שהוא בחי' תיקון שהוא בחי' ז\"א, וההפרש שבין ז\"א לבינה הוא כמו ההפרש שבין חכ' לכתר, שהתהוות החכ' היא מבחי' אין וכמ\"ש והחכ' מאין תמצא, כמ\"כ ת\"ת דבינה נעשה כתר לז\"א, ולזה הי' עליית משה שהוא בבחי' ז\"א שם מ\"ה שהוא בז\"א לבחי' ס\"ג שהוא בחי' בינה, ופ\"ה הוא בחי' אלקים היינו הוי' בניקוד אלקים שהוא בחי' בינה, ופי' הוי' בניקוד אלקים היינו שאלקים הוא בחי' כלי והוי' בחי' אור שלאחר הבירור וכתיב ותחסרהו מעט מאלקים, שלא השיג כל אלקים גימ' פ\"ו, ופסגה הוא ס\"ג פ\"ה, והיינו שלא השיג שער הנו\"ן דבינה.\n<b>והנה</b> מה שיש לדקדק על פי' הוא ממשארז\"ל גדולים צדיקים במיתתן יותר מחייהן, ומאחר שלא השיג כל הנש\"ב א\"כ מהו גדולים צדיקים כו', וי\"ל כי זה הי' לפני מותו וגדולים צדיקים במיתתן שאז השיג כל הנשע\"ב, וגם מה שלא השיג משה הוא חלק א' ממ\"ט, כי מ\"ט שערים השיג כו' ולפי' הפ\"י חסר חלק א' ממ\"ט ולכן אפ\"ל שמשה השיג כל הנו\"ן שע\"ב. ומתחלה צריך להבין מהו מספר נון שע\"ב, וי\"א כי זפ\"ז הוא מ\"ט ושער הנו\"ן הוא בחי' בינה וי\"א כי בינה היא בחי' ה' של שם הוי' וכל א' כלול מיו\"ד, זהו נ' שערי בינה, והנה חמשה חומשי תורה הם בחי' ה' עילאה שהיא בחי' בינה, עיין בד\"ה תורת ה' תמימה ומבואר שם שיש ו' פסוקים כל אחד מחמשה תיבות, ו' פסוקים כנגד שיתא סדרי משנה וחמשה תיבות שבכל פסוק הוא כנגד חמשה חומשי תורה."],[4101400110,"<b>והנה</b> התורה נאמרה ע\"י משה ואעפי\"כ לא השיג כל הנו\"ן שע\"ב, פי' כי יש אור מים רקיע ומשה השיג בחי' מים אבל בחי' אור שהוא פנימיות התורה לא השיג בחייו, ובחי' רקיע הוא בחי' תורה כמו שלומדים אותה במתיבתא דרקיעא כמ\"ש במ\"א, וכמ\"ש וראית את אחורי ופני לא יראו פני לשון פנימיות שעדיין לא השיג בחי' אור שהיא פנימי' התורה, אבל גדולים צדיקים במיתתן שהשיג כל הנו\"ן שע\"ב, כי הנה התורה נקרא' אור וכמו שמבואר במדרש בראשית פ\"ג א\"ר סימון חמשה פעמים כתי' כאן אור אורה כנגד חמשה חומשי תורה, ויאמר אלקים יהי אור כנגד ספר בראשית שבו נתעסק הקב\"ה וברא עולמו, ויהי אור כנגד ספר שמות שבו יצאו ישראל ממצרים מאפילה לאורה, וירא האלקים את האור כי טוב כנגד ספר ויקרא שהוא מלא הלכות רבות, ויבדל אלקים בין האור ובין החושך כנגד ספר במדבר שהוא מבדיל בין יוצאי מצרים לבאי הארץ, ויקרא אלקים לאור יום כנגד ספר דברים כו' מתיבין חברי' כו' אמר לון אף שנה בו דבר כו' עכ\"ל, והנה אור נקרא טוב כמ\"ש ג\"כ במדרש סוף מקץ פצ\"ב, אר\"ל עובדא הוה בדרומא תמן חד פונדקי כו' אזל ר' מאיר ואיתקבל קמן, קם ולבש זינן א\"ל קום פוק דלויתא אנא עבדא א\"ל ר\"מ אית לי אח א\"ל אן הוא א\"ל בכנישתא א\"ל ומה שמי' א\"ל כי טוב כו', בצפרא קם ר\"מ ושוי חמרא דיזיל לי' א\"ל ההוא פונדקא אן הוא אחוך דאמרת לי א\"ל הא אתא לי' וירא את האור כי טוב כו' עכ\"ל, נמצא האור נקרא טוב כו', והנה ה' פעמים טוב עולה פ\"ה, וזהו פסגה שם ס\"ג ופ\"ה ה' פעמים טוב כו', וטוב ואור הכל אחד, והתורה נק' אור והיינו שהשיג בחי' אור התורה שהוא בחי' פנימיות התורה כו' וזהו העלי' שהשיג כל הנו\"ן שע\"ב, וזהו ענין מ\"ש במד\"ר ובילקוט רמז תתכ\"ב נתן בעיניו כח לראות מסוף העולם ועד סופו, והנה אור שנברא ביום ראשון הי' אדם מביט בו מסוף העולם ועד סופו, והיכן גנזו בתורה, וע\"י שהשיג בחי' פנימיות התורה בחי' אור התורה לכן הי' כח בעיניו לראות מסוף העולם ועד סופו."],[4101400111,"<h3>להבין החילוק שבין צדיקים לחסידים</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>להבין</b> החילוק שבין צדיקים לחסידים ובע\"ת, הנה צדיק הוא לשון צדקה, והנה ענין הצדקה למטה היא להחיות רוח שפלים דהיינו מה שנותן לעני חיות נפשו הוא נק' בשם צדקה, ולמעלה הוא ג\"כ להחיות רוח שפלים דהיינו פגימת הלבנה שזהו מ\"ש בעירום ובחוסר כל פי' שחסר בחי' כל שהוא בחי' יסוד המשפיע למל' וע\"י הצדקה שעושי' למטה דהיינו להחיות רוח שפלים וליתן לעני די סיפוקו עי\"ז מעוררים למעלה ג\"כ שיומשך למל' דהיינו למלאות פגם הלבנה, וכמאמר רז\"ל שמש בשבת צדקה לעני', דהיינו מה שנמשך מבחי' שמש הוי' הוא צדקה לענים בחי' מל' מיעוט הירח כו' כנ\"ל, וזהו בחי' צדיקים אבל בחי' חסיד גבוה מצדיק כמארז\"ל נדה די\"ז קוברן צדיק שורפן חסיד ע\"ש בפרש\"י ותוס', נמצא שחסיד גבוה מצדיק.\n<b>ולהבין</b> כ\"ז הוא דהנה צדקה הוא רק לענים, וגם להעני א\"צ להעשיר את העני רק שיתן לו די מחסורו אשר יחסר לו, אבל גמ\"ח הוא בין לענים בין לעשירים דהנה לשון חסד (פי' הרמב\"ם במ\"נ) שהוא לשון הפלגת הטוב והוא בין לענים ובין לעשירים, והנה איתא בזוהר ברע\"מ פ' תשא העשיר לא ירבה דא עמודא דאמצעיתא בחי' ת\"ת שהוא בחי' עשיר שמאיר שם גילוי אלקות כנודע, והנה גמ\"ח היא גם לעשירים דהיינו אפי' בחי' ת\"ת כי חסד הוא הפלגת הטוב ונמשך מבחי' חסד דא\"א ששם לית שמאלא כלל, וזהו בחי' חסיד, וזהו בית יעקב לכו ונלכה באור ה' ופי' בזוהר באור ה' באור שמאיר בשם ה' דלכאורה י\"ל באור ה' היינו האור המאיר משם ה' אבל פי' בזוהר כנ\"ל דהיינו באור המאיר בשם ה', וזהו ע\"י מדריגת החסידי' שהיא הפלגת הטוב אף לעשירים שהיא בבחי' שם ה' בחי' ת\"ת כי בד\"כ שם ה' היא בת\"ת והאור הנמשך משם ה' היא ע\"י מדרגות הצדיקים שהיא להחיות רוח שפלים בחי' מל' דהיינו למלאות פגם הלבנה. ומדרגות בע\"ת היא גבוה אף מבחי' חסידים, דהנה המשכת הצדיקים והחסידים הוא רק מבחי' ו\"ה משא\"כ הבע\"ת ע\"י האתהפכא מחשוכא לנהורא בחילא יתיר ממשיכים מבחי' י\"ה וכדאיתא בזוהר פ' אחרי ואתחברו וא\"ו עם ה' מאן גרם לון חסד, יו\"ד עם ה' עילאה לא תליא חיבורא"],[4101400112,"דלהון בחסד אלא במזלא תליא פי' החיבור מבחי' ו\"ה תליא בחסד דהיינו מדות עליונות, אבל החיבור דבחי' י\"ה לא תליא במדות כ\"א במזלא בחי' כח\"ב תליא, וזהו מדרגה היותר נעלה, והוא מדרגת הבע\"ת שממשיכין מבחי' י\"ה ולכן יכול לימשך למטה ביותר ממדרגות הצדיקי' שאינו נמשך כ\"א למעלה דוקא."],[4101400113,"<h3>זה היום תחלת מעשיך</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>זה</b> היום תחלת מעשיך זכרון ליום ראשון. הנה זה הפסוק קאי על ר\"ה (כי כל מקום שנאמר היום הוא ר\"ה) ולכאו' צ\"ל מ\"ש שזה היום דהיינו ר\"ה הוא תחלת מעשיך הלא בכ\"ה באלול נבה\"ע וא\"כ ר\"ה הוא יום ו' למעשה בראשית. הנה מתחלה צ\"ל משארז\"ל בתחלה עלה ברצונו לברוא את העולם במדת הדין ראה שאין העולם מתקיים שיתף עמו מדה\"ר, וצ\"ל איך עלה ברצונו לברוא את העולם במדה\"ד הלא הוא ית' מקור הרחמים והחסדים כו'. ויש ע\"ז ב' תירוצים. דהנה חסד הוא גילוי והתפשטות, והנה מצד אוא\"ס הי' ההתפשטות ג\"כ לאין סוף וממילא לא הי' נפרדים כלל, ועיקר המכוון שיהי' מלך על עם נפרדים בע\"ג, ולכן הי' צ\"ל הבריאה במדה\"ד דייקא כי דין היא צמצום וגבורה, וכידוע מענין שמש ומגן הוי' אלקים, הרי שנמשל שם הוי' לבחי' שמש כמו שהשמש הוא בחי' התפשטות וגילוי כמ\"כ מצד בחי' שם ה' הי' יכול להיות ההתפשטות לאין קץ, ושם אלקים נמשל לבחי' מגן ונרתק כמו שהנרתק מסתיר את השמש כו' כמ\"כ בחי' שם אלקים מעלים ומסתיר את אור שם הוי' כדי שיוכל להית התהוות העולמות, ולכן לא נזכר במע\"ב כ\"א שם אלקים כו' כמ\"ש במ\"א באורך.\n<b>והב'</b> הוא כי הנה כתיב שמאלו תחת לראשי וימינו תחבקני, פי' ראשי הוא כי בנש\"י יש שני בחי' ראש ורגל, דהיינו שיש נשמות שהם בחי' ראש ויש נשמות שהם בחי' רגל, יעקב יוד עקב וישראל הוא בחי' לי ראש, וכמ\"כ יש שני בחי' אהבה שנק' ג\"כ בשם ראש ורגל, והוא בחי' אהבה דבכל מאדך בלי גבול ונק' אהבה [זו] בשם ראש, והב' היא אהבה כמ\"ש לאהבה את ה' למען"],[4101400114,"חייך שהאהבה זו נק' בשם רגל כו', והנה איך יגיע לבחי' אהבה דבכל מאדך הוא ע\"י בחי' שמאלי דוקא כי שמאל דוחה וימין מקרבת שע\"י הביטושים שמבטש א\"ע ומסגף כו' ע\"י יגיע לבחי' אהבה דבכל מאדך, וזהו שמאלו תחת לראשי.\n<b>ובזה</b> יובן מה שמתחלה עלה ברצונו לברוא את העולם במדת הדין, שעיקר המכוון הוא שיהי' העלאת דוקא כי ירידה צורך עלי' דוקא וא\"א כ\"א שיבטש א\"ע שהוא בחי' שמאל דוחה בחי' מדה\"ד, ראה שאין העולם מתקיים, פי' שמצד מדה\"ד לא הי' יכול להיות קיום העולמות (כמ\"ש הן שמים לא זכו בעיניו) לזה הי' צריך לשתף מדת הרחמים."],[4101400115,"<h3>הן האדם היה כאחד ממנו</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>הן</b> האדם היה כאחד ממנו לדעת טו\"ר, הנה האדם הוא נבדל במדרגה מכל בע\"ח אשר על פני האדמה והוא שניתן לו מעלת הבחירה שיוכל לבחור כך או כך, משא\"כ שאר בע\"ח אין להם בחירה כו' כ\"א כפי הטבע אשר ניתן לו דהיינו שור נגח וארי דורס כו' אינו מצד הבחירה כ\"א שהטבע שלו כך. ולכן בשרשן דהיינו בחי' ד' חיות המרכבה ג\"כ ארי נוהם ושור גועה וא\"א להם לשנות את תפקידם כ\"א להאדם דוקא ניתן הבחירה והוא כפי שיוכל למשול ביצרו ולהפוך אותו. והמכוון מזה הוא שע\"י שמגביר יצ\"ט על יצה\"ר עי\"ז נעשה למעלה המתקת הגבורות כי שורש יצ\"ט היא מחסדים ושורש היצה\"ר היא מהגבורות ובזה שהאדם מגביר את היצ\"ט על היצה\"ר למטה עי\"ז נעשה למעלה המתקת הגבורות, וזהו הן האדם הי' כאחד ממנו וארז\"ל כיחידו של עולם, דהיינו שיכול לבחור בטוב כו', וכ\"ז הוא לאחר חטא עה\"ד כו' וקודם חטא עץ הדעת לא הי' יצה\"ר כמו עתה אלא הי' כמו שהוא בשרשו דהיינו בחי' גבורה והי' ע\"ד מיכאל שר של אש וגבריאל שר של שלג ואין מכבין זא\"ז, וכמו קין והבל שקין הביא פשתן מנחה להוי' והבל הביא צמר, והנה צמר ופשתן יחד הוא שעטנז, משא\"כ בציצית בזמן שהי' תכלת הי' מותר כלאים בציצית והוא מפני ששרש הציצית גבוה בחי' ה' אלקי גדלת מאד כו' וכנ\"ל מיכאל וגבריאל כו', וזהו וה' אלקים עשה את האדם ישר כו'."],[4101400116,"<h3>בזהר פ' בראשית מקול מחצצים</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>בזהר</b> פ' בראשית דל\"ב ע\"א פתח ואמר מקול מחצצים בין משאבים שם יתנו צדקות ה', מקול מחצצי' דא קול יעקב מחצצים כד\"א איש הבינים, בין משאבים דאיהו יתיב בין אינון דשאבין מים דלעילא והוא נטיל בתרין סטרין וכליל להון בגווה. שם יתנו צדקת ה' תמן אתר מהימנותא לאתדבקא, שם יתנו צדקת ה' תמן ינקין צדקת ה' ושאבין, צדקת פרזונו דא צדיק דעלמא דאיהו קיים וקדוש ואיהו שאיב ונטל כולא, ע\"כ תוכן המאמר.\n<b>ולהבין</b> המאמר מקול מחצצים דא קול יעקב, הנה איתא בתנא דבי אליהו ג' פירושים ע\"פ מחצצים א' לשון דיני חציצה ודיני מחיצה וא' שקאי על תורה כשר פסול טמא טהור, והנה ענין הפירוש הג' שהוא ענין תורה כשר פסול הוא ע\"ד מ\"ש בזוהר דא קול יעקב שיעקב הוא ממוצע בחי' ת\"ת שמחבר ב' בחי' חו\"ג. ולהבין מהו הממוצע. והענין דהנה חסד הוא חד אריך שהוא מתפשט לאין שיעור להשפיע החסד לזולתו עד שאפי' אם יהא חייב גמור ע\"פ חסדים יוכל להשפיע לו, וכמ\"כ להיפוך ע\"י מדת הגבורה יוכל להיות גבורות עד אין קץ ותכלית, והתפארת מכריע ביניהם שמודד שלא יהא החסדים כ\"כ והגבורות ג\"כ כ\"כ, רק שיהי' בחי' ממוצע (כי עד\"מ מצד אברהם שהי' איש החסד יצא ממנו ישמעאל ויצחק שהי' מדת הגבורה יצא ממנו עשו אבל יעקב שהי' מדת התפארת בחי' התכללות הי' מטתו שלמה), וזהו הפירוש בתד\"א ג\"כ מקול מחצצים לשון כשר פסול טמא טהור הנה כשר טהור הוא מצד החסד ופסול טמא הוא מדת הגבורה, ובלתי התכללותם יוכל להיות לא' חסדים גדולים ולהשני מהיפוך להיפוך ממש גבורות מפני המדות שהם בלא התכללות, וזהו כמ\"ש בזוהר שהתפארת מחבר אותם, דוגמא לזה בפלוגתא שמאי והלל שמאי הוא מקור הגבורות והלל הוא מקור החסדים, וארז\"ל הלכה כדברי המכריע וזהו ג\"כ מזה הטעם שמפני ששמאי הוא מקור הגבורות ולא יוכלו העולמות לקבל דין הקשה, וכמ\"כ מדת הלל הוא להיפוך ממש שהיא מדת החסדים ויכול להשפיע חסד לזולתו אף שאינו כדאי כלל, לכן ארז\"ל הלכה כדברי המכריע שלא יתנהגו העולמות לא ע\"י חסדים גדולים כ\"כ וגם לא ע\"י מדת הגבורה כ\"כ כ\"א ע\"י מדת התפארת בחי' התכללות חסדים וגבורות.\n<b>מחצצים</b> כד\"א איש הבינים, הנה איש הבינים כתי' (שמואל א' [י\"ז] ד') גבי גלית הפלישתי ויצא איש הבינים שיצא ממחנה פלישתים ועמד"],[4101400117,"נגד מחנה ישראל. ופירש\"י שבטח על הגבורה שלו ע\"כ נק' בשם איש הבינים שהוא בין מחנה פלישתים ובין מחנה ישראל, וכמ\"כ בכאן יעקב נק' בשם איש הבינים שהיא בין חסד לגבורה דאיהו יתיב בין אינון דשאבין מים מלעילא, שאבין מים עילאין בין חו\"ג חסד שואב מן החכמה בחי' חסדים וגבורה שואבת מן בינה שהיא מקור הגבורות. וזהו שהתורה נק' בשם כד כמ\"ש ותער כדה אל השוקת ותמלא כדה שהיא כד מים החכמה. ולזה יש ב' בחי' כד כד שמשותיך ב' פעמים כד שהיא כד מים החכמה וכד מבחי' גבורות, ומדת התפארת היא בחי' רחמים בחי' התכללות שלא יהא הגבורות כ\"כ וכמ\"כ שלא יהא החסדים ג\"כ כ\"כ, ולכן התורה היא בתפארת דוקא שמחברת ומחלקת בין טמא ופסול לטהור וכשר שהם מב' סטרין.\n<b>והוא</b> נטיל מב' סטרין וכליל להון בגבי'. נטיל מב' סטרין כנ\"ל וכליל להון גביה שעיקר היופי היא מצד ההתכללות דוקא, כמשל הרבה גוונין ביחד לבן וירוק אדום כשהמה בהתכללות המה בתכלית היופי כמ\"כ יובן עד\"מ למעלה ג\"כ שתכלית היופי הוא מהתכללות דוקא.\n<b>שם</b> יתנו צדקות הוי' תמן אתר מהימנותא לאתדבקא ותמן ינקין צדקת כו'. הנה צדקת הוי' נק' בשם נו\"ה. שם יופי המדות ומשפיעים לזולתם ומקבלים מבחי' תפארת ומתדבקים שם, כמשארז\"ל שחקים טוחנות מן לצדיקים לע\"ל כמשל האכילה שמפררים המאכל כמ\"כ מפררים ההשפעה לפי ערך המקבל, ואף שהמדות המה חח\"ן בג\"ה, חכמה חסד נצח מימין, חכמה היא מוח המדות חסד היא עצם המדה נצח נק' בשם ענף המדה, זהו רק עצם ענף המדה משא\"כ פנימיות המדות המה מתפארת דוקא שהיא בחי' התכללות וכתי' מגיד דבריו ליעקב לא עשה כן לכל גוי שלהם אינו נמשך פנימיות ח\"ו כ\"א חיצוניות דוקא משא\"כ לישראל נמשך פנימיות דוקא ע\"י נו\"ה.\n<b>צדקת</b> פרזונו בישראל, דא צדיק דעלמא. צדיק הוא בחי' יסוד בחי' יוסף שנק' צדיק עליון, שע\"י הוא כל ההשפעות דוקא, וזהו פרזונו לשון פרזות תשב ירושלים מאין חומה, דהנה חומה הוא מאבנים בחי' אותיות שתי אבנים בונות שתי בתים כו' בחי' צמצומים, וזהו מצד שם אלקים עיר אלקינו אבל לע\"ל כתיב ושם העיר מיום הוי' שמה שלא יהא עוד בחי' צמצומים שע\"פ שם אלקים, ולכן פרזות תשב ירושלים מאין חומה שבחי' חומה לא יוכל להגבילם שחומה היא מגביל הדבר, אבל לע\"ל שיהא בחי' התרחבות ע\"ד שחומה לא יוכל כו'.\n<b>והפי'</b> הב' של התד\"א לשון דיני חציצה ומחיצה הוא ע\"ד ופרעה הקריב, בשלח פרעה, הקריב את לבם כו' שע\"י התשובה זכו כו'."],[4101400118,"<h3>בזהר פ' חיי שרה ויהיו חיי שרה</h3>\n<b></b><b>[הנחת כ\"ק אדמו\"ר מהר\"ש]</b>\n<b>בזהר</b> פ' חיי שרה ויהיו חיי שרה מאה שנה, מ\"ש בכולהו דאמר שנה שנה ובאינון שבע דאמר שנים כו' אלא מאה שנה כללא דכולא קוב\"ה דאתכליל מאתר עילאה סתימא דכל סתימין במאה ברזא דמאה ברכאן וכן עשרים שנה ובגין כך כתיב שנה רזא דיחודא דלא אתפרש מחשבה ויובלא לעלמין, שבע שנים אלין אתפרשין מכלל סתימא דלעילא כו' בדינא ורחמי בכמה סטרין כו' וכולהו אקרי חיי שרה כו'.\n<b>הנה</b> ידוע מאמר אליהו אנת הוא חד ולא בחושבן אנת הוא דאפיקת עשר תיקונין וקרינן לון עשר ספירן, והנה בס\"י עשר ספירות בלי מ\"ה פי' בלי מה בלי מהות כלל, ולפ\"ז צ\"ל מה שע\"ס נק' בשם חכמה ובינה ומדות, קאי על הכלים דע\"ס, אבל אור הכלי הוא בלי מהות ממש והוא כמשל שבמוח היא השראת השכל והמוח כלי המקבל לקבל גילוי אור השכל, כמ\"כ יובן למעלה מה שאנו קורין בשם חכמה או מדות זה קאי על הכלים שהם כלי החכמה אבל אור המלובש בהכלי הוא בלי מה בלי מהות כלל. והנה כדי שיוכל להיות מאא\"ס שהוא חד ולא בחושבן בחי' ע\"ס צ\"ל בחי' ממוצע והיינו בחי' כתר, והנה ידוע שהממוצע הוא כלול משני הבחי' וכמ\"ש בע\"ח שער מ\"א פ\"ג שבכתר יש בו בחי' התחתונה שבמאציל וזהו פנימיות הכתר ובחי' חיצוניות הכתר הוא מקור לע\"ס דאצילות. וזהו מאה שנה שמפני שהוא מקור לע\"ס הוא מאה דהיינו יו\"ד וכל א' כלול מיוד ואעפ\"כ הוא שנה ל' יחיד והוא מפני בחי' התחתונה שבמאציל.\n<b>ולהבין</b> היטב מ\"ש אף שהוא מאה אעפ\"כ היא שנה דהנה מבשרי אחזה אלוה שאנו רואים שיש כח הראי' בעין וכח השמיעה באזן וכח ההילוך ברגלים הרי שכוחות אלו המה בהתחלקות זמ\"ז שמכח הראי' לא יוכל לשמוע וכך להפך, והנה ע\"כ צ\"ל שכל הכוחות האלו יש בנפש דאל\"כ מאין באו הכוחות האלו, והנה אף שיש בהנפש כל הכוחות אעפ\"כ הוא אחד והמה בהתאחדות עד שלא יש נפרד בין ראי' לשמיעה, וע\"ד משארז\"ל ע\"פ וכל העם רואין את הקולות רואין את הנשמע ושומעין הנראה, וע' בלק\"ת בד\"ה כנשר יעיר קנו פ\"א, וכמו\"כ יובן למעלה שבחי' כ\"ע אף שיש בו בחי' מאה אעפ\"כ הוא שנה לשון יחיד כנ\"ל. וזהו רזא דמאה ברכאן שע\"י מאה ברכות יומשך מבחי' מאה שנה. וזהו ויהיו חיי שרה מאה שנה, שרה הוא ל' שררה כי שרית"],[4101400119,"עם אלקים שהיא בחי' כתר מל', וצריך שיומשך בה מבחי' כתר מאה שנה כנ\"ל.\n<b>ועשרים</b> שנה קאי על חו\"ב, והנה חו\"ב נק' אין ויש שהחכמה נק' אין וכמ\"ש והחכמה מאין תמצא והבינה נק' יש וכמ\"ש להנחיל אוהבי יש, והנה כתי' ונהר יוצא מעדן, וארז\"ל מה שמו דההוא נהר יובל שמו שהוא בחי' שער החמישים דבינה יוצא מעדן תמיד בלי הפסק שתמיד צ\"ל התחדשות הבריאה מאין ליש וזהו מחשבה ויובלא דלא אתפריש כלל לעלמין, מחשבה בחי' חכמה ויובלא בחי' בינה לא אתפרש כלל שזווגייהו תדיר ונק' תרין ריעין דלא מתפרשין. והנה התהוות החכמה הוא מאין. ויובן זה בנפש האדם דהנה יש מיש הוא כמו המדות שמתחלה היו כלולים בהשכל בהעלם ואח\"כ יצאו מהעלם לגילוי, וכן מחשבה ודבור הנה מה שהוא רוצה לדבר עולה לו מתחלה במחשבתו רק שהוא בהעלם ואח\"כ יוצא לגילוי ע\"י הדבור, זה אינו נק' יש מאין כ\"א יש מיש מאחר שמתחלה הי' כלולים במחשבה והיא כמשל עיבור ולידה שבעת העיבור הי' הולד ג\"כ ברמ\"ח איבריו כמו עתה רק שהי' בהעלם ואח\"כ ע\"י הלידה יוצא לגילוי. וזהו יש מיש אבל התהוות השכל מלמעלה מן השכל זהו ע\"ד יש מאין מאחר שאין מושג לנו אופן ומהות הנשמה שלמעלה מן השכל, וכמ\"כ למעלה התהוות החכמה הוא מאין. אך אין המשל דומה לנמשל כי התהוות השכל הוא מלמעלה מהשכל והיא מהנשמה שהיא ג\"כ יש משא\"כ התהוות החכמה הוא מאין ממש. והנה השראת אוא\"ס הוא בחכמה לפי שהחכמה הוא בחי' כח מה בחי' ביטול ולכן כתיב שנה ל' יחיד לפי שהשראת אוא\"ס בחכמה וחו\"ב הם תרין ריעין דלא מתפרשי' כנ\"ל. וזהו שהחכמה נק' יו\"ד שיש במילוי שלו ג\"כ יו\"ד וכידוע שהמילוי נק' בינה וזהו מ\"ש והבן בחכמה דהיינו בינה שכלולה בחכמה, וזהו עשרים, ע\"ס דאבא וע\"ס דאימא ואעפ\"כ שנה, וצריך שיומשך במל' גם מבחי' חו\"ב והוא כמשל שעל פי רוב הדבור שהוא בחי' מ\"נ מקבל מהמדות אעפ\"כ לפעמים יקרה שהדיבור מקבל מהשכל כמו אם מדבר דבר שכל וכמו\"כ בחי' מל' לפעמים מקבלת מבחי' חו\"ב כנ\"ל וד\"ל.\n<b>ושבע</b> שנים לשון רבים כי הנה בז\"א יש בחי' חסד ודין שהוא בחי' התחלקות מה דלא הוי' הכי לעילא, ות\"ת קו האמצעי מחבר ב' הבחי' שת\"ת עולה עד הכתר, ולכן כתיב כאן שנים ל' רבים, וזהו שבד\"כ נק' ז\"א בשם יחידות וחו\"ב הוא בחי' עשירות וכתר הוא בחי' מאות כנ\"ל והוא שכשהשפע בא מלמעלה בא במספר יותר גדול ע\"ד שבכתר היא יו\"ד פעמים יו\"ד ואח\"כ בריבוי השתלשלות נתמעט במיעוט אחר מיעוט עד שבז\"א הוא בחי' יחידות בד\"כ, והוא בחי' אתוון רברבין בינונים וזעירין שאתוון רברבין הוא במדרגה היותר נעלה, והנה צריך שיומשך במל' גם מז\"א כי הנה במדות צריך להיות בחי' חו\"ג מלך במשפט יעמיד ארץ כדי שיוכל להיות ואוהב את יעקב"],[4101400120,"ואת עשו שנאתי, וזהו מ\"ש בזוהר וכולהו חיי שרה שכל הבחי' הנ\"ל דהיינו כת\"ר ואו\"א וז\"א הוא חיי שרה בחי' מל'.\n<b>ואח\"כ</b> כתיב שני חיי שרה, וצ\"ל מה שכפל הכתוב ואמר עוד שני חיי שרה. והענין הוא שפי' שני חיי שרה הוא שיומשך ממל' גם בבי\"ע והוא ע\"י שמל' דאצי' נעשה עתיק לבריאה ונמצא יש בה כל הבחי' הנ\"ל שנמשך בה, עד שיש בכאו\"א מישראל כל בחי' הנ\"ל (שבריאה הוא עולם הנשמות) והוא כמו ר\"א בן דרודיא שיצא נשמתו בבכיה דהיינו שהי' לו רצון פשוט לאלקות דהיינו בחי' יחידה שבנפש שרומז לבחי' כתר, וגם יש בכ\"א בחי' חכמה דהיינו ביטול היש, ועי\"ז גורם וממשיך למעלה התהוות מאין ליש, ובחי' בינה הוא התבוננות בגדולת ה', ועד\"ז כל המדות ישנם בנפש האדם וזהו שני חיי שרה כנ\"ל וד\"ל."],[4101400121,"<h3>מזוזה מימין</h3>\n<b>מזוזה</b> מימין ונ\"ח משמאל, וי\"ל למה נ\"ח משמאל דוקא, והלא המנורה היתה בדרום דוקא ולמה נ\"ח משמאל. וגם בנ\"ח שהיא משמאל זהו דוקא כשיש מזוזה ואם אין מזוזה אזי גם נ\"ח מצותה בימין. ולהבין זה י\"ל מ\"ש כל אשר חפץ ה' עשה וכן כתיב בחכ' יסד ארץ כונן שמים בתבונה ובדעתו תהומות נבקעו, וכתי' בדבר ה' שמים נעשו, ובע\"מ נבה\"ע שהוא מאמר ודבור ולא נברא בחפץ ורצון בלבד. והענין הוא דהנה ידוע שבכל דבר יש חומר וצורה שהחומר הוא ענין הדבר ההוא בכללות דהיינו להיות השמים או הארץ או שמש וירח, והצורה הוא כל ציור וכל תמונה במראה ושטח שיש לכל דבר כדמותו בצלמו על איזה אופן נעשה, כמו השמים והארץ הם כדורים, ומן הארץ לרקיע כו' והשמש והירח הם גלגלים מאירים כו', וכן ענין ריחוק השמש מן הארץ בכדי שעי\"ז יהי' קור וחום, וכן עד\"ז בכל דבר נברא, והנה החומר נברא בדבר ה' ובע\"מ, שבמא' יהי אור נתהווה בחי' האור מאין ליש, וכן במאמ' יהי רקיע נתהוו' הרקיע מאין ליש, אבל אופן צורת הרקיע כדמותו וצלמו הוא"],[4101400122,"נעשה ע\"י חפץ ה' שלא בא לכלל גילוי בדבור או מאמר. והנה מה שנברא החומר במאמ' ודיבור ולא נברא הכל בחפץ ה' ורצונו בלבד, והגם כי ארז\"ל והלא במא' א' יכול להבראות אעפי\"כ הי' צריך לכה\"פ מא' ודיבור א'. היינו מפני שאז לא הי' גילוי מאין ליש רק שהי' העולם בטל במציאות ממש, ולא הי' גילוי מאין ליש, רק שהי' כמו עלמין סתימין שנתהוו מאותיות המח' ולכך הם סתימין כמו אותי' המח' שאין להם גילוי לזולתו, וכדי שיתהווה עלמין דאתגליין עולמות נפרדים זהו ע\"י דבור דוקא כי אותי' הדבור הם נעשין נפרדין כו', כי הגם כי לא מחשבותי מחשבותיכם כו' ואין לך דבר שחוץ ממנו, מ\"מ דברה תורה כלשון בנ\"א ועי\"ז הם נראים ליש ודבר נפרד כו', ואם הי' נברא בדבור לבד הי' נעשי' בבחי' יש ופירוד ממש ולא הי' ביטול היש לאין, וכדי שיהי' בחי' ביטול היש זהו לפי שהצורה נתהווה ע\"י חכ' ועי\"ז אף שהם בבחי' יש הם בטלים ונעשה ביטול היש לאין.\n<b>ולהבין</b> זה בתוס' ביאור י\"ל עוד ענין חומר וצורה, והענין הוא דהנה יש ב' בחי' צורה דהיינו תואר וצורה, והיינו שהחומר גופא יש לו צורה למשל גלגל השמש שיש בו חומר וצורה, עצם החומר והצורה של החומר מה שהוא עגול ולא משוך דהיינו תואר החומר, והצורה האמיתית הוא נפש של הגלגל מה שהוא מניע אותו ומסבב אותו ממזרח למערב, וכן אנו רואין באותיות למשל אותי' הכתב שיש בהם חומר של האותי' דהיינו הדיו, והצורה של האותיות דהיינו מה שהא' משונה מב', שיש בזה סודות נפלאים מה שא' נעשה ככה בתמונה שלו, והשכל שנתלבש באותיות כמו ברוך שאמר והי' העולם שיש בזה השכלה איך שבמאמר א' נברא העולם, וכן באדם יש בו בחי' צורה דהיינו החומר שלו וכמ\"ש ויצר ה' אלקי' את האדם עפר מן האדמה בחי' חומר, והצורה של החומר מה שנעשה הגוף באופן זה וחלוק משאר נבראים כמו למשל ארי' ושור, והיינו לפי שהצורה של הגוף נמשך מבחי' פני אדם שבמרכבה, וגוף הארי' נמשך מבחי' פני ארי' שבמרכבה, והיינו לפי שכדי שיוכל לקבל הגוף את נה\"א, צריך שיהי' הכלי ג\"כ לפ\"ע, משא\"כ גוף הארי' אינו יכול לקבל את נפש האדם לפי שהוא נמשך מבחי' פני ארי' שבמרכבה, וזהו ג\"כ שהבהמות וחיות חלוקים זמ\"ז, שהבהמה יש לה יותר כח מחי' ואעפי\"כ החי' טורף ודורס את הבהמה, והיינו לפי שבחי' יש לה זריזות יותר. והנה\"א שמתלבש בו זהו צורה האמיתית כו'.\n<b>והנה</b> שרש חומר וצורה זהו בחי' אורות וכלים, דהנה איתא בת\"ז וכמה גופי' תקינת לון חסד דרועא ימינא כו' שנק' בשם גופין בחי' כלי לבד, והאור המתלבש בו זהו צורה, וזהו ענין הוי' ואלקי' שאלקי' הוא בחי' כלי לבחי' שם הוי' כי שם הוי' הוא בחי' האור, וזהו ששם הוי' נק' שם העצם ומצטרף לכל השמות כמו הוי' אלקי' אל הוי' כו' הוי' צבאות כו', והיינו לפי ששם הוי' הוא בחי' האור כו', אך הכלי היא לפ\"ע האור, לפי שכדי שיוכל"],[4101400123,"להתלבש האור בבחי' כלי צריך שיהי' הכלי לפ\"ע האור, כמו שנפש האדם א\"א להתלבש בגוף הבהמה, לפי שהגוף אינו לפי ערכו רק בבחי' גוף של האדם יכול להתפשט ולהתלבש כו'. והנה המכוון הי' שיהי' הכלי בטל להאור בחי' ביטול היש לאין, והיינו ע\"י התבוננות אני ראשון ואני אחרון ומבלעדי אין אלקי', כי שרש הדבור הוא מבחי' שם אלקי' ולכך יש ה' אותיות בשם אלקי' כנגד ה' מוצאות הפה, וכמ\"ש ואתה מחי' את כולם, א\"ת וה' מוצאות הפה, וזהו מ\"ש גדול הוי' ומהולל מאד בעיר אלקינו, עיר אלקינו הוא בחי' ק\"ך צירופי אלקי', וגדול הוי' בעיר אלקינו היינו ששם הוי' מושל על שם אלקי' כי אלקי' בגי' הטבע ושם הוי' מושל על שם אלקי', וזהו מ\"ש כי גדול הוי' ואדוננו מכל האלקי' דהיינו שכל הק\"ך צירופי' אלקי' כי באמת ומבלעדי אין אלקי' שההסתר של שם אלקי' אינו הסתר כלל לפני' כיון שאין לך דבר שחוץ ממנו, רק שההסתר הוא לעיננו שנראה ליש ודבר נפרד, אבל קמי' אינו הסתר כלל, וזהו אני ראשון היינו קודם שנבה\"ע ואני אחרון לאחר שנבה\"ע, ומבלעדי אין אלקי' היינו באמצעיתא ג\"כ אין אלקי' שאין הסתר לפניו כמו קודם שנבה\"ע ממש כו' כי זהו רק לעינינו כו', ועי\"ז נעשה ג\"כ אצלו בחי' ביטול היש ויזדכך החומר שלו שלא ירצה רק בחי' אלקות ויהי' לו רצון ותשוקה לאלקות לבד. וזהו מ\"ש בזהר דכל מאן דלא אהפיך חשוכ' לנהורא מרירו למיתקא לית לי' חולקא בעלמא דאתי, והיינו כי חושך הוא בחי' חומר, ונהורא הוא בחי' צורה וכמ\"ש יוצר אור ובורא חושך, וצריך להפוך את החושך לאור שיזדכך החומר, ומרירו למיתקא הוא בחי' להפוך את תענוגי עוה\"ז שהן בחי' מרירו למיתקא, בחי' טעמו וראו כי טוב הוי', אז תתענג על הוי'. והנה עי\"ז שמברר את החומר ומזכך אותו כו' ומהפך חשיכו לנהורא עי\"ז נעשה יתרון האור מתוך החושך וממשיך מלמעלה מבחי' האור, כי שרש האור הוא מבחי' הקו וחוט שהוא לאחר הצמצום, אבל שרש הכלים הוא מבחי' הרשימו שהוא מבחי' טה\"ע שלמעלה מן הצמצום כו' ועי\"ז דוקא נעשה יתרון מעלה כו' וכמ\"ש אז תתענג על הוי' כו'.\n<b>והנה</b> בבחי' ביטול זה יש ב' בחי' היינו מלמטלמ\"ע ומלמעלמ\"ט, והנה מלמטלמ\"ע זהו מ\"ש מט\"ט קושר כתרים לקונו מתפילתיהן של ישראל, והנה כתר הוא ע\"ג הראש למעלה מן המוחין כו', והנה עטרה זו נעשה דוקא מתפילותי' של ישראל שהוא בחי' אותי' והיינו כי האותי' נתעלין לשרשן. דהנה ידוע שאותיות הדבור אף שהם נמשכי' מהבל הלב ומתלבש בה' מוצאות הפה מ\"מ הבל הלב הוא רק כמו חומר של האותיות לבד אבל צורת האותיות נמשכי' מלמעלה מעצמות הנפש וכמ\"ש ויהי האדם לנפש חי' ות\"א לרוח ממללא ששרש הדבור נמשך מבחי' חי', דהנה ידוע שיש נר\"נ ח\"י, ונשמה היא"],[4101400124,"בחי' בינה וכמ\"ש נשמת שדי תבינם, אבל שרש האותיות נמשך מבחי' חי' כנ\"ל רק שהם מתלבשים בה' מוצאות הפה שנתלבש הצורה של האותיות בהבל הלב שנתלבש בה' מוצאות הפה, וכמו שאנו רואין שהחרש אף שיש לו הבל הלב וגם ה' מוצאות אעפי\"כ אינו יכול לדבר והיינו לפי שהצורה של האותיות שהוא בחי' אותיות הקבועין בחכ' אין לו וע\"כ אינו יכול לדבר כו', וזהו ג\"כ שאנו רואין שכיון שרוצה לדבר תומ\"י הוא מדבר ואינו מתעכב זמן מה, ואם הי' האותי' נמשכין מבחי' ה' מוצאות אזי הי' צריך שיתעכב זמן מה כנ\"ל א\"ו ששרש האותיות הם למעלה מבחי' שכל דהיינו מבחי' עצמות החכ' שלמעלה מהשגה וע\"כ תומ\"י שרוצה לדבר אזי הוא מדבר, וזהו שמט\"ט קושר כתרים לקונו מתפילתן של ישראל דהיינו שמעלה את אותי' התפילה למעלה בשרשן שהם למעלה מבחי' חכ', ועי\"ז נעשה בחי' כתר שהוא בחי' יהי רצון המשכת הרצון חדש שאף שעפ\"י חכ' הי' צריך שיהי' בחי' דין לפי שפגם כו' אבל ע\"י תפילה שנתעלה האותי' למעלה מבחי' חכ' עי\"ז נמשך רצון חדש וממלא כל הפגמים. והנה זהו בחי' תפילה שהיא העלאה ממטה למעלה כמו\"כ כל המצות הם בחי' העלאה כמו תפילין שכותבין אחד ע\"ג קלף גשמי ועי\"ז נתעלה הקלף שהיא מבחי' ק\"נ לקדושה והוקשה כל התורה כולה לתפילין שהם בחי' העלאה, וזהו תרי\"ג מצות דאור' וז' דרבנן הם תר\"ך עמודי אור בחי' העלאה וכן צדקה כו'. והנה התורה היא בחי' המשכה למטה לפי שאורייתא מח\"ע נפקת ונמשכה למטה בגשמי'.\n<b>וזהו</b> מזוזה בימין כי הנה מזוזה היא מצוה השייך לבתים, כי הנה יש בחי' מצות השייך ללבושים כמו מצות ציצית, ומזוזה היא מצוה השייך לבתים, והנה פי' מזוזה היינו מל' זו וזה, זו היא בחי' נש\"י וכמ\"ש עם זו יצרתי לי כו', וזה הוא בחי' זה אלי, ומ' היינו מ' יום שקיבל משה את התורה בהר כו', והיינו שע\"י המצות נעשה התחברות נש\"י עם הקדב\"ה, וזהו מימין היינו בחי' ימין מקרבת שע\"י מצות הוא בבחי' וימינו תחבקני שהיא בחי' המשכת מקיפי' שע\"י מצות כו', אך התורה היא המשכה מלמעלה למטה, כל היושב ושונה הקדב\"ה יושב ושונה כנגדו שהיא המשכ' בבחי' פנימי' וכמו שאנו רואין שהתורה נמשך בבחי' פנימי' כו', וזהו ונ\"ח משמאל דהיינו שמתקן ומעלה גם את בחי' שמאל.\n<b>והענין</b> הוא דהנה כתי' ועבד הלוי הוא, ואיתא בזהר הוא דא עלמא דאתכסי', והנה לוים הם מקו השמאל, כי כהנים הם מסט' דימינא ולוים הם מסט' דשמאלא, והיינו שהלוים ע\"י עבודתם מתקנים את קו השמאל, דהנה ארז\"ל עולם לאכסדרה הוא דומה ורוח צפונית אינה מסובבת כי רוח צפון בראו ולא גמרו, והענין הוא דלכך בראו ולא גמרו, דהנה עיקר יניקת החיצוני' הוא מקו השמאל מחמת ריבוי הצמצומים, והנה אם הי' נגמר רוח צפון שהוא בחי' קו השמאל הי' ריבוי יניקת החיצונים עד שלא הי' באפשרי לברר אותם, ולכך"],[4101400125,"לא נגמר כו'. אך אעפי\"כ מקבלים מקו השמאל תוס' יניקה ולכך צריך קו השמאל יותר תיקון. וזהו שקדשי קדשים שחיטתן בצפון, והיינו לפי שע\"י קרבנות מתקנים את רוח צפון כו', וכך הלוים מתקנים את קו השמאל, והיינו לפי שנאמר בהם ועבד הלוי הוא שהוא בחי' עלמא דאתכסי' וכמ\"ש הוא עשנו, הוא ה' אלקינו כו', כי יש בחי' אתה ובחי' הוא, אתה הוא עלמא דאתגלי', והוא הוא עלמא דאתכסי' דהיינו בחי' בינה, והנה בעלמא דאתכסי' שהיא בחי' בינה אין שם יניקת החיצוני' כי מה שמסט' דשמאלא יכול להיות יניקת החיצוני' זהו בבחי' מדות שהם בבחי' ענפין מתפרדין ועי\"ז יכול להיות יניקת החיצוני' אבל למעלה בבחי' בינה שהם שם בבחי' התכללות אזי אינו יכול להיות יניקת החיצוני' כלל, כי הנה חו\"ב הם בחי' תרין ריעין דלא מתפרשין כו' וכתי' ימותו ולא בחכ' שלא הי' שם בחי' שבירה כלל ע\"כ עי\"ז לא יוכל להיות יניקת החיצוני'. והנה הלוים ע\"י עבודתם בבחי' העלאה ומעלים את המדות לבחי' בינה עי\"ז מתקני' את קו השמאל לפי שאין הדינין נמתקין אלא בשרשן, לפי שהם שם אין בבחי' דינין כלל לפי שהם נמתקין ע\"י החסדים לפי שהם שם בבחי' התכללות לפי ששם מאיר אא\"ס בבחי' גילוי ועי\"ז נעשה התכללות ביניהם, וכמ\"ש המשל ופחד עמו עושה שלום במרומיו שע\"י שהמשל ופחד עמו שמאיר אא\"ס בבחי' גילוי עי\"ז נעשה שלום במרומי' מיכאל שר של מים וגבריאל שר של אש ואין מכבים זא\"ז, לפי שע\"י שמאיר עליהם אא\"ס בבחי' גילוי עי\"ז הם בטלים במציאותן ממש ונעשה יחוד והתכללות ביניהם, וכך הלוים לפי שהם מעלין לשרשן שהיא בחי' בינה והתגלות ע\"י היא בבינה עי\"ז הם מתקנים את קו השמאל, ונעשה התכללות לאכללא שמאלא בימינא.\n<b>אך</b> הנה הלוים הי' צריכים מקודם להעביר תער על כל בשרם דהיינו להפריד השערות בכדי שלא יוכלו לקבל יניקה ע\"י השערות כו', וגם הי' צריכין מקודם שיניף אותם אהרן תנופה שהוא כהן בחי' חסד, והיינו לפי שזה גופא שיוכלו הלוים להתעלות לשרשן בבחי' הוא זהו ג\"כ ע\"י הכהנים דוקא שהוא בחי' המשכת החסד מקודם בכדי שיוכלו להתעלות, וכמ\"ש אלה תולדות יצחק כו' יצחק הוא בחי' גבורות שהוא בחי' העלאה ממטה למעלה שזהו מ\"ש צחוק עשה לי אלקים שהוא בחי' תענוג עליון שנמשך ע\"י בירור שם אלקי' כו' והנה זהו הכח ג\"כ ע\"י אברהם שהוא בחי' חסד, לפי שעתה העיקר הוא בחי' חסד (וע' בת\"א פ' תולדות כו') והלוים טפלים לכהנים, ולכך קרח שלא רצה להיות טפל נענש, אך לע\"ל יהי' הגבורות עיקר וכמ\"ש והכהנים הלוים בני צדוק ואיתא בלק\"ת מהאר\"י שלע\"ל יהי' הלוים כהנים, וכשארז\"ל שלע\"ל יאמרו ליצחק כי אתה אבינו, אך עתה העיקר הם החסדים וצריך לאכללא שמאלא בימינא, ולכך זה גופא שיהי' ועבד הלוי הוא בבחי' העלאה לעלמא דאתכסי' כו' זהו ג\"כ ע\"י הכהנים.\n<b>ובזה</b> יובן ענין נר חנוכה משמאל, והיינו שנ\"ח מתקנים ג\"כ את קו המדה של שמאל, והענין הוא דהנה נ\"ח הם שמונה נרות, ובמקדש היו ז'"],[4101400126,"נרות. והענין הוא דהנה ז' נרות הם כנגד ז' מדות שהם בבחי' ענפין מתפרדין וע\"כ המנורה בדרום לפי שאם הי' בצפון הי' הרבה יניקת החיצונים וע\"כ המנורה בדרום בכדי שיהי' התגברות החסדי' על הגבורות, אך נ\"ח שהיא שמונה נרות שהיא בבחי' בינה היא משמאל לפי ששם הם בבחי' התכללות ולא יוכלו להיות שם יניקת החיצוני' ע\"כ הוא דוקא משמאל כדי שעי\"ז יתוקן קו השמאל ג\"כ. אך כ\"ז הוא כשיש מזוזה בימין, אבל אם אין מזוזה בימין אזי נ\"ח בימין, והיינו שכמו שבלוים צריך שיונפו ע\"י הכהנים דוקא ואז עי\"ז יכולים להמשיך מבחי' הוא שלא יהי' יניקת החיצוני' כו', כך נ\"ח זהו ג\"כ כשיש מזוזה מימין ואז יכול נ\"ח להמשיך מבחי' בינה לתקן את קו השמאל, אבל אם אין מזוזה בימין צריך שיהי' נ\"ח בימין דוקא כדי שלא יהי' יניקת החיצוני' כו', אבל אם יש מזוזה בימין מצותה דוקא בשמאל. דהנה ענין נ\"ח הוא ששלחו כתבו לכם על קרן השור שאין לכם חלק באלקי ישראל, והיינו כי שור הוא מבחי' גבור' בחי' קו השמאל, וקרן השור הוא פסולת כי קרנים הוא בחי' פסולת כו'. והיינו שרצו שלא יקבלו ע\"י קדושה כו', אך אח\"כ שהי' ההיפוך ע\"י מס\"נ עי\"ז קבעו שמונה נר חנוכה כדי שיתקן את קו השמאל שלא יהי' יניקת החיצוני' ע\"י קרנים קרן השור כו'.\n<b>והנה</b> החילוק שבין העלא' ממטה למעלה שהיא בחי' מצות ובין המשכה מלמעלה למטה בחי' תורה, זהו כענין מ\"ש יששכר חמור גרם, ופירש\"י גרם הוא לשון גרמי והיינו שהחמור יש לו הרבה עצמות, ועי\"ז יכול לסבול הרבה משא, וכך יששכר חמור גרם שקיבל עליו לסבול את עול התורה כשור לעול וכחמור למשא, והנה עי\"ז נזדכך החומר שלכך נק' חמור ע\"ש חומר, אך ע\"י עול תורה נזדכך החומר כו' שהוא ע\"י אתכפי' כו'. והנה יש לומר עוד פי' חמור גרם הוא לשון שבירת העצמות וכמ\"ש ועצמותיהם יגרם, והיינו בחי' אתהפכ' מחשוכא לנהורא ממש, וזהו החילוק שבין מצות שהם העלאה ממטה למעלה שזהו רק בחי' אתכפי' שעי\"ז נזדכך החומר אבל מ\"מ לא נתהפך לגמרי אבל ע\"י התורה שהיא המשכה מלמעלה למטה עי\"ז נעשה אתהפכא מחשוכא לנהורא ממש שבירת העצמות כו', וזהו ג\"כ ענין מזוזה בימין ונ\"ח משמאל לפי שמזוזה מימין שהוא בחי' מצות שהם בחי' העלאה הם בבחי' אתכפיא כו' אבל נר חנוכה שהוא בחי' תורה וכמ\"ש ורצו להשכיחם תורתך כו' הם בבחי' אתהפכא לפי שמסרו נפשם ממש על קדושת השם וד\"ל."],[4101400127,"<h3>ויגש אליו יהודה</h3>\n<b>ויגש</b> אליו יהודה ויאמר בי אדוני ידבר נא עבדך כו'. הנה איתא בזוהר שענין ויגש אליו יהודה הוא ענין סמיכת גאולה לתפלה. ולהבין זה י\"ל מה שעתה נש\"י נק' ע\"ש יוסף וכמ\"ש נוהג כצאן יוסף, ולע\"ל יהי' נק' ע\"ש יהודה וכמ\"ש בהפטורה דפ' זו ודוד עבדי נשיא עליהם לעולם. והנה להבין זה י\"ל מה שארז\"ל כל הקובע מקום לתפלתו אויביו נופלים לפניו ויש שני גרסאות, דרב אלפס גורס לתורתו, ושניהם אמת. דהנה מקום הוא בהמ\"ק וכמ\"ש ושמתי מקום לעמי לישראל, והנה תפלות כנגד תמידין תקנו, ולכך צריך תפלה קביעות מקום, וגם לפי גירסת רב אלפס לתורתו ג\"כ אמת דהנה ארז\"ל משחרב בהמ\"ק אין להקב\"ה בעולמו אלא ד\"א של הלכה כו', ומאחר שלאחר החורבן ד\"א של הלכה הם במקום בהמ\"ק לכן צ\"ל קביעות מקום לתורתו כו'.\n<b>ולהבין</b> כ\"ז י\"ל מקודם מ\"ש בדבר ה' שמים נעשו וכתי' כל אשר חפץ ה' עשה שמשמע שבחפץ ורצון ה' נעשה הכל ולא במאמר לבד, והענין הוא כי הנה ידוע שלכל דבר ודבר יש חומר וצורה שהחומר הוא ענין הדבר ההוא בכללות דהיינו להיות שמים או ארץ או שמש וירח, והצורה היא כל ציור וכל תמונה במראה ושטח לכל דבר בדמותו בצלמו על איזה אופן נעשה כמו השמים והארץ הם כדורים ומן הארץ לרקיע כו' נמצא צ\"ל ציור השטח ע\"ד ריחוק כזה, והשמש והירח הם גלגלים מאירים כו' וכן עד\"ז בכל נברא ודצח\"ם אופן ציורו שיהי' כך בארכו ורחבו או בעל קרנות או משולש ז\"ע הציור. והנה החומר נברא בדבר ה' ובע\"מ שבמא' יהי אור נתהווה בחי' האור מאין ליש וכן במאמ' יהי רקיע נתהווה הרקיע מאין ליש, אבל אופן צורת הרקיע עד\"מ או ציור שארי פרטי הנבראי' דדצח\"ם בדמותם ובצלמם הוא נעשה בחפץ ה' שלא בא לכלל גילוי בדבור או מאמר. והנה מה שנברא החומר במאמ' ודבור ולא נברא הכל בחפץ ה' ורצונו בלבד הוא מפני שאז לא הי' יכול להיות התהוות היש הגשמי רק שהי' העולם רוחני והי' בבחי' ביטול במציאות ממש, וכמו שאנו רואים בכל בחי' השתלשלות עו\"ע שהעלול בטל לעילה כמו למשל מדות משכל שהמדות נולדים מן השכל, וכמו שאנו רואים שאם מתבונן בשכלו שהדבר ההוא טוב לפניו אזי נולד לו אהבה לזה, ובזה יובן מ\"ש ואהבת את הוי' אלקיך דלכאור' אינו מובן איך יתכן הציווי על האהבה, שהיא מדה שבלב, אך הענין הוא דהציוי הוא על התבוננות וכמ\"ש תחלה שמע ישראל כו' מל' הסכת ושמע שהו\"ע ההתבוננות שיתבונן באלקות ועי\"ז ממילא יבוא לבחי' האהבה, לפי שהמדות מקבלים מן השכל דרך השתלשלות עו\"ע בבחי' קירוב, וכן בגשמי' כמו במו\"מ המדות נולדים מן"],[4101400128,"השכל, ולפי שהמדות נולדים מן השכל לכן הם בטלים להשכל כו' כי העלול בטל להעילה, וכמו\"כ אם הי' נברא הכל בחפץ ורצון הוי' הי' העולם בטל במציאות ממש כמו עלמא דאתכסי' שהם בתכלית הביטול וא\"כ לא הי' עבודה כלל, רק עיקר גילוי מציאות התהוות היש ע\"י דבר הוי' וכמו שאנו רואי' שאותי' הדבור נראים כאילו הם נפרדים, הגם כי למעלה אינו שייך לומר נפרד כו' כי אין לך דבר שחוץ ממנו אך מ\"מ דברה תורה כלשון בנ\"א כו' וע\"כ לפי שנתהוו מבחי' דבר הוי' נראים ליש והוא בחי' מל' כי מלכותך מלכות כ\"ע אין מלך בלא עם שבחי' מל' היא בחי' ההתנשאות והסתלקות שלא יאיר ויתגלה אלא בבחי' שם בלבד, וזהו יהללו את שם הוי' כי הוא צוה ונבראו כמו עד\"מ מלך בו\"ד שמלכותו הוא שמו בלבד אשר נקרא על מדינתו אבל לא בבחי' התלבשות כח הפועל בנפעל, וזהו ונבראו שהוא ממילא כו', וזהו ג\"כ מ\"ש אתה הוא עד שלא נבה\"ע אתה הוא משנבה\"ע ולא כתי' ברא לפי שברא משמע שהוא כח הפועל בנפעל ממש, וכמ\"ש בראשית ברא אלקי' שהוא בחי' התלבשות כח הפועל בנפעל כו' אבל נברא משמע שאינו בבחי' התלבשות כלל, וזהו מ\"ש בפרקי דר\"א עד שלא נברא העולם הי' הוא ושמו בלבד לפי שהתהוות העולם הוא רק מבחי' זיו והארה בעלמא בבחי' התנשאות וריחוק כדי שיתהווה יש מאין כו', ואם הי' התהוות העולמות בבחי' השתלשלות הי' העולם בטל במציאות ממש ולא הי' גילוי בחי' יש, ולזה התהוות החומר הוא מבחי' דבר הוי', אך אם הי' התהוות הצורה ג\"כ מבחי' דבר ה' הי' נפרדים ממש ולא הי' בהם בחי' ביטול כלל, ותכלית בריאות יש מאין הוא כדי להיות ביטול היש לאין ונגלה כבוד ה' למטה כמו למעלה וכמו שיהי' לע\"ל כי עין בעין יראו כו', וזהו ע\"י שנעשה הצורה ע\"י חכ' כי חכ' הוא כח מה בחי' ביטול ועי\"ז נעשה ביטול היש לאין ובחכ' אתברירו. והנה המכוון מזה הביטול הוא כדי שיזכו לעוה\"ב שכל ישראל יש להם חלק לעוה\"ב, וכדי שיזכו לעוה\"ב זה תלוי בעבודתינו כל ימינו היום לעשותם לעשות ביטול היש לאין ועי\"ז יזכו לעוה\"ב שהוא גילוי בחי' חכ' כח מה כי חו\"ב תרדל\"מ כי שכר מצוה מצוה, והנה עוה\"ב הוא בחי' עולם התחי' שיעמדו נשמות בגופים דוקא ויהי' הגוף ניזון ג\"כ מאלקות וכשארז\"ל עוה\"ב אין בו לא אכילה ולא שתי' שא\"א לומר שקאי על ג\"ע דא\"כ מאי רבותא שהרי ג\"ע הוא נשמות בלא גופים ואין שייך בהם אכילה כלל, א\"ו שקאי על עולם התחי' שיהי' נשמות בגופים ואעפי\"כ לא יהי' בהם אכילה ושתי' אלא יהי' נזונים מזיו השכינה וגם הגוף יקבל חיות כמו הנשמה, וזהו ענין טעם עצו ופריו שוה שעתה הארץ שינתה מהציוי אבל לע\"ל יהי' טעם עצו ופריו שוה דהיינו שהגוף יקבל חיות רוחני מזיו השכינה כמו הנשמה ממש.\n<b>אך</b> לכאור' אינו מובן מהו המעלה שיהי' הנשמות דוקא בגופים מהנשמות הגבוהות שהם יותר משלשה אלפים שנה בג\"ע כמו נשמת האבות ומשה שהם משיגים השגות עד אין קץ וכמ\"ש וקדושים בכ\"י יהללוך סלה בלי הפסק כלל ילכו מחיל אל חיל וירדו בגופים דוקא ולכאור' היא ירידה גדולה ולמה"],[4101400129,"ירדו בגופים, א\"ו שהוא ירידה צורך עלי'. ולהבין מהו העלי' יותר גדולה מג\"ע. והנה להבין זה י\"ל ההפרש שבין משכן לבהמ\"ק שהמשכן הי' מארזים כמ\"ש עצי שטים עומדים והמכסה הי' מיריעות עזים ועורות אלים מאדמי' ועורות תחשים כו' ובהמ\"ק הי' מאבנים ועפר דוקא, שאסור לעשות בו עץ בולט כו' ואכסדראות של עץ כמ\"ש הרמב\"ם פ\"א מהלכות בית הבחירה כו' וע' בס' החינוך מצוה תצ\"ב, רק שהי' כלונסאות של ארזים בתקרת האולם, וצ\"ל מפני מה במשכן הי' הארזים עיקר בבנין והעפר הי' רק בקרקע המשכן למטה, ובמקדש נהפוך הוא שהי' האבנים והעפר העיקר שאפי' הגג הי' מהן ולא הי' עצים רק כלונסאות של ארז הנ\"ל שהי' טפלים לעיקר הבנין.\n<b>וזהו</b> ג\"כ החילוק שבין יוסף ליהודא שהמשכן הי' בחלקו של יוסף שעמד שס\"ט שנה בשילה, וזהו שקדשים קלים נאכלים בשילה בכל הרואה ובירושלים לפנים מן החומה, והיינו לפי שבשילה הוא בחלקו של יוסף וע\"כ נאכלים בכל הרואה וכמ\"ש במד\"ר בשכר שלא זן עיניו מן הערוה ולא רצה להביט ברע לכך זכה שיהי' נאכלים בכל הרואה, ובהמ\"ק הי' בחלקו של יהודא ובנימין. והנה המשכן נק' דירת עראי ובהמ\"ק נק' דירת קבע. וא\"כ אינו מובן למה המקדש הי' מאבנים ועפר דוקא שהוא בחי' דומם שהוא למטה מצומח וחי והמשכן הי' מצומח וחי כו', אך הענין הוא דלא ראי זה כראי זה שאעפ\"י שהדומם למטה מהצומח וחי עכ\"ז יש בו מעלה יתירה מצד שרשו שלמעלה מבחי' צומח וחי כו' דהנה ידוע מחלוקת התנאים בגמרא חגיגה ח\"א שמים קדמה לארץ כמ\"ש בראשית ברא את השמים ואת הארץ וח\"א ארץ קדמה לשמים כמ\"ש ביום עשות ה' אלקי' ארץ ושמים ואלו ואלו דא\"ח שבמחשבה ארץ קדמה לשמים וכשברא ברא השמים תחילה, והענין כי סוף מעשה עבמ\"ת פי' כי הארץ לפי שהוא סוף מעשה ע\"כ שרשה במח' היא בבחי' תחילת המח' אבל שמים שהם תחלת המעשה הם אחרונים במח' כי זהו הכלל שהסוף מעשה עולה בתחילת המח', והיינו לפי שעיקר המכוון נגמר בסוף וכמו שאנו רואים למטה בגשמי' בכל השפעה שעיקר המכוון נשלם בסוף כמו למשל תבואה או אילן שמתחלה נגדל האילן והקש ואח\"כ נגמר הפרי שהוא עיקר המכוון כו' וכן בהשפעת שכל שמשפיע הרב לתלמיד שמתחלה צריך להקדים לו הקדמות ומשלים ואח\"כ מבין את השכל שהוא העיקר, וכן פירש\"י בחומש ע\"פ בראשית ברא אר\"י לא הי' צריך להתחיל את התורה אלא מהחודש הזה לכם, אלא כח מעשיו הגיד לעמו לתת להם נחלת גוים ומכח זה הקדים ברה\"ע כו' (הגם שספר בראשית הוא למעלה משאר ספרים שנק' ספר הישר מ\"מ עיקר התורה היא מהחודש הזה לכם כו'), וכך במח' ארץ קדמה, אך בהשתלשלות ברה\"ע נברא שמים תחלה לפי שארץ מקבל מבחי' שמים וכמ\"ש אני אענה את השמים והם יענו את הארץ, לכך נברא שמים תחלה. וזהו ענין הפלוגתא בגמ' תלמוד גדול או מעשה גדול נמנו וגמרו תלמוד גדול שמביא לידי מעשה, והיינו לפי שבשרש מעשה גדול כי לע\"ל יתעלה בחי' מעשה א\"ח עט\"ב אך"],[4101400130,"לע\"ע תלמוד גדול מפני שמביא לידי מעשה שע\"י תורה דוקא נעשה המצוה כי בחכ' אתברירו, ועי\"ז נעשה המצוה גשמי' שיעורר עי\"ז אתדל\"ע, וזהו [שבפ' ראשונה של] ק\"ש נאמר מתחלה והי' הדברים האלה ושננתם כו' ואח\"כ וקשרתם תלמוד גדול שמביא לידי מעשה אבל לע\"ל יהי' מעשה גדול כי שרש המצוה הוא בבחי' כתר כו'. ושרש הענין הוא דהנה יש בחי' השתלשלות ולמעלה מהשתלשלות, והענין הוא דהנה כדי שיהי' התהוות העולמו' שהם בבחי' גבול מאא\"ס שהוא למעלה מבחי' גבול ואינו בגדר עולמות כלל וכדי שיהי' מקור לעולמות הוצרך להיות צמצום באא\"ס, וזהו ענין יוד של שם הוי' כי יוד הוא בחי' חכ' וכדי שיהי' בחי' חכ' דהנה כתי' כולם בחכ' עשית שהחכ' נחשבת כעשי' גשמי' לפניו וא\"כ כדי שיהי' בחי' חכ' זהו ע\"י צימצום ונקודה כו' ומחכ' ולמטה נמשך דרך השתלשלות, אבל התהוות החכ' מלמעלה מן החכ' אינו נמשך בדרך השתלשלות וכמ\"ש והחכ' מאין תמצא כו' שהוא ע\"י צמצום, אך עיקר המכוון הי' כדי שיהי' התגלות אא\"ס כמו שהוא למעלה מן הצמצום שלמעלה מסדר השתלשלות, והיינו שאח\"כ שנעשה סדר השתלשלות יכולים להמשיך גילוי אא\"ס ע\"י תו\"מ שלמעלה מסדר השתלשלות רק שלכתחלה א\"א להיות גילוי אא\"ס שלמעלה מסדר השתל' שא\"כ לא הי' אפשר להיות התהוות העולמות, רק אח\"כ שנתהווה עולמות ע\"י צמצום יכולים אח\"כ להמשיך גילוי אא\"ס שלמעלה מן הצמצום כו', וכמ\"ש בכתבי האריז\"ל שהתהוו' העולמות הי' מתחלה ע\"י צמצום ואח\"כ המשכת הקו, ולכאו' למה לא נשאר מתחלה הקו אלא לפי שאם הי' נשאר הקו מתחלה לא הי' יכול להתהוות עולמו' בבחי' גבול כמו שהן עתה אלא אח\"כ דוקא שנתהוו העולמות אף שנמשך המשכה מלמעלה מסדר ההשתל' יכולים לקבל ג\"כ ולא יהי' בטלים כו', וכך כדי שיהי' גילוי אא\"ס בעולמות הוצרך להיות מתחילה צמצום באא\"ס כדי שיהי' סדר השתלשלות, ואח\"כ נמשך בחי' גילוי אא\"ס שלמעלה מן הצמצום, וזהו דעת המ\"ד ארץ נבראת תחלה והיינו שעיקר המכוון הי' בשביל הארץ לפי שאדם עלי' בראתי שהוא עיקר המכוון לפי שהוא ממשיך גילוי אא\"ס ע\"י תו\"מ למטה כו' אך כדי שיהי' התהוות בחי' ארץ הוצרך להיות נברא תחלה שמים לפי שבסדר השתלשלות שמים קדמו כו'.\n<b>וזהו</b> ג\"כ החילוק שבין משכן למקדש שהמשכן הי' מצומח דוקא, והיינו לפי שבמשכן הי' הגילוי שבבחי' סדר ההשתל' כי הי' רק דירת עראי של הקדב\"ה וכמ\"ש ואהי' מתהלך מאהל לאוהל כו'. וזהו שבמשכן הי' למעלה יריעות ע\"ש נוטה שמים כיריעה בחי' שמים קדמו, ולכך כל מה שהי' בבריאת העולם הי' במשכן כמ\"ש במדרש, ולכך הי' מצומח וחי שבבחי' סדר השתל' צומח וחי למעלה מדומם כו', אבל בבהמ\"ק שהי' מעין דלע\"ל שיהי' הגילוי שלמעלה מסדר השתלשלות כי הי' דירת קבע של הקדב\"ה דהיינו כי קבע הוא בחי' שלמעלה מסדר השתלשלות, וזהו\"ע המחלוקת שבגמרא בסוכה אי דירת קבע בעינן אי דירת עראי, והיינו שהפלוגתא היא בהמשכה זו של סוכה"],[4101400131,"שממשיכין ע\"י סכך דסוכה מקיפים עליונים, אם הוא דירת עראי מבחי' המשכה שבבחי' סדר השתל' או דירת קבע שלמעלה מסדר השתל', והנה בהמ\"ק שהי' דירת קבע דהיינו גילוי אא\"ס שלמעלה מסדר השתל' ע\"כ הי' מאבני' ועפר דוקא לפי שדומם שהיא סוף מדריגה ע\"כ נעוץ תחב\"ס כו' לפי שבמח' ארץ קדמה. ובזה יובן ג\"כ מה שנשמות עליונות שבג\"ע ירדו למטה בגופים דוקא, והיינו לפי שג\"ע הגם שיושבין ונהנין מזיו השכינה, אך מ\"מ הגילוי שבג\"ע הוא רק מבחי' גילוי אא\"ס שבסדר השתלשלות כו' וכמ\"ש ונהר יוצא מעדן להשקות את הגן, עדן הוא בחי' חכ', והנה חכ' הוא בחי' סדר ההשתל' כי מחכ' נמשך ראשית ההשתל' וכמ\"ש והחכ' מאין תמצא שהוא בחי' ממכ\"ע, וכן ארז\"ל ביוד נברא העוה\"ב שהוא בחי' חכ', אבל תח\"ה יהי' הגילוי מבחי' שלמעלה מן סדר השתל' מבחי' סוכ\"ע וע\"כ יהי' נשמות דוקא בגופים לפי שלגבי עצמות אא\"ס הסוכ\"ע המגביהי לשבת המשפילי לראות כו' שניהם שוין לפניו השוה ומשוה גדול וקטן, ואדרבה כל שהאור גבוה יותר יכול להשפיל יותר וכידוע וע\"כ יהי' נשמות דוקא בגופים, ונשמות גבוהות שהם יותר מג' אלפי' שנה בג\"ע ירדו למטה להתלבש בגוף כדי לקבל ולהנות מאור הסוכ\"ע שלא נתגלה עדיין להםבג\"ע, וזהו ירידה צורך עלי' כו'. אך מ\"מ צריך להיות הנשמה תחלה בג\"ע ואינו יכול לקבל אור הסוכ\"ע כ\"א ע\"י שהי' תחלה בג\"ע ולכך צריכה כל נשמה להיות תחלה בג\"ע ואח\"כ תח\"ה לפי שבהשתל' שמים קדם ואחר שיהי' בג\"ע יכולה אח\"כ לקבל ג\"כ אור הסוכ\"ע שארץ קדמה. והנה זהו ג\"כ ענין יוסף ויהודא שהוא ג\"כ בחי' ומדריגת שמים וארץ ובחי' צומח ודומם כו' כי יוסף לשון תוס' וריבוי שמתוסף והולך בהגדלה והגבהה למעלה והוא ענין בחי' צומח שהוא בחי' יסוד שעולה עד הדעת ודעת עולה עד הכתר, ויהודא הוא בחי' ארץ מל' דאצי' שהוא בחי' הרוממות דאצי' ולכן יהודא הוא בחי' הודאה וביטול שבדומם יש בו בחי' הביטול ביותר כנ\"ל.\n<b>והנה</b> בסדר ההשתלשלות עתה יוסף הוא למעלה מיהודא שהרי המל' מקבלת שפעה וחיותה מן הז\"א ולכן הי' יוסף המלך במצרים שהוא בחי' צומח בחי' גידול והוא הי' המשביר והמשפיע לכולם וכמ\"ש ויוסף הוא השליט על הארץ שהוא מושל על בחי' ארץ שהוא בחי' מל' ויהודה הוא המקבל כו' וז\"ש ויגש אליו יהודה ופי' בזוהר שהוא ענין סמיכות גאולה לתפלה, כי תפלה היא בחי' השתחוואה בחי' ביטול שהוא בחי' יהודה, וגאולה הוא בחי' יוסף שהוא בחי' יסוד כו', והיינו שהסמיכות גאולה לתפלה הוא כמו ענין שארז\"ל הקובע מקום לתפלתו דלכאורה אינו מובן שהרי ארז\"ל אל תעש תפלתך קבע, אלא הענין הוא דהנה פי' הקובע מקום לתפלתו היינו כמארז\"ל עשה תורתך קבע ומלאכתך עראי, והנה אין הפי' קבע ועראי בריבוי ומיעוט שימעט במלאכה שהרי אמרו כל תורה שאין עמה מלאכה סופה בטלה כו' אלא הפי' קבע היינו עיקר המכוון שעיקר הכוונה יהי' הכל בשביל התורה דהיינו שכל כוונתו שעוסק במו\"מ הוא כדי שיוכל ללמוד תורה ולעבוד את ה', וזהו מ\"ש ואספת"],[4101400132,"דגנך בפ' שני' של ק\"ש והיינו שיאסוף את דגנך ג\"כ לבחי' אחד והיינו ע\"י שיעבוד בזה להקדב\"ה וילמוד בכח זה ויקיים מצות עי\"ז נאספים ג\"כ לבחי' אחד מה שהי' תחלה בבחי' פירוד כו'. וזהו ענין והנה אנחנו מאלמים אלומים כו' ע' בת\"א פ' וישב. וזהו ענין כל הקובע מקום לתפלתו דהיינו שכל עיקר כוונתו יהי' בבחי' תפלה כי תפלה היא לשון התחברות כמו התופל כלי חרס והיינו שמחבר את נה\"א המאיר בגוף עם שרש הנפש בחי' מזל שהוא בחי' אלקות ממש ועי\"ז ממשיך ג\"כ מבחי' קבע כמו שהי' בהמ\"ק דירת קבע דהיינו המשכה שלמעלה מסדר השתלשלות וכמאמר רז\"ל מט\"ט קושר כתרים מתפלותיהן של ישראל שנתעלה התפלה בבחי' כתר שלמעלה מן החכ' סדר השתלשלות כו' שהוא בחי' קבע. וזהו ע\"י קביעת מקום לתפלתו שכל עיקר כוונתו היא בתפלה לחבר את נפשו לאלקות בקביעות כו', ומה שאמרו אל תעש תפלתך קבע היינו שלא תעשה בדרך חובה כ\"א רחמים ותחנוני'. וזהו ויגש אליו יהודה שהוא ענין סמיכות גאולה לתפלה והיינו כי כדי שיוכל להיות העלאה של תפלה צריך שיהי' נמשך זה הכח מלמעלה כדי לעורר את העלאה זו, וזהו ענין סמיכות גאולה לתפלה המשכה מבחי' גאולה בחי' יוסף לתפלה ואח\"כ ויגש אליו יהודה שנעשה העלאה של תפלה, והנה זהו ענין ג' ראשונות דש\"ע שהוא בחי' סדור שבחו של מקום וכמארז\"ל לעולם יסדר אדם שבחו ש\"מ ואח\"כ יתפלל, וזהו ויגש אליו יהודה שהוא בחי' הודאה וביטול במציאו' ממש כו' ואח\"כ ויאמר אליו בי אדוני שהוא בחי' י\"ב ברכות אמצעית כי בי הוא י\"ב שהוא בחי' י\"ב בקר דבריאה שהוא כנגד י\"ב שבטים מרכבתא תתאה ויוסף הוא בחי' יסוד ז\"א דאצי', וזהו ויאמר אליו בי אדוני שהוא בקשה שיומשך אליו למרכבתא תתאה י\"ב בקר דבריאה המשכה מבחי' אצי' שהיא בקשת רפאנו ברך עלינו המשכת גילוי אלקות למטה.\n<b>ואל</b> יחר אפך בעבדך הוא ענין נפ\"א שהוא בחי' המשכות יגמה\"ר אל רחום וחנון ארך אפים כו'. ועוד יש לפרש ויגש אליו יהודה ס\"ת שוה, והענין הוא דהנה מה שמבואר לעיל שעתה יוסף למעלה מבחי' יהודה כי בהשתל' שמים קדמו, ולע\"ל יתעלה יהודה כי במח' ארץ קדמה זהו רק לפי הפלוגתא אם שמים קדמו או ארץ קדמה, אך יש עוד דיעה שלישית והיא דעת רשב\"י שסובר ששמים וארץ כאחד נבראו וכמ\"ש קורא אני עליהם יעמדו יחדיו ששניהם שוין, וזהו כענין זכור ושמור בד\"א נאמרו שאף שזכור לדכורא ושמור לנוק' שזהו ענין מעלי שבתא ויומי דשבתא מ\"מ יש בחי' בשבת שלמעלה משניהם שזכור ושמור בד\"א נא', וכמו\"כ שמים וארץ כא' נבראו היינו בחי' שלמעלה משניהם והיינו שאף שבמח' ארץ קדמה דהיינו בבחי' סוכ\"ע מ\"מ בבחי' מקיף הכללי שהוא מח' הקדומה שצופה ומביט כל הדורות שניהם שוה כא' ממש כו' וד\"ל."],[4101400133,"<h3>ויחי יעקב</h3>\n<b>ויחי</b> יעקב בארץ מצרים שבע עשרה שנה ויהי ימי יעקב שבע שנים וארבעים ומאת שנה וצ\"ל למה נא' מספר המועט קודם למספר המרובה. וגם להבין מ\"ש ויחי יעקב בארץ מצרים שבע עשרה שנה מהו ענין שבע עשרה שנה שחושב אותם בפ\"ע. ולהבין זה י\"ל מקודם משארז\"ל יפה שעה א' בתשובה ומעשים טובים בעוה\"ז מכל חיי העוה\"ב דלכאורה אינו מובן זה שהרי מתשובה ומעשים טובים נעשים לבושים להנשמה בכדי שיוכל הנשמ' להנות מזיו השכינה וכמ\"ש ואברהם זקן בא בימים, ופי' בזוהר באינון יומין עילאין דהיינו בבחי' הלבושים של תו\"מ, וא\"כ כיון שהם רק לבושין כדי שיוכל להנות מזיו השכינה עצמה, ואיך הלבושים למעלה מהשגה שבג\"ע כו', והענין הוא דהנה מקודם צ\"ל ההפרש שבין ג\"ע לכללות העולם. והענין הוא דהנה כתי' ואתה מחי' את כולם, והנה החיות שמאיר בכללות העולם דימו אותו חז\"ל לחיות הנשמה המאיר בגוף וכשארז\"ל מה הנשמה ממלא את הגוף כך הקדב\"ה ממלא את כל העולם. והנה אנו רואים שאעפ\"י שהנשמה מתלבשת בגוף ומחי' אותו הנה בגוף יש בו התחלקות רמ\"ח אברים מ\"מ א\"א לומר שבנשמה יש בו ג\"כ התחלקות רמ\"ח כו' שהרי אנו רואים שהסומא מוליד שלם, ואם הי' גם בנפש התחלקות רמ\"ח אברים כמו בגוף, וא\"כ כשנחסר לו אבר ה\"ז חסרון גם בנפש ומאין יוליד שלם, א\"ו שאין הנשמה מתחלקת לרמ\"ח אברים רק שהנשמה מתלבש' במוח או בלב וממילא הוא מחי' את הגוף רמ\"ח אברים שלה וכמו למשל כשמעמידין נר על השולחן נתמלא כל הבית אור, וכך כשמתלבשת הנפש במוח ממילא מקבלין כל הרמ\"ח אברים ממנה חיות אף שאינה מתלבשת בכל הרמ\"ח אברים כו', והנה כמו שהוא בנפש האדם כמו\"כ הוא בכל דבר כמו למשל הגלגלים שהם עגולים, שא\"א לומר שהחיות המתלבש בו הוא ג\"כ עגול, אלא הוא אור פשוט, רק שהוא מתלבש בו וממילא יקבל ממנו חיות.\n<b>והנה</b> אף שאנו רואים זה ומשיגין שאור הנפש הוא למעלה מהתחלקות רמ\"ח כנ\"ל מ\"מ אין אנו משיגים את עצמות מהות הנשמה איך ומה הוא, רק שאנו משיגין שישנו לנשמה בהכרח ממה שהגוף יש לו חיות, ומאין יש להגוף חיות ע\"כ בהכרח לומר שיש בו נשמה שמחי' אותו, אבל מהות הנשמה אין אנו משיגין כלל, וכך בכללות החיות של כל העולמות, אעפ\"י שאנו משיגין שמתלבש בהם חיות אלקי כיון שאנו רואים שהעולם שהוא כמו גוף גדול ויש לו חיות ומאין יש להם חיות, בהכרח שמלובש בהם חיות אלקי שמחי' אותם, מ\"מ אין זה רק השגת המציאות, אבל מהות של חיות אלקי"],[4101400134,"המלובש בהם אין אנו משיגים כלל, וזהו בכללות העולם כו' וזהו שנק' עולם מל' העלם שחיות אלקי הוא בהם בהעלם לפי שאין אנו משיגי' מהות של אוא\"ס ב\"ה כו', אבל בג\"ע מאיר שם אלקות בבחי' גילוי בבחי' השגת המהות ממש שמשיגי' שם מהות של אא\"ס וכמ\"ש יושבין ונהנין מזיו השכינה שהיא השגת המהות ממש, וכמ\"ש לע\"ל ואמר ביום ההוא הנה אלקינו זה, ופירש\"י כאו\"א מראה באצבעו, שהיא השגת המהות, וכך בג\"ע מאיר שם אור אלקי בבחי' גילוי עד שמשיגי' מהות של אא\"ס, וזהו שארז\"ל מוטב דלידייני' וליתי לעלמא דאתי שכדאי כל יסורי גיהנום שאפי' כל יסורי איוב אין כדאי כנגד שעה א' של גיהנם ואעפי\"כ כל יסורי גיהנם הם כדאי אפילו לגבי שעה א' של קורת רוח בג\"ע והיינו לפי ששם הוא השגת המהות כו', וזהו מ\"ש ויטע הוי' אלקי' גן בעדן שם מלא, כי בבריאת העולם לא נא' רק שם אלקי' בראשת ברא אלקי' משא\"כ בג\"ע נא' השם מלא הוי' אלקי' שמאיר שם בחי' שם הוי' כו'.\n<b>אך</b> הנה ההפרש שבין ג\"ע לכללות העולם שהוא בין השגת המציאות להשגת המהות זה י\"ל רק בין עוה\"ז לג\"ע, אבל עדיין י\"ל מהו ההפרש בין עולמות עליונים לג\"ע דהיינו עולם המלאכים וחיות הקודש ואופנים כנ\"ל שא\"א לומר הם אין משיגין רק השגת המציאות לבד, שהרי הם אומרים קדוש ברעש גדול באהבה ברשפי אש בכלות הנפש כו' והחיות נושאות את הכסא ובודאי גם הם משיגים השגת המהות, וא\"כ י\"ל מהו ההפרש ביניהם ובין נשמות שיושבין ונהנין מזיו השכינה בג\"ע כו'. והענין הוא דהנה כתי' זכר רב טובך יביעו וצדקתך ירננו, והנה צדקתך הוא בחי' מל' וכמ\"ש בזהר צדק מלכותא קדישא והיינו שכל השגתם הוא רק בבחי' מל' וכמ\"ש מל' מל' כ\"ע שחיות כל העולמות הוא רק מבחי' מל' שהוא בחי' שם וכמ\"ש מלך שמו נקרא עליהם שאינו נוגע אל עצמו כלל שהוא זיו והארה בעלמא, וזהו מ\"ש מלא כה\"כ ותרגומו זיו יקרי' שהוא רק הארה בעלמא מבחי' מל', וכתי' את השמים ואת הארץ אני מלא דמשמע מהו\"ע, והיינו שאני מלא היינו מהו\"ע, אבל הוא רק בהעלם שאינו מאיר בגילוי, ולכך השמים והארץ בשוה לפי שמאיר בהם בהעלם כו', ומה שמאיר בגילוי הוא רק בחי' זיו והארה מבחי' מל' כו', והנה השגת המלאכי' הוא בבחי' מל' שהוא מקור ושרש חיותם והתהוותם והיינו שהמלאכים שבכל עולם משיגי' את בחי' המל' שבכל עולם דהיינו מלאכים דבריאה את בחי' מל' דבריאה ומלאכי' דיצי' את בחי' מל' דיצי' כו', וזהו וצדקתך ירננו צדקתך שהוא בחי' מל' ירננו בבחי' רינה דהיינו בבחי' השגה, והיינו השגת המהות דהנה רינה הוא דוקא מבחי' השגה שמשיג את הדבר עי\"ז נעשה אצלו התפעלות בבחי' רינה כו', אך זכר רב טובך יביעו דהיינו בחי' טוב הוא רק להם בבחי' יביעו שאין להם השגה בבחי' טוב דהנה ר\"ת את השמים ואת הארץ בגי' טוב, והיינו שבבחי' את השמים ואת הארץ אני מלא אין להם השגה כו', רק שרצונם לבד ליכלל בבחי' טוב אבל אינם משיגים את הטוב כלל, רק זכר רב טובך יביעו בחי' זכר הארה מבחי' טוב לבד יביעו כי כל"],[4101400135,"השגתם הוא רק בבחי' מל', אבל בבחי' טוב שהוא יסוד ז\"א כי יסוד נק' טוב אין להם השגה, אבל נשמות שבג\"ע משיגים את בחי' הטוב וכמ\"ש ועמך כולם צדיקי' וכתי' אמרו צדיק כי טוב שמאיר להם מבחי' רב טוב מבחי' יסוד הממשיך מבחי' חכ' ג\"ר כו', נמצא שבדרך כלל יש כאן ג' מדריגות דהיינו השגות נש\"י שבגופים שבעוה\"ז שהיא רק בחי' השגת המציאות, וגם זה הוא בחי' השגה וכמ\"ש שאו מרום עיניכם וראו מי ברא אלה מי הוא בחי' עצמות אוא\"ס, אך זהו רק השגת המציאות לבד כנ\"ל, והשגת המלאכים שמשיגים בחי' השגת מהות של אא\"ס אך זהו רק השגה בבחי' מל' מלכותך מלכות כ\"ע, והשגת דנשמות שמשיגים השגת המהות בבחי' גבוה יותר דהיינו בבחי' טוב ג' ראשונות כו'.\n<b>והנה</b> יש עוד בחי' רביעית שהוא למטה מכולם והיא בעולם העשי' ששם מדור הקליפו' והן הע' שרים שכללותם המה י' כתרין דנוגה כידוע שמכירין את בוראם שמהווה אותם מאין ממש ואעפי\"כ יכול להיות יש ודבר בפ\"ע כנ\"ל בבחי' נפרד כו\"ע כע\"ז, והוא לפי שכח אלקי מצומצם בהם מאד מאד בריבוי הסתרות והעלמות ורק דקארו לי' אלקא דאלקי' כלומר שהוא כח הראשון המקור האמיתי לכל כחות מוגבלים הנמצאים ממנו כו' והוא ענין כח הפועל בנפעל לבד ובחי' אא\"ס המצומצם בהם זה האלקי מוסתר ונעלם מהם בתכלית ההעלם, לכך אעפ\"י שיודעים ומכירים ומשיגים את בוראן בבחי' השגת המציאות אין בהם התפעלות הביטול ממציאותם כלל אלא יהי' ליש ודבר בפ\"ע מפני שהיש מסתיר את האין ונראה להם היש בלבד, אבל האין האלקי אין בהם אלא בבחי' השגה מרחוק בלבד, וזהו מדריגת הע\"ש דקרו לי' אלקא דאלקי', אך נש\"י למטה בעוה\"ז אף שאין להם רק השגת המציאות לבד מ\"מ אין אור אלקי מוסתר בהם ואין היש מסתיר על האין, ולכך הם בטלים לאלקות, ונשמות בג\"ע הם למעלה גם מן מלאכי' לפי שנש\"י עלו במח' ושרש המלאכי' הוא רק מבחי' דבור בחי' מל' ע\"כ אין להם השגה רק בבחי' מל', משא\"כ נש\"י עלו במח' וע\"י תו\"מ שמקיימין ששרשן מבחי' אנכי וכמ\"ש והי' הדברים האלה אשר אנכי מצוך היום עי\"ז משיגים השגת המהות בבחי' אא\"ס ממש למעלה מהשגת המלאכים כנ\"ל.\n<b>אך</b> הנה כדי שיוכלו הנשמות לקבל זיו השכינה שבג\"ע הגם כי שרש נש\"י עלו במח' מ\"מ ירדו למטה בבחי' בריאה יצי' כו' וכמ\"ש נשמה שנתת בי טהורה היא אתה בראת יצרת נפחת בי וא\"כ איך תוכל הנשמה לקבל זיו השכינה שבג\"ע. וזהו ענין המצות שנעשי' לבושין לנפש בכדי שע\"י הלבושי' יכולים לקבל אור זיו השכינה, והיינו כמו למשל אור השמש שאין יכולים להביט באור השמש מחמת תוקף בהירות אורו, אך ע\"י אספקלרי' זכוכי'"],[4101400136,"שמסתיר מעט על עצם אור השמש עי\"ז אנו יכולים לקבל את אור השמש כנ\"ל, או למשל כשצריך הרב להשפיע לתלמידו שכל עמוק שאינו לפ\"ע המקבל צריך להלביש את השכל במשל דהיינו שמלביש את השכל בדבר זר, וע\"י המשל יכולים להשיג את הנמשל כו' והנה לפי\"ז המשל הוא למטה מהנמשל לפי שע\"י יכולים לקבל את הנמשל. אך מ\"מ צריך לומר ששרש המשל הוא למעלה מהנמשל, לפי שכדי שיכול להמציא את המשל צריך שיהי' בר שכל גדול יותר, וכמ\"ש בשלמה וידבר שלשת אלפי' משל, והיינו לפי שבשלמה כתי' ויחכם מכל האדם אשר על פני האדמה ע\"כ הוא יכול להמציא ג' אלפים משל, וכן ר\"מ לפי שהי' מנהיר עיני חכמים בהלכה והי' מקור האור הי' יכול לומר שלש מאות משלים והיינו לפי ששרש המשל הוא למעלה לפי שע\"י יכולים להשיג את הנמשל, וזהו מ\"ש במשה ויבא משה בתוך הענן לפי שמשה לחם לא אכל ארבעים יום וארבעים לילה וא\"כ צ\"ל שהי' ניזון מזיו השכינה וכמ\"ש לחם אבירים אכל איש לחם שמלאכי השרת אוכלים והוא בחי' זיו השכינה וכמ\"ש במדרש ואתה מחי' את כולם מלמד שכולם צריכי' למזון ומזון של מלאכי השרת הוא בחי' זיו השכינה, וא\"כ איך הגוף גשמי יהי' נזון מזיו השכינה, וכדי שיוכל הגוף לקבל את זיו השכינה, זהו ע\"י הענן דהיינו ששרש הענן נמשך ממקום גבוה מאד שהוא בחי' ישת חושך סתרו, ונמשך למטה עד שנעשה לבוש כו' וע\"י יכול להיות נמשך שיהי' גם הגוף גשמי ניזון מזיו שכינה, וזהו ג\"כ ענין המצות שכדי שתוכל הנשמה שירדה למטה להנות מזיו השכינה זהו ע\"י הלבושים של מצות, והיינו שאעפ\"י שהמצות נמשכו למטה בגשמי' מ\"מ שרש המצות הוא למעלה גבוה מאד כי תרי\"ג מצות דאו' וז' דרבנן הם תר\"ך עמודי אור שהוא בחי' כתר וע\"כ ע\"י יכולים לקבל את זיו השכינה שבג\"ע השגת המהות. וזהו יפה שעה א' בתומע\"ט בעולם הזה מכל חיי העוה\"ב, לפי ששרש המצות הוא למעלה מבחי' השגה שבג\"ע, והיינו כי שרש השגה שבג\"ע הוא מבחי' חכ' וכמ\"ש ונהר יוצא מעדן להשקות את הגן, אבל שרש המצות הוא מבחי' כתר, וזהו מ\"ש שכר מצוה מצוה, דהיינו שעיקר השכר של מצות היא מצוה עצמה לפי ששרשן מאד נעלה כו', וזהו לע\"ל דוקא שלע\"ל יתגלה עיקר השכר של המצות השגת המהות ממש וכמ\"ש כי עין בעין יראו את ה', והנה להבין פי' עין בעין הענין הוא דהנה יש שני בחי' עין דהיינו שני בחי' ראי', דהיינו ראי' מלמטה למעלה וכמ\"ש שאו מרום עיניכם וראו מי ברא אלה שהוא בחי' השגת המציאות ואעפי\"כ יש בזה בחי' ראי' שהוא בחי' השגת המציאות של אא\"ס שמי ברא אלה, מי היינו בחי' עצמותו ומהותו כו', אך מ\"מ היינו בחי' ראי' ממטה למעלה שהיא בחי' יחו\"ת, אך בחי' עין דלעילא היינו בחי' ראי' של השגת המהות בחי' יחו\"ע גילוי בחי' זה כו'.\n<b>והנה</b> לכאור' אינו מובן כיון שמאיר גילוי בחי' עין דלעילא למה צריך לבחי' עין דלתתא, וכתי' עין בעין יראו שמשמע שצריך שיהי' ב' הבחי' עין דוקא, והענין הוא שכדי שיהי' גילוי בחי' עין דלעילא זהו דוקא ע\"י בחי' עין"],[4101400137,"דלתתא, ולפ\"ע הראי' של עין דלתתא שמשיג השגת המציאות לפ\"ע זה נתגלה בחי' עין דלעילא, דהנה ידוע שירידת הנשמה בגוף הוא כדי לברר את נה\"ב שמצד עצמה אינה צריכה תיקון כלל רק שירדה לברר נה\"ב, וכדי שיתפעל נה\"ב מאלקות זהו דוקא ע\"י עין דלתתא בחי' השגת המציאות של בריאת יש מאין דוקא לפי שנה\"ב לא יתפעל רק מבחי' השגה יש מאין כו', וזהו שמאריכין בפסוד\"ז שהוא הכל בדברים גשמי' כמו הללו את ה' מן הארץ תנינים וכל תהומות אתה עשית את השמי' והיינו לפי שכדי שיתפעל נה\"ב זהו דוקא ע\"י בריאת יש מאין כו'. והנה ע\"י שיתברר נה\"ב עי\"ז נעשה בחי' גילוי בחי' עין דלעילא בחי' השגת המהות, וזהו מ\"ש ימי שנותינו בהם שבעים שנה, והיינו שניתן לו ימי חיי' שבעים שנה כדי לברר את נה\"ב ועי\"ז נעשה לפ\"ע זה גילוי בחי' עין דלעילא.\n<b>ובזה</b> יובן מ\"ש במדרש שדוד לא היו לו חיים ונתן לו אדה\"ר ע' שנה, לפי שאדה\"ר הי' צריך לחיות אלף שנה יומו של הקדב\"ה וחי רק תשע מאות ול' שנה ונתן ע' שנה לדוד, והנה האבות נתנו ג\"כ לדוד ע' שנה לפי שאברהם הי' צריך לחיות ק\"פ שנה ולא חי רק קע\"ה ונתן ה' שנים לדוד ויעקב הי' צריך לחיות כמו אברהם קע\"ה ונתן ך\"ח לדוד ויוסף הי' צריך לחיות כמו יעקב ונתן ל\"ז לדוד, וזהו שיעקב נתן לו כ\"ח שנה שהוא בחי' ועתה יגדל נא כ\"ח אד' מקור של שם אד' ויוסף נתן לו ל\"ז שנה שהוא כנגד ג' מוחי' וז' מדות, וע\"כ נתן לו יוסף יותר לפי שעיקר תוס' אורות הוא בחי' יוסף, וה' שנה של אברהם הוא ה' חסדים כו'. והנה דוד לא חי רק ע' שנה לבד. והענין הוא דשני בחי' ע' שנה זהו שני בחי' עין, עין בעין יראו, דע' שנה של אדה\"ר זהו בחי' עין דלתתא, לפי שאדה\"ר שחי אלף שנה זהו אחר חטא עה\"ד וע' שנה של האבות הוא בחי' עין דלעילא שהוא בחי' השגת המהות, והיינו כי יש כמה בחי' בג\"ע ג\"כ וכמ\"ש מרוב כל שיש כמה בחי' כל ולפ\"ע הגילוי של עין דלתתא כך נמשך לפ\"ע זה הגילוי של עין דלעילא בחי' השגת המהות, אך מה שלא חי רק ע' שנה לבד, הענין הוא דעיקר הי' אצלו רק בחי' עין דלתתא רק שעין דלעילא הי' מאיר אצלו בבחי' מקיף לבד.\n<b>ובזה</b> יובן מ\"ש ויחי יעקב בארץ מצרים שבע עשרה שנה, דהנה פי' ויחי זהו כענין מ\"ש מי האיש החפץ חיים אוהב ימים לראות טוב שהוא בחי' חיים אמיתים זהו ע\"י ארץ מצרים שהוא ע\"י שבירר את בחי' מצרים וגבולים שהוא בחי' נה\"ב ועי\"ז נתגלה בחי' שבע עשרה שנה שהוא בחי' טוב התגלות המהות של אא\"ס. והנה אח\"כ פי' ויהי ימי שני חיי' שבע שנים, והיינו שכל עיקר עבודתו של יעקב הוא כדי לברר את בחי' ז' מדות שהעיקר הוא לברר את המדות, דהנה שרש המדות הוא למעלה מבחי' חכ' דהיינו מבחי' עולם התהו שלמעלה מתקון רק שהם נמשכי' ע\"י השכל והשכל מורה להם דרך, אבל שרשן הוא למעלה מן השכל, וזהו כמו יפה כח הבן מכח האב, והיינו לפי"],[4101400138,"שג' שותפין הם באדם אב ואם והקדב\"ה נותן בו נשמה, וע\"כ מצד הנשמה יפה כח הבן כו', וכך המדות אעפ\"י שנולדים מן השכל שנק' אב ואם אעפי\"כ מצד הנשמה שבהם הם למעלה מבחי' חכ', רק שנפלו למטה ונעשה לעומת זה ז' מדות רעות כו' וע\"כ העיקר הוא כדי לברר את בחי' המדות, וזהו ענין שם מ\"ב שהוא בחי' ז' מדות וכל אחד כלול מו', וע\"י בחי' בירור המדות עי\"ז נעשה העלאה למעלה מאד כי שם מ\"ב הוא בחי' העלאה, וזהו שכל עיקר עבודתו של יעקב הוא כדי לברר את המדות, וזהו מ\"ש ביעקב אעבדך שבע שנים ברחל בתך כו', וזהו ג\"כ שיעקב הוא בגי' ז\"פ הוי', והיינו לפי שהמשיך בכל ז' המדות את בחי' הוי' וכל עיקר עבודתו הי' לברר את הז' מדות וזהו ויהי ימי יעקב שבע שנים, ואח\"כ עי\"ז שבירר את המדות עי\"ז וארבעים ומאת שנה שהוא שני פעמים ע' דהיינו עין בעין שע\"י עין דלתתא עי\"ז נתגלה בחי' עין דלעילא, והנה ביעקב שהי' מאיר אצלו בבחי' גילוי ממש עין דלעילא וכמ\"ש וישכון בטח בדד עין יעקב שביעקב הי' מאיר מבחי' בדד שהוא בחי' ונשגב ה' לבדו ביום ההוא כו' ע\"כ חי מאה וארבעים ב' בחי' עין משא\"כ דוד עיקר הי' אצלו רק בחי' עין דלתתא ע' שנה של אדה\"ר, וע' שנה של האבות הי' מאיראצלו רק בבחי' מקיף אבל לא נמשך אצלו בבחי' גילוי ע\"כ לא חי רק ע' שנה לבד וד\"ל."],[4101400139,"<h3>הבאים ישרש יעקב</h3>\n<b></b><b>בס\"ד, יום ש\"ק פ' שמות תזר\"ח לפ\"ק</b>\n<b>הבאים</b> ישרש יעקב יציץ ופרח ישראל, כתיב קדש ישראל לה' ראשית תבואתה, הנה תבואתה קאי על המצות שנקראים בשם תבואה כמ\"ש ואספת דגנך וארז\"ל זה מקרא כי דגן תירש ויצהר זהו מקרא משנה תלמוד, וע\"ז א' קדש ישראל כו' ראשית תבואתה שנש\"י הם ראשית במדריגה מתבואתה הם המצות. וכמו שידוע ממאמרי רז\"ל שממעשה המצות בעוה\"ז"],[4101400140,"מזה נעשה לבושים לנשמות לג\"ע. מכוונת המצות נעשה לבושי' לגעה\"ע, וממעשה המצות עצמן נעשה לבושים בגעה\"ת. ופעם מצינו שהמצות נקראים בשם פירות וכמארז\"ל שלא הניחוהו לעשות פירות מאי פירות אילימא כו' אלא מאי פירי מצוה, ולהבין כ\"ז ילה\"ק מאמר רז\"ל נתאוה הקב\"ה להיות לו דירה בתחתונים, וצ\"ל הלא את השמים ואת הארץ אני מלא ומהו ענין דירה בתחתונים דוקא, אך הנה ארז\"ל מה הנשמה ממלא את הגוף כך הקב\"ה ממלא את העולם, הנה דימו חז\"ל התפשטות חיות אלקות תוך כל העולמות כדמיון התפשטות חיות הנפש תוך הגוף, שאנו רואים שגם שחיות הנפש מתפשט בכל הגוף ברמ\"ח איברים להחיותם ולקיימם כו' מ\"מ אין השפעת חיות הנפש בהם בגילוי והשגה ממש שגם שהנפש מלובשת בכל האברים ביד וברגל וכדומה אעפ\"כ אין בהם השגה וגילוי ממש רק שמחי' אותם בלבד, משא\"כ השראת הנפש במוח ששם הוא בגילוי והשגה שכל ממש, אשר ע\"כ נקראת הנפש נפש השכלית נפש המשכלת נפש המדברת, כי החילוק שבין המדבר לשאר בע\"ח שלא נמצא בהם כח הדיבור רק באדם שיש לו נפש השכלית כי בצלם אלקים עשה את האדם מחמת שבמוח שורה הנפש בגילוי והשגה ממש, משא\"כ בשאר כל האיברים שרק פועלת בהם פעולת כאו\"א ביד לעשות וברגל להלוך אבל לא גילוי השגה כדוגמת השראתה במוח ששם גילוי השגת שכל ממש.\n<b>ועפ\"ז</b> יובן ענין נתאוה הקב\"ה להיות לו דירה בתחתונים, שגם שאת השמים ואת הארץ אני מלא וכמ\"ש ואתה מחי' את כולם שכל העולמות חיים וקיימים מאלקותו ית', עכ\"ז הרי הוא דוגמת התפשטות הנפש בתוך כל חלקי הגוף שאף שמחי' אותם מ\"מ החיות הוא בהעלם כמו\"כ למעלה בשגם שחיות כל העולמות נמשך ממנו ית' עכ\"ז החיות אלקות מוסתר בהם בהעלם, אבל מ\"ש דירה בתחתונים ה\"ז דוגמת משכן הנשמה במוח שהוא בגילוי והשגה כמו\"כ הו\"ע דירה בתחתונים הוא שחיות אלקות שבהם הוא בגילוי ממש לא כדוגמת חיות הנפש בשאר כל האיברים וכנ\"ל, וזהו\"ע התגלות אלקות שהי' במקדש וכמ\"ש ודברתי אתך ונועדתי לך וכו' וידבר אל משה מאוה\"מ דוקא ששם הי' גילוי אלקות שהי' במשכן דוקא דירה בתחתונים, ועיקר הגילוי יהי' לע\"ל שאז יהי' ההתגלות אלקות ביתר שאת וכמ\"ש ואמר ביום ההוא הנה אלקינו זה גילוי ממש, וזהו ענין הברכות שאנו מברכין בכי\"ו, חייב אדם לברך מאה ברכות פי' ברוך הוא מלשון בריכה שיומשך ויתגלה אתה הוי' למטה שיתגלה למטה בחי' ממכ\"ע וסוכ\"ע והוא ע\"י יוד צמצום ה\"א התפשטות כו'.\n<b>ופי'</b> ענין מאה ברכות דוקא הוא כי הנה ידוע שיש ג' בחי' נפש רוח ונשמה, משכן הנשמה במוח ובלב שורה רוח החיים והנפש בכבד כו', והנה רוח החיים שבלב מקבל מנשמה רק חלק עשירי ועד\"מ שאנו רואים כי לא כל ההשגה שהשיג באה בהתגלות המדה כשמתבונן באלקות איך שכולא קמי' כל\"ח ועי\"ז ואהבת כו' לא כל השגת המוח באה למטה במדה שבלב כי הי' בא"],[4101400141,"לכלות הנפש ממש רק שמקבל חלק עשירי בלבד והוא רק מקצת ההשגה, וכן הנפש מרוח מקבל ג\"כ רק מעשר בלבד, וכן הענין למעלה כי הנה כ' נשבע ה' בנפשו כידוע שיש עולם שנה נפש, עולם הוא בחי' מקום, שנה הו\"ע הזמן, נפש הוא חיות אלקות המחי' את המקום והזמן, ובחי' רוח גבוה מהנפש וכמ\"ש לא ידון רוחי באדם שבחי' רוח שלמעלה לא נמשך למטה וכמ\"ש עד יערה עלינו רוח ממרום, והנה כ' אם ישים אליו לבו רוחו ונשמתו אליו יאסוף שע\"י שישים אליו לבו עי\"ז יגיע לבחי' רוח ונשמה שלמעלה וזה\"ע מאה ברכות הוא בחי' נשמה שנמשך למטה בהתגלות, וזהו פי' אם ישים שפי' ל' עשיי' וכמ\"ש ואלה המשפטים אשר תשים, שפירושו שאעפ\"י שאם ישים שהוא רק עשיי' בלבד כי מה יתרון לו לאדם אף שיש לו קצת חיות מ\"מ הרי הוא רק עשיי' בלבד, אעפ\"כ עי\"ז רוחו ונשמתו אליו יאסוף שעי\"ז יעלה ויגיע לבחי' רוח ונשמה שלמעלה, וזה\"ע מאה ברכות שחייב אדם לברך בכי\"ו וכמ\"ש בכי\"ו אברכך שבכל יום ויום מימי שנותינו בהם שבעים שנה ובכל שנה יש שס\"ה ימים צריך להמשיך בחי' דירה בתחתונים התגלות אלקות למטה ממש, וזהו הכל ההמשכה שע\"י הדבור בברכת המצות.\n<b>אך</b> עיקר ההמשכה הוא ע\"י מעשה והו\"ע עשיית המצות בפו\"מ דוקא, וכידוע שכל מה שגבוה יותר הוא בא בגילוי למטה דוקא ועד\"מ מחותם שעל האבן טוב מצד הברקת האבן אין ניכרים שם האותיות רק כשחותמין על השעוה דוקא שם ניכרים האותיות, ולכן נקראים המצות בשם (פירות) וזריעה עד\"מ שזורעין גרעין בארץ שבגרעין כלול כל כח הפרי שיצמח ממנו אח\"כ רק שהוא בהעלם וכשזורעין אותו בארץ עי\"ז כח הצומח שבארץ שהוא מביא מהעלם לידי גילוי אח\"כ שיצמח ממנו בתוס' וריבוי, כמו\"כ הו\"ע המצות שנקראים בשם זריעה וכמ\"ש זרעו לכם לצדקה וכו' זורע צדקות, שגם שהמה נמשכו למטה בעשיי' עכ\"ז הרי יש בהם בהעלם כל אורות עליונים שמרומזים בהם וכמו ד' בתים דתפילין שמורים על ד' מוחין וכן ל\"ב ציצית שרשם הוא ל\"ב נ\"ח רק שנמשכו למטה בגשמיות וה\"ז דוגמת הגרעין שזורעין בארץ, אך עי\"ז אח\"כ יהי' מהם הצמיחה בתוס' וריבוי וכמ\"ש מצמיח ישועות והו\"ע הצמיחת אורות עליונים שיהי' אח\"כ וכמ\"ש אור זרוע לצדיק, ופי' ישועות ל' הפנה וכמו וישע ה' כו' שיומשך אח\"כ גילוי אורות עליונים משרש התומ\"צ. ודוקא ע\"י מעשה המצות דעכשיו וכמשל מזריעה הנ\"ל ולכן נקראים המצות בשם תבואה ופרי מאי פירי מצוה וכנ\"ל. אך הנה מהמשל דזריעה הנ\"ל יובן שעיקר הצמיחה דוקא ע\"י הארץ שזורעין בו הגרעין אז יהי' צמיחה בתוס' ברכה, וכן הענין ג\"כ במצות שעיקר ענין צמיחתם אח\"כ זורע צדקות מצמיח ישועות הוא ע\"י הארץ שע\"י כח הצומח שבו שמביא מהעלם לידי גילוי והו\"ע נש\"י שנקראים בשם ארץ וכמ\"ש כי תהיו לי ארץ חפץ ופי' חפץ הוא מה שהוא עיקר המכוון, כי יש חפץ ורצון, רצון נקרא ג\"כ מה שהוא רצון לרצון אחר שהוא עיקר הכוונה והרצון הקדום הוא רק דרך אגב, וחפץ נקרא מה שהוא"],[4101400142,"פנימי' הכוונה, וזהו ואתם תהיו לי ארץ חפץ שישראל הם עיקר הכוונה וכמ\"ש רק באבותיכם חשק הוי' וחפץ וחשק הוא ענין א', וכמ\"ש בג' לשונות של חבה נק' ישראל בחשיקה ודביקה וחפיצה כו', וע\"י ישראל שנק' ארץ חפץ על ידם דוקא יהי' עיקר סיבת צמיחת המצות לע\"ל.\n<b>והענין</b> הוא כי הנה כ' מלכותך מכ\"ע וכתיב כה אמר ה' מלך ישראל וגואלו דוקא, והענין יובן כי הנה ארז\"ל גדולים מעשה צדיקים יותר ממעשה שמו\"א, כי מעשה שו\"א הו\"ע מאין ליש שאין זה חידוש למעלה רק אצלינו ה\"ז חידוש ופלא אבל למעלה הרי זה כל סדר השתלשלות ועו\"ע יש מאין, משא\"כ מעשה הצדיקים גדולים יותר שהם עושים מיש לאין שע\"י ביטול היש שלהם וזה\"ע מה שנש\"י נק' ארץ חפץ פנימי' ועיקר המכוון של כל העולמות, כי מלכותך מכ\"ע הרי סדר הבריאה הוא יש מאין שחיות אלקות שבתוך הנברא הוא בהעלם והנברא הוא יש ממש ומה שנמשך מאין אין זה חידוש למעלה, משא\"כ נש\"י הם עושים גילוי אלקות בחי' מלכותו ית' ולכן נק' מלך ישראל גילוי מדת המלוכה ביטול היש, וזהו שארז\"ל למה קדמה שמע לוהא\"ש כדי שיקבל עליו עומ\"ש תחלה ואח\"כ יקבל עליו עול מצות שבתחלה צריך להיות בחי' ארץ חפץ ואח\"כ יוכל להיות זריעת התומ\"צ וכנ\"ל, וזהו מ\"ש אשריכם זורעי על כל מים שזריעת המצות גבוהים מבחי' מים שהו\"ע ונהר יוצא מעדן להשקות את הגן השגות אלקות שבג\"ע נשמות יושבים ונהנים מזיו השכינה, אבל זריעת המצות הוא על כל מים ע\"ד מ\"ש אז תתענג על הוי' למעלה מבחי' שם הוי' שהוא ע\"י יוד צמצום כו' משא\"כ המצות שע\"י נש\"י הם גבוהים יותר מזה לפי שהם עיקר הכוונה ולכן כ' קדש ישראל ראשית תבואתה שישראל הם ראשית לתבואת המצות לפי שהם נקראים הארץ חפץ שבם וע\"י דוקא יהי' צמיחה אח\"כ דירה בתחתונים וכנ\"ל.\n<b>וזהו</b> הבאים ישרש יעקב, כי הנה יעקב הוא בחיר שבאבות, הקול קול יעקב, ואין קורין אבות אלא לג' שהם אברהם יצחק ויעקב, וא\"א לבא לבחי' יעקב א\"ל שיקדים תחלה בחי' אברהם ויצחק, והו\"ע המשכת ג' קוין קו הימין קו השמאל ואמצעי, והוא כמ\"ש בזוהר בכי' תקיעא בלבאי מסט' דא בהתבוננותו בגדולת הבורא איך שכולא קמי' כל\"ח וכשמתבונן בפחיתת ערכו איך שהוא רחוק מאלקות עי\"ז בכי' תקיעא בלבאי והוא קו השמאל בחי' יצחק, ואח\"כ חדוה תקיעא בלבאי בהתבוננותו כי מצד אלקותו ואא\"ס בעצמותו הלא את השמים ואת הארץ אני מלא עי\"ז ישמח ישראל בעושיו, ואח\"כ מעורר רחמים על נפשו והוא מדתו של יעקב וזהו מ\"ש רק באבותיך חשק ה' ורק הוא ל' מיעוט כי רק ע\"י בחי' אבותיך אין קורין אבות אלא לג' בזה חשק הוי' שתקרא בשם ארץ חפץ וכנ\"ל וע\"י כן יוכל להיות אח\"כ זריעת המצות, וזהו"],[4101400143,"הבאים ישרש יעקב שע\"י בחי' יעקב ובהקדם הב' בחי', הב' אבות אברהם ויצחק ג\"כ, עי\"ז ישרש יהי' זריעת והשרשת המצות בארץ חפץ ובזה יהי' הצמיחה אח\"כ, יציץ ופרח ישראל, שהפריחה והצמיחה שייך לבחי' ישראל, והוא ע\"ד מ\"ש כה אמר ה' בוראך יעקב יוצרך ישראל ובמדרש ע\"ז אומרים לעולם מי בראך יעקב בראך מי יצרך ישראל יצרך, והענין הוא כי הנה בריאה ויצירה הוא ג\"כ ענין חומר וצורה, כי בכל הנבראים יש חומר וצורה וכמ\"ש פעם א' בדבר ה' שמים נעשו הרי שחיות העולמות נמשך מבחי' דבר ה' ורוח פיו ופעם כ' כל אשר חפץ ה' עשה שנמשכו מבחי' חפץ ורצה\"ע, רק הענין הוא שחומר הנבראים נמשכו מבחי' דבר הוי' והו\"ע עשרה מאמרות ויאמר אלקים יהי רקיע שקאי רק על החומר לבד כי הרי לא נא' שם צורתו איך ומה היא, וצורת הנבראים הוא מבחי' חפץ ורצה\"ע, ובכל דבר יש בו חומר וצורה כמו גוף ונפש שהגוף הוא החומר והנפש הוא צורתו של הגוף לבד צורת חומר הגוף שיש לו ג\"כ, וכמ\"ש וייצר ה' אלקים את האדם וייצר בב' יודי\"ן, והנה במצות יש ג\"כ חומר וצורה וכמ\"ש בזוהר גופא דאורייתא לבושא דאורייתא נשמתא דאורייתא, גופא דאורייתא הם מעשה המצות בפו\"מ, לבושא הוא בחי' פשט התורה בגשמיות, נשמתא הוא פנימית הכוונה של המצות שהם צורתם והו\"ע תענוג ופנימי' אא\"ס שיתגלה ע\"י מעשה המצות לע\"ל כי טעמי מצות לא נתגלו כעת, וזהו יציץ ופרח ישראל שפריחתם וצמיחת המצות שיהי' אח\"כ התגלות אא\"ס ושייך לבחי' ישראל וכמ\"ש יוצרך ישראל צורה וכנ\"ל.\n<b>ולכן</b> סיים אח\"כ ומלאה פני תבל תנובה, תבל הוא כמארז\"ל ד' שמות נק' לארץ אדמה ארקא ארץ תבל, [ארץ הוא] בתקופת ניסן שמריצה פירותיה ותבל הוא בתקופת תמוז שמתבלת פירותיה שאז נגמרו הפירות בבישולם היטב ומתובלים בטעמם כו' וכמ\"ש ואהי' אצלו אמן ואהי' שעשועים משחקת בתבל ארצו שעיקרו התענוג והטעם, וגם ע\"ש תבלין וע\"ד מארז\"ל תבלין א' יש לנו ושבת שמה ולכן סמך לכאן שמדבר מענין הצמיחה יציץ ופרח כו' ומלאו פני תבל והו\"ע גילוי התענוג עליון שיהי' אח\"כ לע\"ל וכמ\"ש משחקת בתבל ארצו ואהי' שעשועים כו' שעיקר השחוק והתענוג עליון יהי' לע\"ל וכמ\"ש אז ימלא שחוק פינו והוא מה שיתגלו פנימי' וטעמי המצות לע\"ל, תנובה, ובפי' תנובה יש ב' פירושים הא' מלשון חיל כי ינוב, ניב שפתיים שהוא לשון גילוי והו\"ע גילוי וצמיחת אורות עליונים שיהי' לע\"ל, והנה בזה יש ג\"כ ב' בחי' פירות ועלין וכמ\"ש ועליהו לא יבול והעלין נקראים בשם שערות וכמ\"ש פונה שער זה לכאן ושער זה לכאן, או כמ\"ש שער של אפונין שער עדשים שהוא עלין של קטניות, ועד\"מ השערות למטה שהם נקראים רק בשם מותרי מוחין כמו\"כ הו\"ע המצות דעכשיו שמלובשים בגשמיות ממש אלו כשירות בבהמה אלו טריפות שנק' בשם שערות בלבד לגבי עצם הפירות וכמארז\"ל נובלות חכ' שלמעלה תורה, רק נובלות בלבד, אך לפי שהשערות הם שלמעלה הרי הם ג\"כ בחי' גבוה כי הלכות התורה נק' בשם שערות וכמ\"ש קווצותיו תלתלים"],[4101400144,"תלי תלים של הלכות, אך כ' סלסלה ותרוממך שצריך להפריד השערות זמ\"ז בכדי שלא יהי' בה תערובות והו\"ע בירורי הלכות כמו ורמינהו לא קשי' כמו שמפרידים היטיב שלא יהי' בהם שום תערובות, והו\"ע העלין שנק' בשם שערות ויש צמיחת הפירות בטעמם והוא מה שיתגלה לע\"ל, ופי' הב' מלשון תנו בה, והו\"ע מה שכל גילוי הפנימי' אא\"ס ותענוג עליון שיהי' לע\"ל הכל צריך להמשיך וליתן מתחלה והוא שע\"י מעשה המצות דעכשיו דווקא בגשמיות ממש בארץ חפץ וכנ\"ל עי\"ז אח\"כ יהי' צמיחת הפירות לע\"ל, וזהו מ\"ש ואהי' אצלו אמון כו' ושעשועי את בני אדם, שעיקר השחוק ותענוג עליון הוא דוקא ע\"י נש\"י ראשית תבואתה שהם ממשיכים גילוי אלקות דירה בתחתונים וכנ\"ל וד\"ל.\n<b></b><b>בס\"ד נאמרה יום א' ך\"ד טבת יא\"צ דשנת תזר\"ח לפ\"ק פה ליובאוויטש\nביאור לד\"ה הבאים ישרש יעקב דפ' שמות</b>"],[4101400145,"<h3>להבין ענין התומ\"צ שמבואר בלק\"א פכ\"ג</h3>\nביאור לד\"ה הבאים ישרש יעקב דפ' שמות\nלהבין ענין התומ\"צ שמבואר בלק\"א בגודל מעלת המצות שנק' רמ\"ח פיקודין רמ\"ח איברי' דמלכא. כי טפ\"ט הוא פ\"א וכ\"א יש בו רת\"ס"],[4101400146,"הרי רמ\"ג וה\"ח הרי מספר רמ\"ח, ובמדריגת התורה אמר דאורייתא וקוב\"ה כולא חד, ולהבין ענין ההפרש שלהם, וגם י\"ל מה שנק' המצות בשם איברי' דמלכא, [חסד דרועא ימינא כו' וטפ\"ט כו'], תינח בשורש המצות שגבוה מעלתם עד שהם בבחי' רצה\"ע אבל מצות הגשמי' שלמטה איך יתכן לקראם בשם איברי' דמלכא, והנה המצות נק' בשם רצה\"ע וכתיב כל אשר חפץ ה' עשה כו' (ומהו החילוק שביניהם). ומתחלה י\"ל ענין הרצון למטה באדם שאנו רואי' שהרצון מלובש בכל הרמ\"ח איברים שבאדם ביד ורגל וכדומה שמחי' אותם ונמצא מהותו ג\"כ בהאברים, ולפיכך נשמעים כל האיברים תיכף להרצון שמיד שיעלה ברצונו לנוע א' מהאיברי' מיד יניע אותו כרצונו, וכן אם ירצה להלוך תומ\"י ילך, ואם הי' הרצון שורה רק במוח הי' צריך שיהוי זמן מה עד שיבא מהמוח להאבר פרטי ההוא, א\"כ מוכרח לומר שעם שעיקר השראת כח הרצון הוא במוח עכ\"ז מלובש ממש בכל האיברים בגילוי, ולכן ג\"כ אנו רואים שהרצון מושל עליהם אפי' בדבר היפוך הטבע, כמו שלא להיות לו רצון לדבר ההוא וכן להעמיד את הרגל במים חמין או קרים שהטבע יכריח להיפוך אבל הרצון יעמיד כרצונו, והוא רק מפני שמלובש ונמצא מהותו בכל האברים ממש ולפיכך ימשול עליהםוינהיגם כרצונו, והנה נמצאים ג\"כ אברים שהרצון לא יפעול בהם כלל והם האברי' פנימי' הקרביים והאצטומכא וכו' שגם אם ירצה להניע אותם לא יתנוענעו כלל, וגם בכל ה' כחות כמו כח הדוחה שלא יוכל ברצון שבו לעצור אותו או כח המרעיב שאם ירצה לאכול אין הרצון שליט לכלוא שלא ירצה לאכול, וכן כולם, והטעם הוא לפי שאין הרצון מלובש בהם בהלבשה ממש כדמיון כל האברים ולכן לא יוכל לפעול בהם כלל, אעפ\"י שמחי' אותם ג\"כ שכל עיקר החיות נמשך מהרצון ומחי' כולם בפרט מ\"מ אינם דומי' זל\"ז שבכל האיברי' מחי' בדרך הלבשה וגילוי לכן נשמעים לו בביטול גמור, אבל האיברים פנימי' הוא רק שמחי' אותם אבל הוא בהעלם ולא נמצא בהם בגילוי ולכן לא ימשול בהם, והן אמת שאנו רואים שבהיות האדם טרוד מאד אז לא ירגיש בכח הדוחה שלו ויעצר, וכן ג\"כ בכח המרעיב שלא ירצה לאכול כל היום כולו בהיותו טרוד באיזה דבר שכל, אך הוא לא מצד גילוי כח הרצון בהם כדמיון שאר האיברים שלכן יתבטלו הכחות אלו לפניו רק שהוא ביטול והתכללות הכחות האלו שנכללים בכח השכל כנר בפני האבוקה, שכל כח קטן מתבטל לפני גדול ממנו, אבל לא שהרצון נמצא בהם בגילוי וכנ\"ל.\n<b>והנה</b> עפי\"ז יובן ענין מה שהמצות נק' בשם איברי' דמלכא והוא לפי שהם כלים לגילוי רצון העליון ב\"ה בהם וכדוגמת משל האיברים גשמיים שהרצון מלובש בהם בהלבשה ממש כמו\"כ למעלה במצות שורה אא\"ס בהלבשה ובגילוי ממש, הגם דכתיב כל אשר חפץ ה' עשה בשו\"א שמהווה ומחיי' את כל העולמות עליונים ותחתונים כי התהוות כל הדברי' גשמיי' הוא"],[4101400147,"מבחי' סוכ\"ע, אך הוא כדוגמת האברים פנימי' הקרביים כו' שגם שמקבלים חיות מהרצון אעפ\"כ אינו מלובש בתוכם כמו\"כ ענין מה שמהווה ומחי' את כולם וכמ\"ש ואתה מחי' הוא שמחי' אותם והחיות אלקות הוא בהעלם שמחי' אפי' דברים טמאים שהוא היפוך הרצה\"ע וזה כל עיקר ענין קליפת נוגה שנמשך ממנה חיות לכל דברים גשמיים, ובכלל יש ב' מרכבות מרכבה דקדושה שהוא ביטול הנברא לאלקות כדוגמת ביטול האיברי' להרצון, ויש מרכבה דקליפה את הגמל ואת הארנבת והשפן והחזיר שמשפיעים חיות גשמי' כדמיון חיות האצטומכא כו' אעפ\"י שלא נמצא בהם גילוי הרצון, משא\"כ המצות כמו ציצית ותפילין שהארת הסוכ\"ע הוא בהם בגילוי בתפילין בחי' ח\"ע ול\"ב חוטין לבנ\"ח כו' ולכן נק' בשם איברים כמשל הרצון באיברי' וכנ\"ל.\n<b>והנה</b> יש בזה ג' בחי' המצוה עצמה וכח המעשה שבאדם העושה המצוה והאדם גופא, המצוה נק' בשם אברים דמלכא, כח המעשה נק' בשם לבוש והוא למטה מהמצוה עצמה, אעפ\"כ עולה ונכלל כח המעשה עם המצוה עצמה, והאדם עצמו נק' בשם מרכבה לקדושה, ולכאורה הוא במדריגת שלמטה מהמצוה שנק' בשם אבר והאדם הוא רק מרכבה וכדמיון ביטול המרכבה לגבי הרוכב כו', ובאמת שיש מעלה באדם יותר מהמצוה וכמ\"ש בתו' הנ\"ל שהמצות נק' בשם זריעה וכמשל מהגרעין שכלול בו כל התהוות הפירי שיצמח ממנו אח\"כ מ\"מ עיקר הצמיחה הוא ע\"י הארץ שמביא מההעלם לידי גילוי, כמו\"כ הענין במצות ואדם שנש\"י נק' בשם ארץ וכמ\"ש ואתם תהיו לי ארץ חפץ שעיקר המשכת גילוי רצה\"ע וסוכ\"ע ע\"י המצוה הוא דוקא ע\"י האדם שעושה המצוה שהרי אם התפילין יניחו על השולחן אין זה מצוה רק דווקא כשישראל הוא העושה המצוה אז יהי' סיבת המשכת אורות עליונים, וא\"כ יש מעלה באדם שגבוה יותר מהמצוה ובלעדו לא יהי' המצוה כלל, ומ\"ש שהאדם הוא רק מרכבה להקדושה הנה באמת יש מעלה בהמרכבה שגבוה יותר מהרוכב וע\"ד מ\"ש והחיות נושאו' את הכסא שנושאות ומגביהות גם את הבחי' כמראה אדם היושב על הכסא למעלה לפי ששורשם גבוה יותר במדריגה, וכמו\"כ ענין האבות הן המרכבה כו', ששורש נש\"י גבוה יותר משורש המצוה לכן דוקא בם וע\"י יהי' סיבת המשכת גילוי רצה\"ע וסוכ\"ע בעשיית המצוה.\n<b>ומעתה</b> י\"ל בענין מדריגת התו' שמבואר כי אורייתא וקוב\"ה כולא חד, ושורש ההפרש בין תו' למצות שנק' איברי' דמלכא, והענין יובן בהקדים מאמר הזוהר איהו וחיוהי חד בהון איהו וגרמוהי חד, וצ\"ל מהו החילוק שבין איהו וחיוהי לאיהו וגרמוהי, מאחר שכולא חד, והנה בפי' איהו וחיוהי וגרמוהי יש ב' פירושים, הא' כי גרמוהי נקראים הכלים וחיוהי הוא האורות, ופי' הכלים הו\"ע הספירות עליונות חסד וגבורה כנ\"ל, כי הנה ענין המדות לא יתכן זה באוא\"ס שהוא עצמות פשוט ולא יתכן לקוראו בשם חסד או גבורה כו' שהוא בחי' דבר מה, וגם הרי נמצא בהמדות ב' הפכים חסד והיפוכו הוא"],[4101400148,"הגבורה ולא יתכן זה באוא\"ס שהוא אחד האמת אחדות פשוטה כו', רק בחי' המדות עליונות נק' בשם בחי' כלים, חסד נק' כלי החסד וכן גבורה וכדומה, לגבי עצמות אא\"ס, אבל אא\"ס הוא לאו מכל אילין מדות איהו כלל ולא שייך זה לפניו וכו', ומ\"מ כשהאור א\"ס נמשך בהכלים הם הספי' עליונות אז מתאחד עמהם והיו לאחדים האור עם הכלי ונק' חסיד שמתחסד וכדומה, וזהו שאמר איהו וגרמוהי חד, איהו הוא בחי' אא\"ס שנמשך בהכלים וגרמוהי הם חיצוניות הכלים וכולא חד שמתאחדים ביחוד גמור, ולהבין איך הוא שייך ענין התאחדותם יחד מאחר שהם דברים הפכים כו', הענין יובן ע\"פ מה שקרא בזוהר את עצם הספירות בשם גופא וכמ\"ש גופין תקינת לון, וע\"ד ענין גוף ונפש שהנה הרי הם ב' הפכים אמיתים שהנפש היא בחי' רוחניות והגוף הוא גשמי' וה\"ז ב' הפכים ועכ\"ז בהתאחדותם יחד הנפש תוך הגוף ה\"ז נעשה אחדות גמור שהנפש מרגשת במקרי הגוף בכאב וכו' ומתפעלת מהם כו', ועפ\"ז נבין בערך יחוד אא\"ס בתוך הכלים שהם ב' הפכים סותרים שמ\"מ בהשראת אא\"ס בהם אז מתאחדים ביחוד גמור וז\"ש איהו וגרמוהי חד שכולא חד באין הפרש ועד\"מ מגוף ונפש וכנ\"ל, ופי' איהו וחיוהי חד הו\"ע יחוד האא\"ס שבתוך הכלים עם עצמות אא\"ס עצמותו ומהותו ויחוד זה הוא יחוד עצום ונפלא וגבוה ממעלת יחוד אא\"ס עם הכלים איהו וגרמוהי כו', ולהבין בחי' יחוד זה איהו וחיוהי ה\"ז דוגמת ביטול זיו השמש בשמש עצמו שלא הי' שום דבר נפרד מעולם כי האור מעין המאור ולא כדוגמת גוף ונפש שהם מתחלה נפרדים רק שאח\"כ מתאחדים משא\"כ הזיו עם עצם המאור הרי הם באחדות מתחלת עצם בריאותן, והזיו בטל בשמש בביטול במציאות, כמו\"כ הו\"ע ביטול ויחוד אא\"ס מה ששייך לגדר המשכת אור בתוך כלי לגבי עצמות אא\"ס שהוא יחוד והתכללות עצום ונפלא וז\"ש איהו וחיוהי חד, והיחוד הזה הוא לא כעין היחוד של איהו וגרמוהי וכנ\"ל, והפירוש הב' במאמר איהו וחיוהי וגרמוהי הוא מ\"ש בע\"ח שגרמוהי הו\"ע יחוד אא\"ס במדות, ואיהו וחיוהי הוא יחוד אא\"ס שבחכמה כנ\"ל, וג\"כ בחי'\nאיהו וחיוהי חד הוא גבוה מעלתו מבחי' איהו וגרמוהי יחוד אא\"ס במדות.\n<b>ויובן</b> הדברי' ע\"פ מה שאנו רואים בענין המדות שאינם שייכים רק לזולתו אבל לא לעצמו שאינו שייך לומר שיתחסד ויעשה חסד לעצמו, וכן במדות הרחמים שאינו שייך לומר שירחם על עצמו אלא הכל הוא לזולתו, אבל במהות ענין החכמה אנו רואים ששייך גם לעצמו שהוא עסוק וטרוד במושכלות ודברי חכמה כו', וכן הענין והחילוק למעלה כי בחי' המדות עליונות הוא שאינו שייך רק להתהוות ולהחיות העולמות וכמ\"ש זכור רחמיך וחסדיך כי מעולם המה, וכן כי אמרתי עולם חסד יבנה שאינו שייך כלל לגבי עצמות אא\"ס כו' רק לצורך קיום העולמות, משא\"כ בבחי' חכ' ששייך ג\"כ לגבי עצמותו וכמ\"ש אנת הוא חכים ולא בחכ' ידיעא הרי שאנו קוראים אותו בשם חכים ולא ידיעא בהעולמות שאינו שייך כלל כו', וזה\"ע איהו וחיוהי כי והחכ' תחי' כו' לעשות אחד שכולא חד, אבל יחוד זה גבוה מיחוד אא\"ס עם המדות"],[4101400149,"עליונות, ועיקר ההפרש שביניהם הוא לפי שחכמה הוא בחי' כח מה והו\"ע השגת הביטול איך שכולא קמי' כל\"ח ואני הוי' לא שניתי ולכן אין אא\"ס שורה אלא בחכמה משא\"כ המדות שהם בבחי' איזה מהות דבר מה, ולכן נק' התורה אמת ומבואר במדרש בתיבת אמת שמורה על בחי' אני ראשון ואני אחרון ומבלעדי אין אלקים א' בתחלתו מ' באמצעיתו תי\"ו בסופו כי אורייתא מח\"נ ובחכ' הו\"ע הביטול לאלקות איך שקמי' כו'.\n<b>ועפ\"ז</b> יובן שורש הפרש מעלת התו' למצות כי רמ\"ח פיקודין הם רמ\"ח איברי' דמלכא כמבואר לעיל כמשל השראת והלבשת הרצון בכל האיברים, כמו\"כ הו\"ע המצות שממשיכים אא\"ס בכלים להיות שם רצה\"ע ובחי' סוכ\"ע בגילוי, ע\"י בחי' גמ\"ח ממשיכים אא\"ס במדת החסד, וע\"י בחי' איזהו גבור הכובש את יצרו ממשיכים אא\"ס במדת הגבורה להיות שם אא\"ס בגילוי, אך עכ\"ז ה\"ז דוגמת ענין המדות כי טפ\"ט הם פ\"א ורת\"ס הם רמ\"ג וה\"ח רמ\"ח ה\"ז יחוד אא\"ס במדות או כמשל הנ\"ל מענין גוף ונפש איהו וגרמוהי שמתאחדים כאחד, אבל במעלת התו' אורייתא מחע\"נ אורייתא וקוב\"ה כולא חד ה\"ז יחוד אחר לגמרי וגבוה יותר, וכן יובן ג\"כ הענין למטה, שבהיות האדם לומד פסוק ממקרא או משנה כו' הרי מתאחד שכלו עם בחי' חכמת התורה ואורייתא וקוב\"ה כולא חד ה\"ז יחוד והתכללות ממש (וכמבואר בתניא).\n<b>ועפ\"ז</b> יובן ג\"כ איך שייך לקרוא למצות גשמי' שלנו בשם איברי' דמלכא, עד\"מ האיברים שנמשך בהם הרצון וכנ\"ל כך ע\"י המצות הוא המשכת אא\"ס בכלים ומדות עליונות להיותם כלים לגילוי רצה\"ע ממש ולא כבחי' כל אשר חפץ ה' עשה וכנ\"ל, וזשארז\"ל במצוה שאפשר לעשותה ע\"י אחרים שאין מבטלין מת\"ת כי שורש התו' גבוה יותר, אם לא במצוה שא\"א לעשותה ע\"י אחרים שאז מבטלין מת\"ת כי עיקר הכוונה הוא בהמשכת גילוי אא\"ס למטה נתאווה הקב\"ה להיות לו דירה בתחתונים, וכל האומר אין לי אלא תורה אפי' תורה אין לו אלא תו' וגמ\"ח וכנ\"ל.\n<b>ועתה</b> י\"ל בענין הק\"ש שארז\"ל אליו ולא למדותיו, ואעפ\"כ יש בה רמ\"ח תיבין כנגד בחי' רמ\"ח אברים דמלכא, והענין הוא כי באמת ענין הק\"ש הוא גבוה אפי' ממעלת יחוד התורה והוא בחי' איהו בעצמותו למסו\"נ באחד אחדות פשוטה שלמעלה מעלה אפי' ממדריגת החכמה כי כדי שיתהווה אפי' בחי' חכמה עילאה הי' מוכרח להיות בתחלה בחי' צמצום עצום ואח\"כ מהרשימו נמשך המשכת בחי' חכ\"ע, אבל אא\"ס פשוט בתכלית כו' וזה\"ע למסו\"נ באחד האמת ליכלל ולבטל אליו ית', ואח\"כ יוכל להיות ב' מיני יחוד הנ\"ל יחוד אוא\"ס בחכ' ויחוד אא\"ס במדות והו\"ע פרשה ראשונה דק\"ש שמבואר שם יחוד אא\"ס בתו' ושננתם וקשרתם כו' ובפרשה שני' מבואר שם ענין המצות והי' אם שמוע תשמעו את מצותי כו' ובתחלה צ\"ל יחוד אא\"ס בחכ' התו' ואח\"כ יחוד המצות וכמ\"ש כי נר מצוה ותו\"א כו'."],[4101400150,"<b>והנה</b> המצות נק' בשם איברים וכנ\"ל ובאבר יש ג' בחי' בשר וגידין ועצמות, ורוב בנינו של אדם הוא העצמות שהם עצם האדם והגידים הם המקשרים ומחברים את הבשר להעצמות, וככה ג\"כ נמצאים במצות ג' בחי' מחשבה דבור ומעשה, והוא ג\"כ כוונת המצוה בחי' מחשבה, וברכת המצות בחי' דבור, ועצם המעשה של המצוה, והו\"ע ג' מיני אותיות אותיו' המח' ואותיו' הדבור כו', והעיקר הו\"ע כוונת המצות נק' בשם עצם, והמעשה עצמה נק' בשם בשר ולבוש וכנ\"ל שכח המעשה נק' רק בשם לבוש, ואמנם יש מעלה בעצם מעשה המצוה שגבוה ג\"כ אפי' ממדריגת התו' והוא לפי שעיקר המכוון הוא במעשה המצות המשכת אא\"ס למטה דירה בתחתונים, וזה\"ע המחלוקת שבגמ' אם תלמוד גדול או מעשה גדול ונמנו וגמרו שגדול תלמוד שמביא לידי מעשה, ויובן מזה שתלמוד גדול רק מפני שמביא לידי מעשה שהוא עיקר הכוונה, ומעלת התו' שגבוה מהמצות הוא לפי שהוא המשכת בחי' ח\"ע שגבוה מהמשכה שע\"י המצות בחי' המדות אבל בשורשם יש מעלה ברמ\"ח פיקודין רמ\"ח איברי' שהוא עיקר המשכת גילוי אלקות למטה, וזה\"ע ועשיתם אתם את\"ם כתי' מעלה אני עליכם כאלו עשאוני, ולכאורה צ\"ל מ\"ש מעלה עליהם כאלו עשאוני הלא הם העושים גופא ומהו מעלה אני עליהם כו', אך באמת פי' ומעלה עליהם כאלו עשאוני שע\"י מעשה המצות שישראל עושים את הכלים עי\"ז מעלה עליהם כאלו עשאו להמשכת האור אא\"ס בהם שע\"י כלי המצות שעושים להשראת האור ה\"ז דומה כאלו עושים לעצם אוא\"ס כביכול כו'.\n<b>וזה\"ע</b> מה שנקראים המצות בשם איברים דוקא ולא בשם כלים שהרי הם כלים להמשכת אוא\"ס כו' כנ\"ל, והענין הוא שהחילוק בין איברים לשאר כלים ע\"ד מ\"ש כי נר מצוה כמו שאנו רואים בנר שהוא כלי לשמן ופתילה שבתוכו שיאיר בהם האור כנ\"ל, אבל לא שהנר ימשיך את השמן בתוכו מעצמו רק שהוא כלי המחזיק ומגביל בתוכו את השמן כו', אבל האבר גורם להמשכת החיות בתוכו שכאשר האבר בקיומו אז יומשך בו החיות מהנפש ויפעול פעולתו ובלעדי האבר לא יומשך חיות הנפש, משא\"כ בשאר כלים שהם רק שמגבילים ומחזיקי' דבר הניתן בהם אבל לא הם הממשיכים בתוכם, וזהו שהמצות נקראים בשם איברים דוקא איברים דמלכא שהם הגורמים להמשכת גילוי אא\"ס למטה דוקא, כי נתאוה הקב\"ה להיות לו דירה בתחתונים וכו' וכנ\"ל, ואע\"פ שהם ג\"כ בחי' כלים המגבילים ולכן נק' ג\"כ רק בשם איברים איהו וגרמוהי וכנ\"ל אבל מצד זה יתרון המעלה בהם דוקא יותר משורש התו', ועוד שכדי להיות גילוי אוא\"ס ורצה\"ע הוא דוקא ע\"י בחי' מעשה המצות גשמיי' והו\"ע בחי' צמצומים והסתר ובהם וע\"י יוכל להיות המשכת רצה\"ע וגילוי אא\"ס, וזה\"ע ועשיתם אתם מעלה אני עליכם כאלו עשאוני וד\"ל."],[4101400151,"<h3>[נוסח אחר]</h3>\n<b>עי'</b> בתניא פ' ך\"ג מבואר שם שהמצות נק' רמ\"ח פיקודין רמ\"ח אברים דמלכא ואורייתא וקודב\"ה כולא חד י\"ל החילוק וההפרש שבין תורה למצות, וגם הנה מה שהמצות נק' רמ\"ח אברים דמלכא, הפי' הוא היינו המצות כמו שהן למעלה וגם כמו שהן למטה, ובשלמא המצות כמו שהן למעלה י\"ל שנק' רמ\"ח אברים, דהנה ידוע שיש ט\"ס וטפ\"ט הם פ\"א ורת\"ס הם רמ\"ג וה' חסדי' המגדילים הם רמ\"ח, אבל המצות כמו שהם למטה בגשמי' איך הם נקראים אברים דמלכא. אך הענין הוא דהנה אנו רואים למשל כמו שאברי גוף האדם הם לבוש לנפשו ובטלים לגמרי אלי' מכל וכל כי מיד שעולה ברצונו של אדם לפשוט ידו או רגלו הם נשמעות לרצונו תומ\"י בלי שום ציוי ואמירה להן ובלי שום שהי' כלל אלא כרגע ממש כשעלה ברצונו מיד נשמעות לרצונו, וע\"כ שמלובש בהם ג\"כ הרצון שאל\"כ הי' צריך שהוי זמן מה עד שיומשך מהרצון לרגל אלא ודאי שמלובש בהם הרצון, וע\"כ הם בטלים לרצון ואף אם יסכים ברצונו לכאוב לרגל כגון להעמיד אותה במים קרים וכדומה מ\"מ אינה יכולה למנוע להרצון לפי שהיא בטילה בתכלית להרצון וכל מה שעלה ברצונו לעשות באיזה אבר אינו יכול למנוע כו', אך הנה יש אברים באדם שאינם בטלים כלל להרצון כמו קרבים ואצטומכא שאין לו שליטה להרצון על אברים אלו כמו למשל כח הדוחה או כח המרעיב שאף שאם יעלה ברצונו שלא ירעיב אותו או שלא ידחה הפסולת לחוץ מ\"מ הכח המרעיב עושה פעולתו ואינו בטל כלל לרצונו שרוצה שלא ירעוב כו' ואף שמקבלים ג\"כ חיות מהנפש מ\"מ אינם בטלים לרצונו, והיינו לפי שהחיות אינו מלובש בהם כ\"א בבחי' מקיף לכך יכול להיות שאף שמקבלים חיות מ\"מ לא יהי' בטלים, אך מ\"מ אנו רואים שאם הוא טרוד מאד בשכל עמוק או כשהוא טרוד באיזה ענין שנוגע לעצמות נפשו אזי יכול להיות שיבוטל כח המרעיב ג\"כ שאינו מרגיש כלל שרוצה לאכול, אך זה אינו מצד שהוא בטל רק מצד שכשמאיר אור הנפש בגילוי אזי הוא ממילא בטל ונכלל באור הנפש כביטול הנר בפני אבוקה, אך זה אינו מצד שהוא בבחי' ביטול להרצון, ואם אינו מאיר אור הנפש בתוס' גילוי אזי אינו בטל כלל לרצונו כו', וכך יובן למעלה באור וחיות אלקי' שמחי' את העולמות וכמ\"ש ואתה מחי' את כולם, הנה אעפי\"כ יכול להיות שיהי' בחי' נפרד לעצמו ולא יהי' בטל לאלקות כמו למשל ק\"נ או שלש קליפות הטמאות לגמרי וכמ\"ש את הגמל ואת השפן ואת הארנבת ואת החזיר שהם מרכבה טמאה והם מקבלים חיות מאלקות, ואעפ\"כ הם עושין את ההיפוך ואינם בטלים כו', וכמו למשל באדם ג\"כ שאם ח\"ו עובר עבירה אזי עושה היפוך הרצון מאלקות ואעפי\"כ הוא מקבל חיות מאלקו' בשעת מעשה ג\"כ שאם לא הי' מקבל חיות מאלקות מאין הי' לו חיות, ואעפ\"כ הוא אינו בטל כלל שאם הי' בטל אזי לא הי' עושה העבירה כנ\"ל, והיינו לפי שהם מקבלים חיות מאלקות רק מבחי' סוכ\"ע שמאיר עליהם רק בבחי' מקיף לבד, אבל אינו מתלבש בהם החיות בהתלבשות גמור"],[4101400152,"וע\"כ אעפ\"י שהוא מחי' אותם מ\"מ אינם בטלים לרצונו כלל ויכול לעשות ההיפך מרצונו ממש כו', משא\"כ המצות נק' רמ\"ח אברים דמלכא, והיינו שכמו שהאבר בטל לרצונו ממש כך המצות הם רצה\"ע כו' והיינו לפי שמלובש בהם הרצה\"ע בהתלבשות גמור בבחי' גילוי וע\"כ הם בטלים לרצה\"ע כו'.\n<b>והנה</b> מבואר עוד בתניא שהלבוש החיצון של נה\"א שבאדם המקיים ועושה המצוה שהוא כח ובחי' המעשה שלה הוא מתלבש בחיות של מעשה המצוה ונעשה ג\"כ כגוף לנשמה לרצה\"ע ובטל אליו לגמרי, ואברי גוף האדם המקיימים המצוה שכח ובחי' המעשה של נה\"א מלובש בהם בשעת מעשה וקיום המצוה הם נעשים מרכבה ממש לרצה\"ע. והנה אעפ\"י שהם מרכבה לבד והעיקר הם המצות, מ\"מ יש מעלה בהם לפי שיש מעלה במרכבה מה שאין ברוכב וכמ\"ש והחיות נושאות את הכסא שמנשאין את הכסא למעלה מה שלא הי' ביכולת מצד עצמה רק ע\"י המרכבה של החיות כו', וכך אעפ\"י שהעיקר הם המצות מ\"מ זה גופא שהמצוה יהי' מצוה זהו ע\"י האדם דוקא שעושה המצוה, כמו למשל מצות תפילין שאם אינו מניח תפילין רק שהם מונחים על השולחן אזי אינו מצוה כלל רק שהם תשמישי קדושה אבל אינו מצוה וכשמניח אותם האדם אזי היא מצוה וע\"כ הוא למעלה מהמצוה כו' וכמ\"ש קדש ישראל לה' ראשית תבואתה שישראל נק' ראשית תבואתו, תבואה נק' מצות וכשארז\"ל מאי פרי מצוה ונש\"י נק' ראשית תבואתו לפי שהתבואה למשל אינו יכול להצמיח כ\"א ע\"י כח הצומח שבארץ, וע\"כ אף שהעיקר המכוון הוא הפרי מ\"מ בלתי כח הצומח שבארץ לא יוכל להיות הפרי כנ\"ל וע\"כ כח הצומח הוא ראשית לפרי, כמו\"כ המצות הם הפרי אך כדי שיצמיח הפרי הוא ע\"י כח הצומח שבארץ שהוא נש\"י שנק' ארץ וכמ\"ש כי תהיו אתם ארץ חפץ כו', נמצא שהם עושין למצוה שיהי' מצוה כנ\"ל וע\"כ הם העיקר, וזהו אעפ\"י שהם מרכבה לבד מ\"מ יש מעלה במרכבה, וכמו האבות שהיו מרכבה כנ\"ל והיו בתכלית הביטול לאלקות בבחי' ביטול במציאות ממש.\n<b>וזהו</b> ענין רמ\"ח פיקודין רמ\"ח אברי' דמלכא שבהם מלובש רצה\"ע ממש, והאדם העושה המצוה נעשה מרכבה לרצה\"ע דהיינו בבחי' מרכבתא עלאה בחי' ביטול במציאות ממש משא\"כ בכללות העולם אפי' עולמות דקדושה אעפ\"י שהם בטלים ג\"כ לאלקות מ\"מ הם רק בבחי' מרכבתא תתאה מרכבה של החיות הקודש שהיא רק בחי' ביטול היש לבד כו'.\n<b>ועתה</b> י\"ל מ\"ש שם דאורייתא וקוב\"ה כולא חד, והנה להבין זה י\"ל מקודם מ\"ש בזהר איהו וחיוהי חד איהו וגרמוהי חד בהון כו' ולכאו' אינו מובן למה מחלק זה לשנים איהו וחיוהי חד איהו וגרמוהי חד והל\"ל איהו וחיוהי וגרמוהי חד, וכיון שהוא מחלק לשנים עכצ\"ל אף שהוא חד מ\"מ אינו דומה היחוד שבין איהו וחיוהי לבין איהו וגרמוהי, וי\"ל ההפרש שביניהם, אך הענין הוא דהנה איהו וחיוהי קאי על האורות כי חיוהי היא לשון חיות דהיינו אור"],[4101400153,"וחיות של הכלים, וגרמוהי היא בחי' הכלים כי גרמי היא לשון עצמות כו' שהם כלים.\n<b>ולהבין</b> פי' וענין הכלים, הענין הוא דהנה ידוע שיש ע\"ס חסד גבורה כו', והנה חסד וגבורה הם שני הפכים ממש, והנה אא\"ס הוא בתכלית היחוד ממש שהוא אח\"פ וא\"כ איך שייך לומר באא\"ס חו\"ג כי לאו מכל אינון מדות איהו כלל. אך באמת באא\"ס עצמו אינו שייך כלל לומר חו\"ג רק מה שאנו אומרי' שיש ע\"ס חו\"ג כו' זהו רק בהכלים שהוא בחי' כלי החסד כלי הגבורה, אבל באור אין בו בחי' מדות כלל כי הוא אור פשוט כו', ומה שמבואר בכמה מקומות שכשיש המשכת גילוי אא\"ס במדות בבחי' תוס' וריבוי אזי נעשה אחליפו דוכתייהו אור החסד בכלי הגבורה ואור הגבורה בכלי החסד, וכמו ב' פרשיות דק\"ש שפרשה ראשונה היא אור החסד בכלי הגבורה ופרשה שני' היא אור הגבורה בכלי החסד דמשמע מזה שבאור ג\"כ יש בו התחלקות חו\"ג שנק' אור החסד כנ\"ל, היינו ג\"כ מצד הכלי שהאור נשתנה לפי גוון הכלי אבל בעצם האור אין בו התחלקות כלל רק כשנמשך האור בהכלי אזי נעשה לפי גוון הכלי כו' וכשנמשך המשכת גילוי אא\"ס בתוס' וריבוי אזי נכלל האור שבכלי בעצמות האור וע\"כ יכול להיות אחליפו דוכתייהו כו', והנה לזה אמר אף שמצד הכלים יש בחי' התחלקות חו\"ג אעפי\"כ איהו וגרמוהי חד בהון שנתייחד בהם ביחוד גמור כמו למשל שאנו רואים בנפש האדם שנתייחד באברי הגוף ביחוד גמור שאין לחלק ולומר שהם שני דברים גוף לבד ונפש לבד רק שהם נעשים דבר אחד ממש כנ\"ל, וכך למעלה איהו וחיוהי וגרמוהי חד שנתייחד בהם ביחוד גמור ואמיתי כנ\"ל.\n<b>והנה</b> איהו וחיוהי חד הוא יחוד למעלה מבחי' איהו וגרמוהי לפי שבחי' איהו וגרמוהי הם בעצם שני דברים רק שמתייחדים, כמו למשל נפש האדם בגוף שהם בעצם שני דברים רק שמתייחדים, אבל איהו וחיוהי חד היא יחוד בעצם, והיינו כמו למשל זיו השמש בשמש שהזיו הוא מעין המאור ממש והוא דבר אחד ממש רק שהוא זיו לבד אבל מ\"מ הזיו הוא מעין המאור כו' וזהו איהו וחיוהי חד.\n<b>והנה</b> ע\"י המצות שהם רמ\"ח פיקודין רמ\"ח אברים דמלכא עי\"ז נעשה איהו וגרמוהי חד שהוא בחי' יחוד הכלים כנ\"ל משא\"כ ע\"י התורה אורייתא וקודב\"ה כלא חד שהיא בחי' איהו וחיוהי חד, ובזה יובן מ\"ש ועשיתם אותם מעלה אני עליכם כאלו עשאוני, והיינו שע\"י המצות ממשיכי' אא\"ס בבחי' מדות, כמו למשל ע\"י מדת החסד דהיינו מצות צדקה וכדומה עי\"ז ממשיכים אא\"ס בבחי' מדת החסד וע\"י איזהו גבור הכובש את יצרו עי\"ז ממשיכים אא\"ס במדת הגבורה, וא\"כ אינו מובן למה נאמר כאלו עשאוני בכף הדמיון לבד, שבאמת ע\"י המצות עושין וממשיכי' אא\"ס במדות כו'. אך הענין הוא דזה שע\"י המצות ממשיכי' אא\"ס בבחי' מדות כנ\"ל זהו רק בחי' איהו וגרמוהי שנעשה"],[4101400154,"יחוד הכלים אבל מה שא' מעלה אני עליכם כאלו עשאוני היינו שמעלה אני עליכם כאלו עשאו יחוד האורות בחי' איהו וחיוהי חד כנ\"ל.\n<b>והנה</b> האריז\"ל פי' בע\"ח שאיהו וחיוהי הוא קאי על בחי' חכ' ע\"ש והחכ' תחי', ואיהו וגרמוהי חד קאי על בחי' מדות, והענין הוא דהנה יש הפרש גדול בין בחי' חכ' לבחי' מדות, דהנה מדות אינו שייך רק לזולתו אבל לעצמו אינו שייך כלל בחי' חסד או גבורה רק המדות הם לזולתו כשעושה חסד עם חבירו כגון גמ\"ח נק' חסדן, משא\"כ חכ' שייך גם לעצמו שמשכיל השכלות דבר חכ' כו', וכך למעלה בחי' מדות אינו שייך רק לעולמות וכמ\"ש כי אמרתי עולם חסד יבנה, משא\"כ עצמות אא\"ס קודם שנעשה מקור לעולמות אינו שייך לומר כלל בחי' חסד כי על מי יתחסד או ירחם כי על מי יהי' נקרא רחום וחנון כו', וזהו מ\"ש זכור רחמיך וחסדיך כי מעולם המה שבחי' רחמים וחסדים אינם רק לעולם כנ\"ל, אבל בחי' חכ' הוא למעלה מבחי' עולמות וכשארז\"ל על התורה שאלפיים שנה קדמה לעולם שנא' אאלפך חכ' אאלפך בינה, נמצא שבחי' חכ' היא למעלה מבחי' עולמות ושייך גם לעצמו כנ\"ל, וזהו ההפרש שבין איהו וחיוהי לבין איהו וגרמוהי חד, שאיהו וגרמוהי חד זהו רק היחוד שבמדות כנ\"ל שהם לזולת משא\"כ איהו וחיוהי חד שהוא היחוד שבחכ' שהיא בחי' עצמות ממש ואינו דומה היחוד שבין בחי' חכ' שהיא בחי' עצמות לבין היחוד שבמדות שאינם רק לעולמות, ואף שבתניא ח\"ב פ\"ח מבואר שמצד עצמותו שוה היחוד שבחכ' עם היחוד שבמדות מ\"מ צ\"ל שאעפי\"כ יש הפרש וחילוק לפי שחכ' שייך לעצמו כנ\"ל, ועוד י\"ל דלכך היחוד שבחכ' היא למעלה מבחי' היחוד שבמדות, דהנה חכ' הוא כח מה בחי' ביטול ואין אא\"ס שורה אלא דוקא בבחי' ביטול, וזהו שהתורה נק' אמת וכמ\"ש קרוב ה' לכל קוראיו אשר יקראוהו באמת ואין אמת אלא תורה ולכאו' אינו מובן איך נק' התורה אמת שהרי אא\"ס עצמו נק' אחד האמת כו', אך היינו לפי שבחכ' נתפס אחד האמת, דהנה אמת מורה על בחי' אני ראשון ואני אחרון ומבלעדי אין אלקים, כי אלף מורה על בחי' אני ראשון ות' על בחי' אני אחרון ומ\"ם על בחי' ומבלעדי אין אלקי', ובחכ' נתפס בחי' זו איך שקמי' כלא חשיבי ואין אלקי' זולתו כו' וע\"כ נק' חכ' ג\"כ אמת, וזהו איהו וחיוהי חד שהיא יחוד בעצם לפי ששם גילוי בחי' עצמותו כו' משא\"כ במדות נק' רק איהו וגרמוהי חד ואעפ\"י שמתייחדים בתכלית היחוד אעפי\"כ אינו דומה לבחי' היחוד שבחכ' כו'.\n<b>והנה</b> ק\"ש היא למסור נפשו באחד שהיא בחי' מס\"נ לעצמותו ומהותו ממש וכמ\"ש מי כה' אלקינו בכל קראינו אליו אליו ולא למידותיו, והיינו שאעפ\"י שע\"י תורה ומצות נעשה איהו וחיוהי חד כו' אעפי\"כ היא רק הארה מאא\"ס וכמו למשל זיו השמש מהשמש שהזיו אעפ\"י שהוא מעין המאור מ\"מ הוא רק הארה מעין המאור, אבל ק\"ש היא בחי' אליו לעצמותו ומהותו שהיא בחי' איהו, שע\"י התורה נעשה בחי' איהו וחיוהי חד, אבל ק\"ש הוא לבחי' איהו לבד, וזשארז\"ל למה קדמה פ' שמע לוהי' אם שמוע כדי שיקבל עומ\"ש תחלה"],[4101400155,"ואח\"כ יקבל עליו עול מצות, והיינו שמתחלה צריך לקבל עומ\"ש שהיא לבחי' איהו ואח\"כ עול מצות שהוא בחי' יחוד של איהו וגרמוהי, והנה פ' ראשונה אעפ\"י שהיא בחי' קבעומ\"ש שהיא לבחי' איהו מ\"מ הוא כולל ג\"כ את בחי' התורה וכמ\"ש והי' הדברים האלה ושננתם לבניך, והיינו לפי שהיא בחי' איהו וחיוהי חד כו', ומתחלה צריך שיקבל עליו עומ\"ש העלאה לבחי' עצמותו ואח\"כ ע\"י התורה נעשה יחוד בחי' איהו וחיוהי חד כו'.\n<b>והנה</b> אברים כלול מג' בחי' בשר גידים ועצמות. והנה להבין מהו ענין זה במצות, הענין הוא דהנה המצות כלולים ג\"כ מג' בחי' דהיינו מעשה המצוה עצמה וברכה של המצוה וכוונה של המצוה כי מצות צריכות כוונה כו', וזהו בשר גידים עצמות שהוא בכלל מחדומ\"ע, בשר הוא בחי' נה\"י בחי' מעשה, ועצמות היא בחי' חב\"ד מח' כו', כי מלובן שבאב שהוא בחי' חכ' נעשה עצמות, וגידים הם המחברים, זהו ברכה של המצוה, ואז כשהם כלולים מג' בחי' אזי נק' המצות בחי' אברים דמלכא, דהנה יש הפרש בין בחי' אברים לכלים, והחילוק וההפרש שבין אברים לכלים הענין הוא דהנה כלי הוא בחי' מקבל דהיינו שמקבל בתוכו יין וכדומה והנה אעפ\"י שהוא מקבל מ\"מ אינו גורם הכלי שיומשך בתוכו היין וכמו למשל נר שמקבל השמן הנה אינו גורם הכלי שיומשך השמן לתוכו, והנה אבר הוא ג\"כ בחי' מקבל שמקבל את אור הנפש, ועוד יש מעלה באבר דהיינו מלבד מה שהוא מקבל את אור הנפש אלא שג\"כ הוא ממשיך את חיות הנפש שאם לא הי' האברים לא הי' גילוי הנפש כלל אלא שאם יש אברים אזי נמשך חיות הנפש כו' אבל בלא אבר אינו מתגלה כלל, כמו למשל שאם נחסר איזה אבר כמו עין וכדומה אזי נחסר חיות הנפש של אותו אבר, נמצא שהאבר גורם שיומשך החיות כו', והנה כמ\"כ המצות לבד שהם כלים לגילוי המשכת אלקות אלא שהם גורמים שיומשך המשכת אלקות, וזהו מחלוקת בגמרא תלמוד גדול או מעשה גדול שיש סברא בגמרא לומר שמעשה גדול, והיינו שאעפ\"י שמצד היחוד תלמוד גדול לפי שמעשה המצות הם רק בחי' איהו וגרמוהי חד וע\"י התורה נעשה בחי' איהו וחיוהי חד, אך אעפי\"כ זה גופא שיומשך המשכת אא\"ס כו' זהו ג\"כ ע\"י מעשה המצות כנ\"ל וע\"כ מעשה גדול, וזהו שארז\"ל כל האומר אין לי אלא תורה אפי' תורה אין לו, והיינו לפי שהתורה בלא מצות אינו ממשיך כלום, אך מצד היחוד תלמוד גדול לפי שהוא בחי' איהו וחיוהי חד. וזהו מ\"ש בתניא שע\"י תלמוד נעשה בחי' אורייתא וקודב\"ה כלא חד, והיינו לפי שכשאדם לומד את התורה ומקשר דעתו ומחשבתו בעיון התורה ונעשה מחשבתו ושכלו מוקף משכל התורה, וגם שכלו מקיף שכל התורה עי\"ז נעשה התקשרות חזק ואמיץ ונעשה כלא חד וד\"ל."],[4101400156,"<h3>החדש הזה לכם</h3>\n<b>החדש</b> הזה לכם ראש חדשים ראשון הוא לכם לחדשי השנה, וי\"ל שהרי ר\"ח תשרי נק' ר\"ה שהוא כולל י\"ב חדשי השנה, ולכך נק' ר\"ה כמו שהראש הוא כולל כל כחות הנפש בדרך כלל ואח\"כ מהראש מקבלים כל האיברים כו' כמ\"כ ר\"ה הוא כולל כל חיות השנה ואח\"כ מר\"ה נתחלק לי\"ב חדשים בדרך פרט, וכל חדש הוא כולל ל' יום, ואח\"כ נתחלק לכל יום ויום, וא\"כ ר\"ח תשרי הוא ראשון, ולמה א' כאן ראשון הוא לכם לחדשי השנה.\n<b>אך</b> הענין הוא, דהנה איתא בבעל העקידה שבשני אופנים יכול להבין גדולת הבורא, אופן א' הוא מסידור של י\"ב מזלות שאין להם שום שינוי וכמ\"ש שלא ישנו את תפקידם, כמו שאנו רואים למשל שהשמש והכוכבים בכל יום הם סובבים והולכים ממזרח למערב, בלי שום שינוי, ועכצ\"ל שיש בזה כח מאא\"ס שמניע אותן, שאל\"כ הי' צריך שיהי' בזה שום שינוי, וכיון שזה קרוב לששה אלפים שנה ואין אנו רואים בהם שום שינוי ע\"כ שזה כח מאא\"ס כו'. נמצא שמזה אנו מבינים גדולת הבורא דהיינו מבחי' טבע יכולים אנו ג\"כ להשיג גדולת הבורא כו'. ואופן הב' יכולים להשיג גדולת הבורא משינוי הטבע, כמו למשל יצי\"מ וקי\"ס שהי' שינוי הטבע הפך ים ליבשה שמים נעשה יבשה כו', שאין זה ע\"פ הטבע כו', ומזה שנעשה שינוי הטבע מזה אנו מבינים גדולת הבורא יותר, שכמצביא עביד בחיל שמיא.\n<b>ובזה</b> יובן ענין ר\"ה ור\"ח ניסן, שמה שר\"ה נק' ראש שהוא כולל כל חיות השנה זהו רק בבחי' סדר מע\"ב שהחיות נמשך ונתחדש בר\"ה בדרך כלל, אך זה החיות הוא רק בבחי' הנהגת סדר מע\"ב בבחי' טבע, אבל כדי שיהי' גילוי חיות כללי כדי שיהי' שינוי טבע זהו ע\"י דוקא בר\"ח ניסן, שאז הגילוי מבחי' שלמעלה מסדר ההשתלשלות כדי שיהי' שינוי הטבע, לפי שבניסן הי' יצי\"מ וקי\"ס שא\"ז ע\"פ סדר ההשתלשלות כו' ולכן בבחי' זו נק' ר\"ח ניסן ראשון, שיהי' גילוי בחי' אא\"ס שלמעלה מסדר השתלשלות זהו בניסן דוקא, וע\"פ הקבלה הוא ג\"כ כי יש שני אופנים ביחוד חו\"ב ונק' בשם זיווג חיצוני וזיווג פנימי, והנה זיווג חיצוני הוא לצורך קיום העולמות כו' והיינו שזה ע\"פ דרכי הטבע כו' ובזה תשרי הוא ראשון, אבל יש בחי' יחוד פנימי שבחו\"ב והוא בחי' השפעה פנימי' והוא מה שלמעלה מדרכי הטבע, ובזה ניסן ראשון כו', ולכן כתי' החדש הזה לכם ראש חדשים, זה הוא בחי' גילוי פנימי'"],[4101400157,"כמ\"ש במ\"א, והיינו שבחי' השפעה פנימי' שמחו\"ב שהוא לצאת מדרכי הטבע ניסן הוא הראשון. והנה המשכת שני בחי' זיווג חיצוני וזיווג פנימי זהו ע\"י עבודת המלאכים ונשמות, כי המלאכים ע\"י עבודתם שעומדים ברום עולם ממשיכים בחי' זיווג חיצוני שהוא השרש שלהם, אבל הנשמות שעלו במח' ושרשם מפנימי' הכלים לכן ממשיכים בחי' זיווג פנימי של חו\"ב.\n<b>והנה</b> יש פלוגתא בגמ' ר\"א ור\"י, ר\"י אומר בניסן נגאלו ובניסן עתידין להגאל ור\"א [אומר] בניסן נגאלו ובתשרי עתידין ליגאל, ולהבין ענין פלוגתתן, דסברת ר\"י הוא כי מאחר בניסן הוא התגלות בחי' פנימי' שהיא למעלה מדרכי הטבע בחי' גאולה ובניסן נגאלו שהוא הראשון בזה א\"כ הגאולה שיהי' לע\"ל דהיינו גאולה שלימה יהי' ג\"כ בניסן שהוא הראשון, וסברת ר\"א, אמת כי ניסן הוא הראשון ובניסן הוא התחלת גילוי פנימי' שלכן נגאלו בניסן אך זהו על גאולת מצרים, אבל לע\"ל שיהי' גאולה שלימה יהי' בתשרי דוקא, כי בלמעלה מדרכי הטבע יש ג\"כ ההפרש בין ראשון לשביעי שהוא תשרי כמ\"ש בחדש השביעי וארז\"ל במד\"ר כל השביעין חביבין, והיינו שגם בלמעלה מן הטבע שניסן הוא הראשון תשרי גדול הימנו שבתשרי יהי' גאולה שלימה כי כל השביעין חביבין וכמו שבת לגבי ימי השבוע שבשבת מאיר מוחין דאבא כו' כידוע כי שבת הוא שביעאה וכל השביעין חביבין וכמ\"ש בזוהר ג\"כ שביעאה עלייהו, וראי' לזה שלמעלה מן הטבע ג\"כ חביב הוא מאברהם שהי' מלמעלה מן הטבע וכמשארז\"ל שאמר הקדב\"ה לאברהם צא מאיצטגנינין שלך שיצא מן הטבע ולמעלה מן הטבע, ואף שהי' אברהם מלמעלה מן הטבע אעפ\"כ הגאולה הי' ע\"י משה שהי' דור שביעי לאברהם, והוא מפני שכל השביעין חביבין. וזהו החדש הזה לכם, פי' חדש ל' התחדשות, בענין ההתחדשות כתי' נפלאות כמ\"ש שירו לה' שיר חדש כי נפלאות, הרי שייך ל' נפלאות אצל ל' חידוש, וזהו ג\"כ החדש הזה לכם כו' כנ\"ל וד\"ל.\n<b>אך</b> מה שיש לדקדק על פי' הבעל עקידה ממה שרבינו ז\"ל מפרש בד\"ה שוש אשיש בלק\"ת פ' נצבים ששנה גבוה הרבה מבחי' חדש, וגם אם נאמ' שחדש גבוה הלא אמרו ז\"ל במד\"ר כל השביעין חביבין וא\"כ תשרי הוא השביעי והוא חביב יותר ולכן בתשרי ר\"ה וא\"כ הוא ראש גם החדשים, אך באמת יש דיעה אחרת והוא דעת השל\"ה שאומר שחדש הוא במל' ולכן אמרה אסתר ואני לא נקראתי לבוא אל המלך זה שלשים יום לפי שאסתר היתה בחי' מל' ושלשים הם כנגד ל' יום שבחדש, ולכן בישראל דור כנגד ל' יום שבחדש כמ\"ש במד\"ר שמות פ' בא פט\"ו יע\"ש. ושנה או בינה או לכה\"פ ת\"ת, ונמצא כי שנה גבוה מחדש."],[4101400158,"<b>וביאור</b> הענין ממה שנת' בזוהר ע\"פ משכו וקחו לכם, משכו יומין תתאין [לגבי יומין עילאין], ופי' המק\"מ יומין עילאין יומין דזעיר אנפין יומין תתאין יומין דמל', פי' יומין עילאין הם ימות החמה שס\"ה ע\"ה כמנין משכו ויומין תתאין יומין דמל' שנה ימים הם ימי הלבנה כו', וצריך להמשיך יומין עילאין ימות החמה לימות הלבנה, וע\"י מה ממשיכים בחי' זו הוא ע\"י מצות ל\"ת כי שס\"ה ל\"ת הם כנגד שס\"ה ימים, ולכן ע\"י שס\"ה ל\"ת ממשיכים בחי' שס\"ה ימים, כי באמת עיקר המצות הם ל\"ת ששרשן מבינה ועכ\"פ מז\"א והם העיקר כמו למשל באיברי האדם הנה יש בו רמ\"ח איברים ושס\"ה גידים ואנו רואים שהעיקר הם בגידין שבהם ועל ידם מתפשט הדם והדם הוא הנפש כו', ולכן ע\"י ממשיכים בחי' שס\"ה יומין עילאין ולכן עושין בחדשי הלבנה לפעמים חדש י\"ג שמעברין את השנה כדי להשוות ליומין עילאין, והיינו לפי שממשיכים בחי' זו.\n<b>ועוד</b> יובן ענין שנה ממ\"ש בזוהר ע\"פ ויהי מקץ שנתיים ימים ואמרו בזוהר דתב דרגין לדרגין פי' דרגין חו\"ב לדרגין מל', כי שמי עם י\"ה שס\"ה זכרי עם ו\"ה רמ\"ח, פי' שמי הוא בחי' מל' כשמקבל מבחי' י\"ה ומתייחד בו נעשה שס\"ה והיינו בחי' שנת החמה כי שנה שהיא שנת החמה היא בבינה, והיינו בחי' שמי מל' שהוא שנת הלבנה שנ\"ה יומין עם י\"ה שהוא בחי' חו\"ב נעשה שס\"ה יומין, ונמצא מבואר שבחי' שנה גבוה מבחי' חדש, וכמ\"ש רבינו ז\"ל בד\"ה שוש אשיש ובהרבה דרושים.\n<b>אך</b> עדיין צ\"ל הקושיא הנ\"ל אם תשרי הוא ר\"ה איך ניסן ג\"כ ראש חדשים שהשנה כללות החדשים כנ\"ל, אך צ\"ל שהשל\"ה ס\"ל כדעת החוקר בעל נחמד ונעים שהביא בשם ר' אברהם אבן העזרא שאין לחמה חדשים ואין ללבנה שנה, וא\"כ ניחא מה שר\"ה הוא ראש היינו שנמשך כללות החיות על כל השנה אבל אין בחיות התחלקות מחדשים כי חיות זה הוא מבחי' חמה ואין לחמה חדשים כלל אבל כשנמשך החיות בבחי' לבנה אז נתחלק לבחי' חדשים, ולחדשים ניסן הוא הראשון אבל לכללות החיות של כל השנה תשרי הוא ר\"ה (ומה שעושין או\"ה ג\"כ י\"ב חדשים אף שמונין למספר ימוה\"ח היינו כי יש י\"ב מזלות לכן קבעו י\"ב [חדשים], ולכן אין החדשים שלהם שוה, חדש א' כ\"ח יום וחדש א' ל' יום וחדש א' ל\"א יום), ובאמת לשון חדשים בחמה ולשון שנה בלבנה הוא שם המושאל כו'.\n<b>ומעתה</b> צ\"ל ענין כל השביעין חביבין, צ\"ל מקודם בתוס' ביאור ענין הפלוגתא דר\"א ור\"י שר\"י סובר בניסן נגאלו ובניסן עתידין ליגאל, ור\"א סובר שבניסן נגאלו ובתשרי עתידין להגאל, והנה אף כי בכמה דברים אנו מחזיקי' דעת ר\"א עיקר דהיינו מה שר\"א סובר שבכ\"ה באלול נבה\"ע ואנו סוברים ג\"כ כן, אך בענין זה העיקר כדעת ר\"י שכן סתם המד\"ר בא פט\"ו שבניסן נגאלו ובניסן עתידין להגאל, בו ביום יצא יוסף מבית האסורים, ולהבין"],[4101400159,"ענין מחלוקתם י\"ל ע\"ד שאמר רבינו ז\"ל בת\"א בד\"ה רני ושמחי בת ציון שיש ג' בחי' בת אחותי אמי, והם כנגד ג' רגלים, בת כנגד פסח אחותי כנגד שבועות אמי כנגד סוכות.\n<b>ולהבין</b> מפני מה נק' פסח בשם בתי, כי הנה פסח הוא אתדל\"ע שלא באתדל\"ת כמ\"ש קול דודי הנה זה בא מדלג, שלא ע\"פ אתדל\"ת, ולכן סובר ר\"י שבניסן עתידין להגאל שכתי' גבי משיח עני ורוכב על החמור, פי' עני שלא באתדל\"ת, כי עשיר הוא באתדל\"ת אבל עני הוא בחי' אתדל\"ע בלא אתדל\"ת."],[4101400160,"<h3>\nראו כי ה'</h3>\n<b>ראו</b> כי ה' נתן לכם השבת, איתא במד\"ר אר\"י כל עיסקא דשבתא כפול עומרו כפול שני עומרים לגולגולת, קרבנו כפול וביום השבת שני כבשים כו', זכור ושמור בדיבור א' נאמרו, אף שירו כפול מזמר שיר כו'. ולהבין זה י\"ל מקודם מ\"ש החדש הזה לכם ראש חדשים, ואיתא במד\"ר ע\"ז שמהחדש הזה תזכו לכם, לכל בחי' לכם, והי' לכם לציצית, אני הוי' אלקיכם אשר הוצאתי אתכם מא\"מ להיות לכם לאלקי', ביום השמע\"צ תהי' לכם, אך אשר יעשה לכל נפש הוא לבדו יעשה לכם, שבת שבתון הוא לכם כו'. ולכאורה אינו מובן זה כלל. והענין הוא דהנה החדש הזה לכם ארז\"ל מלמד שנתקשה משה בקידוש החדש עד שהראהו הקדב\"ה ואמר כזה ראה וקדש. והנה להבין למה נתקשה משה בקידוש החדש כו'. הענין הוא דהנה איתא בגמרא וברבות שאלה מטרוניתא אחת לר\"י בששת ימים עשה ה' את השמים ואת הארץ כו' ואח\"כ מאי קאי עביד, אמר לה מזווג זיווגים, אמרה לו מאי האי רבותי' אף אני יכול לעשות כן, אמר לה אם קלה היא בעיניך קשה היא לפני הקדב\"ה כקריעת ים סוף, ולכאורה אינו מובן דבר זה כלל מה קשה כ\"כ לזווגם"],[4101400161,"וגם מה שאמר כקרי\"ס, מה קשה כ\"כ כקרי\"ס כי קרי\"ס הוא יש מיש, וכמ\"ש בתניא שיותר פלא הוא בריאת יש מאין, שהוא מאין ממש משא\"כ קרי\"ס הוא רק יש מיש שהמים נצבו כמו נד, אך מ\"מ הוא יש מיש כו', אך הבריאה הי' מאין ואפס המוחלט ממש, והנה על הבריאה כתי' לא בעמל ולא ביגיעה ברא את העולם כ\"א במאמר פיו כו', וקרי\"ס שהוא יש מיש הוא קשה לפני הקדב\"ה, אך הענין הוא דהנה הבריאה נק' יש מאין ולכאו' אינו מובן שהרי כתי' כי ממך הכל ואיך נק' הבריאה יש מאין כו'.\n<b>ולהבין</b> זה הנה כתי' כי עמך מקור חיים, ולכאורה למה [לא] כתי' כי אתה מקור חיים, אך הנה פי' עמך הוא בחי' מה שטפל ובטל אליו ית', והיינו שמקור חיים הוא טפל ובטל כו', והיינו לפי ששורש כל העולמות אפי' עוה\"ב ותח\"ה הוא רק מבחי' זיו והארה בעלמא שאינו נוגע אל עצמותו, וכמ\"ש כי בי\"ה הוי' צור עולמים ביו\"ד נברא עוה\"ב ובה' נברא עוה\"ז כו', ששורש כל העולמות הוא רק מבחי' שתי אותיות בלבד שאינם תופסי' מקום לגבי עצמות כו', וגם זה ביוד שהוא בחי' צמצום, כי כדי שיהי' מקור לעולמות בע\"ג הוצרך להיות צמצום באוא\"ס כדי שיהי' נעשה מקור לעולמות.\n<b>וענין</b> הצמצום זהו ע\"ד המשכה הנמשכת ע\"י שערות, כי הנה ההמשכה שנמשכת חיות הנפש מהמוחין שבראש ברמ\"ח איברים זהו בחי' השתלשלות ולכך מרגיש כאב גדול כשחותכין איזה אבר לפי שבו מלובש עצמות חיות הנפש, משא\"כ ההמשכה שנמשכת בשערות היא מצומצמת מאד שהרי אם אפי' מגלחין את השערות לא ירגיש כאב במוחין כלל, ואעפי\"כ מלובש בו קצת חיות שהרי אם מושכין את השערות אזי מרגיש כאב גדול, א\"ו שמלובש בו קצת חיות אלא שהוא המשכה מצומצמת מאד, וכך שם הוי' מורה על התהוות וכדי שיהי' בחי' התהוות מאוא\"ס שהוא בלתי בע\"ג כלל זהו רק ע\"י צמצום שנתצמצם עצמות האור, וההמשכה שנמשך להיות מקור לעולמות הוא המשכה מצומצמת מאד, וזהו מ\"ש והחכ' מאין תמצא, דהיינו שהתהוות בחי' החכ' הוא למעלה מן החכ' מאא\"ס ב\"ה שהוא רם ונשא זהו ע\"י אין כמו למשל החיות המלובש בהשערות וכמ\"ש בע\"ח אבא יונק ממזלא, וזהו מ\"ש אני הוי' הוא שמי, ששם הוי' הוא רק בחי' שם לבד כמו למשל שם האדם שאינו נוגע אל עצמותו כלל ואינו אלא לזולתו דוקא, וכך שם הוי' הוא רק בחי' זיו והארה בעלמא כו'.\n<b>והנה</b> תחלת בריאת העולמות הי' מפני כי חפץ חסד הוא, אך מה שבטובו מחדש בכ\"י מע\"ב מחדש מבחי' יש מאין מבחי' חכ' וצמצום בכ\"י כי בכ\"י מתחדשת הארה אחרת (וגם בכל שעה מתחדש צירוף שם הוי' כו') באתדל\"ת תליא מילתא, וצ\"ל בחי' צמצום והעלם זה ג\"כ באתדל\"ת, והוא להיות בחי' בטל רצונך כו', דהיינו לצמצם ולכבוש את כל רצונותיו אשר לא לה'"],[4101400162,"המה, הן במחשבה רבות מחשבות בלב איש ועצת ה' היא תקום, והן בדיבור שלא להיות דיבורו ורוח פיו כרצונו, והן במעשה עוצם עיניו מראות ברע, ולא תתורו אחרי לבבכם כו', ובין באיסור ובין בהיתר כמאמרז\"ל קדש עצמך במותר לך, והוא בכל שיעור קומה של אדם להשליך נפשו ורצונו מנגד כו', וביטול זה הוא בבחי' חכ' כי בחכ' אתברירו לברר הטוב מהרע ולבטל רצון הרע מפני הטוב בכח החכ' שבנפש, ולכן ארז\"ל קדש א\"ע כי קדש הוא בחכ' כמו קדש לי כל בכור כו', וע\"י ביטול זה שבאתדל\"ת שמבטל ומסלק א\"ע ורצונו ליבטל אליו ית', אתדל\"ע להיות ביטול וסילוק עצמות אא\"ס ב\"ה שלא יאיר ויתגלה אלא בבחי' צמצום בהעלם אחר העלם בבחי' ישת חשך ולא אור ויהי' גילוי בחי' יוד שהוא חכ' כו' ע\"י בחי' יו\"ד שבנפש.\n<b>וזהו</b> מ\"ש כי הוא ציוה ונבראו ממילא כו' לפי שהוא הארה בעלמא מלכותך מלכות כל עולמים, ששורש כל העולמות הוא רק מבחי' מל' שהוא בחי' מה שעלה במחשבה אנא אמלוך ואין מלך בלא עם מזה נעשה מקור לעולמות כו' וכמ\"ש בזוהר במחשבה אחת נברא העולם, וזהו מ\"ש כי עמך מקו\"ח ולא כתי' אתה, שאם הי' כתי' אתה הי' משמע שאתה עצמותו ומהותו הוא מק\"ח לכך כתי' כי עמך מק\"ח שמקור חיים הוא רק בחי' עמך מה שטפל ובטל כו', וזהו שהבריאה נק' יש מאין דהיינו שהוא רק מבחי' זיו והארה בעלמא, וזהו לא בעמל ולא ביגיעה ברא העולם כ\"א במאמר פיו דהיינו שברה\"ע נמשך רק מבחי' זיו והארה ולא מעצמותו כו' כי עמל משמע שהוא המשכה שנמשך מעצמות החיות.\n<b>ועתה</b> י\"ל ענין קרי\"ס שהי' הפך ים ליבשה, ומתחלה י\"ל ענין ים ויבשה, הנה ים ויבשה הוא בחי' עלמא דאתכסייא ועלמא דאתגלייא, ים הוא בחי' עלמא דאתכסייא ויבשה הוא עלמא דאתגלייא, והנה ההפרש שבין ים ליבשה בגשמי' הוא שהברואים שבים אינם נראים לחוץ כי הים מכסה עליהם, וגם חיותם וקיומם הם בתוך הים דוקא וא\"א להם לחיות ביבשה שכיון שהם פורשים מן הים מיד הם מתים, והיינו לפי שהם בטלים למקור התהוותם וחיותם בתכלית הביטול.\n<b>וזהו</b> ענין מח' ודיבור כי הדיבור של האדם הוא בבחי' גילוי לזולתו ונעשה נפרד כו' משא\"כ המח' מתאחד עם עצם הנפש, וכך למעלה עלמא דאתגלייא הוא מה שנעשו העולמות בבחי' יש ודבר נפרד והיינו לפי ששרשן מבחי' דיבור וכמ\"ש בדבר ה' שמים נעשו וע\"כ נעשו בבחי' נפרד, כמו שאנו רואים למטה שהדיבור נעשה נפרד מהאדם, הגם שלמעלה אינו שייך זה כי אין לך דבר שחוץ לעצמותו, מ\"מ דברה תורה כלשון בנ\"א, וע\"כ מה שנתהווה מבחי' דיבור עליון נראים ליש ודבר נפרד, אבל באמת אינן נפרדים כלל רק ע\"י שנתהווה מבחי' דיבור נראים לעינינו בבחי' יש ודבר נפרד כו', אבל עלמא"],[4101400163,"דאתכסייא זהו בחי' עלמין סתימין שנתהווה מבחי' מח' וע\"כ הם בטלים בתכלית הביטול כמו המח' שמתאחדת עם עצם הנפש וזהו שהמלאכי' נק' נוני ימא כו'.\n<b>וכך</b> למעלה עלמא דאתכסייא נק' בשם ים, דהנה המלאכים נק' נוני ימא, וכמ\"ש במד\"ר התנינים הגדולים, זה מיכאל וגבריאל, והענין הוא דהנה מצינו שהמלאך יכול לומר על עצמו שם ה' וכמ\"ש ותקרא שם ה' הדובר אליה, בי נשבעתי נאום ה', ולכאורה איך יכול לומר המלאך ע\"ע שם ה', אך הענין הוא לפי שהמלאך הוא ל' שליח, וכד איהי שליח מלעילא, אזי הוא בטל בתכלית הביטול לאלקו' עד שאינו תופס מקום כלל בבחי' ביטול במציאות ממש, לפי שמאיר בו הארת אוא\"ס וע\"כ יכול לומר בי נשבעתי נאם ה' לפי שהוא בטל לשם הוי' המאיר בו, וכאילו שם ה' דובר רק שהדיבור יוצא ע\"י, ולכך נק' המלאך בשם נוני ימא שכמו דגים שבים הם בטלים בתכלית להים ומובלעים בים ואף שהדגים הם בריאה מובדלת מהמים מ\"מ הם מתאחדי' עם המים כו', וכך המלאכים אף שהם נבראי' כו' מ\"מ הם בטלים בתכלית הביטול ממש לאלקו' עד שאינו מרגיש א\"ע כלל, ויכול לומר אני ה' כו'.\n<b>וזהו</b> מלאך בגי' הוי' א\"ד והיינו שהגוף שלו הוא מבחי' שם אד' והנשמה שבו הוא מבחי' שם הוי', וזהו בחי' שילוב הוי' בא\"ד, וע\"כ יכול לומר אני הוי' כו', ודוגמא לזה מצינו במשה שאמר ונתתי מטר ארצכם, והנה משנה תורה אמר משה כאילו הוא הי' המדבר לבד, כי משנה תורה חלוק משאר הספרים כי בתורה כתי' וידבר ה' אל משה שה' הוא המדבר משא\"כ במשנה תורה שמשה הוא המדבר וא\"כ איך אמר ונתתי מטר והול\"ל ונתן הוי', אלא לפי שהי' בתכלית הביטול לאלקו' עד שהי' השכינה מדברת מתוך גרונו של משה וע\"כ אמר ונתתי לפי שלא הי' הדיבור שלו כלל, והיינו לפי שמשה הי' מבחי' עלמא דאתכסייא וכמ\"ש כי מן המים משיתיהו, וע\"כ הי' בתכלית הביטול כו'.\n<b>וזהו</b> ענין עלמא דאתכסייא דהיינו שהנבראי' שבאותו עולם הם מכוסים ונבלעים שם בבחי' ביטול במציאות ממש כו', והנה הנשמות אף ששרשן למעלה מהמלאכים כי שורש נש\"י עלו במח' כו', הנה אעפי\"כ ירדו למטה בגוף ונה\"ב ונעשים בבחי' נפרד כו', וזהו ענין עלמא דאתגלייא דהיינו שהברואי' שביבשה אף ששורש התהוותם הוא מהיבשה וכמ\"ש הכל הי' מן העפר וגם אח\"כ עיקר חיותם הוא ג\"כ מן האדמה וכמ\"ש ארץ אשר ממנה [תוציא] לחם, מ\"מ אינם מתאחדים כ\"כ עם היבשה והם בבחי' נפרד מהיבשה, כי ברואים שביבשה יכולים לפרוש ג\"כ לים ע\"י ארבין, ואינם כמו דגים שאינם יכולים לחיות כלל בלא הים אפי' שעה אחת כו', משא\"כ ברואים שביבשה כו', והנה הארץ תוציא צמחה למעלה ונראי' בבחי' נפרד כו', וזהו ג\"כ למשל כמו"],[4101400164,"ענין הנשמות שאף ששרשן מבחי' מח' עילאה, מ\"מ נראים ליש בחי' נפרדים, ואינם כ\"כ בתכלית הביטול כמו המלאכים שהם בתכלית הביטול.\n<b>והנה</b> אעפי\"כ יש מעלה בעלמא דאתגלייא מה שאין בעלמא דאתכסייא, כי יתרון האור מן החשך דוקא, וזהו שהתורה ניתנה למטה דוקא כי המלאכי' בקשו את התורה וכמ\"ש תנה הודך על השמים ולא ניתנה להם, כי יתרון האור מתוך החשך דוקא, ע\"י בירור בחי' אתכפייא ואתהפכא מנה\"ב דוקא שהוא בבחי' פירוד עי\"ז נעשה יתרון אור, וזהו שנק' ארץ מלשון רצון, וכמשארז\"ל למה נק' שמה ארץ שרצתה לעשות רצון קונה, וגם מלשון רצוא אם רץ לבך שוב לאחד, שעי\"ז דוקא נעשה רצון ותשוקה לעצמותו ומהותו כו'. וזהו ארץ לא שבעה מים, מים הוא בחי' עלמא דאתכסייא, וארץ לא שבעה מים כי הרצוא הוא לעצמותו ומהותו כו', ואינו רוצה לא בגה\"ע ולא בגעה\"ת וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ, וזהו לא שבעה מים (דהיינו מהגילוי אא\"ס שמאיר בעלמא דאתכסייא כו'), וע\"כ הנשמות נק' מהלכים וכמ\"ש ונתתי לך מהלכים בין העומדים האלה, כי המלאכים נק' עומדים וכמ\"ש ויעמידם לעד לעולם, שאף שהם בתכלית הביטול מ\"מ הם עומדים תמיד במדריגה אחת, משא\"כ הנשמות נק' מהלכים שעולים תמיד במדריגה אחר מדריגה בעילוי אחר עילוי כו', וזה דוקא ע\"י בירור הגוף ונה\"ב כו', נמצא שיש מעלה בזה מה שאין בזה ויש מעלה בזה מה שאין בזה, מעלה בעלמא דאתכסייא לפי ששם בתכלית הביטול, ואינם בבחי' נפרד כלל, מה שאין זה בעלמא דאתגלייא, ומעלה בעלמא דאתגלייא שיתרון האור מתוך החשך דוקא.\n<b>והנה</b> ענין מדריגת הפך ים ליבשה, היינו שיהי' ב' המעלות שיהי' הגילוי שבעלמא דאתכסייא בעלמא דאתגלייא ממש כמו שהם בבחי' נפרדים ואעפי\"כ יהי' בהם הגילוי שבעלמא דאתכסייא ממש, וכמ\"ש ובנ\"י הלכו ביבשה בתוך הים דהיינו שהי' גילוי בחי' ים ביבשה ממש כמו שהיו נפרדים והי' בהם יצה\"ר ג\"כ, ואעפי\"כ הי' בהם הגילוי שבעלמא דאתכסייא וכמו שאמרו זה אלי כו', וכדי שיהי' גילוי גדול כזה מעלמא דאתכסייא בעלמא דאתגלייא הוצרך להיות המשכה גבוה שלמעלה מבחי' עלמא דאתכסייא לעלמא דאתגלייא.\n<b>ושורש</b> הענין הוא דהנה כתי' כי אל דיעות הוי' ב' בחי' דיעות ד\"ע וד\"ת, ד\"ע הוא מלמעלה למטה שלמעלה הוא היש ולמטה הוא האין שכולא קמי' כלא חשיב ממש, וזהו בחי' עלמא דאתכסייא בחי' יחו\"ע ביטול במציאות ממש, וד\"ת הוא מלמטה למעלה שהבריאה הוא מאין ליש שלמטה הוא היש ולמעלה הוא אין לפי שאינו מושג בבחי' יחו\"ת שהוא רק ביטול היש לאין שהיש הוא בטל אך אעפי\"כ הוא בחי' יש, אך כדי שיהי' התחברות ב' הדיעות שד\"ע יהי' מאיר בד\"ת בחי' יחו\"ע יהי' מאיר ביחו\"ת שיהי' הגילוי למטה כמו למעלה שאין זה ע\"פ השתלשלות כו', וכדי שיהי' התחברות ב' הדיעות זהו ע\"י"],[4101400165,"שם אל שהוא בחי' הארת אוא\"ס שלמעלה מב' הדיעות, כי שם אל הוא מקור י\"ג מדה\"ר, וכמ\"ש ה' אל רחום וחנון כו' מי אל כמוך נושא עון, וע\"י הארת שם אל יכול להתחבר ב' הדיעות כאחד שיהי' גילוי בחי' ד\"ע בד\"ת ממש, כמו שמצינו גבי משה שאף שהי' למטה בגוף אעפי\"כ השיג בעולם האצי' יותר מכל הנביאים, דהנה נבואת משה הי' חלוק מכל שאר הנביאים, דהנה שאר הנביאים כשהיו צריכים להתנבאות היו צריכים שיהיו בטלים ממהותם מכל וכל והי' בהם הפשטת גשמי' ולא היו מרגישים בשעת מעשה שום חיות כלל לפי שלא הי' הגוף כמו שהוא נפרד יכול לקבל את הנבואה (ששורש הנבואה מבחי' ד\"ע) כלל, וכמ\"ש בחברי דניאל אבל חרדה גדולה נפלה עליהם וארכבותיו דא לדא נקשן וכו', וע\"כ היו צריכים להתפשט מהגשמיות בבחי' ביטול במציאות ממש, משא\"כ משה ע\"ה הי' מקבל את הנבואה כמו שהוא בגוף כו', ולא הי' צריך להבטל מכל וכל וכמ\"ש פה אל פה אדבר בו ומראה ולא בחידות כו', והיינו לפי שמשה הי' מבחי' עלמא דאתכסייא וכמ\"ש מן המים משיתיהו וירד למטה בעלמא דאתגלייא שהוא חיבר בחי' עלמא דאתכסייא בעלמא דאתגלייא ע\"כ הי' יכול לקבל את הנבואה כמו שהוא בגוף כו', וגם ששורש הנבואה שלו הי' ממקום גבוה מאד שהי' יכול לחבר ב' הדיעות, וכמשארז\"ל כל הנביאים נתנבאו בכה משה נתנבא בזה, ע\"כ הי' יכול לקבל את הנבואה כמו שהוא כו', וכך ישראל בשעת קי\"ס הי' חיבור ב' הדיעות והי' הגילוי למטה בעלמא דאתגלייא כמו שהוא בעלמא דאתכסייא, לפי שהי' מאיר למעלה מבחי' השתלשלות הארה מעצמותו כו', וכמ\"ש זה אלי שכ\"א הי' מראה באצבעו ממש זה, והיינו לפי שהי' הגילוי מבחי' כי גאה גאה [אתגאי על גיותניא] למעלה מבחי' סובב וממלא, וזהו מ\"ש עד יעבור עמך ה' למעלה מבחי' שם הוי' וכו', ע\"כ היו יכולים לקבל את הגילוי כמו שהם נפרדים, וזהו ענין קשה כקרי\"ס לפי שהי' הגילוי למעלה מן השתלשלות, כי שרש בריאת העולמות הוא רק מבחי' זיו והארה כו' משא\"כ קרי\"ס הוא המשכה מעצמותו ומהותו כו', וזהו ענין וידגו לרוב בקרב הארץ, פי' וידגו הוא בחי' דגים שבים בחי' עלמא דאתכסייא וביחד שבחי' דגים שבים יהי' בקרב הארץ דוקא דהיינו שהגילוי דעלמא דאתכסייא יהי' בעלמא דאתגלייא כו', וזהו ענין אחד ועד, אחד הוא בחי' עלמא דאתכסייא, וכמ\"ש יקוו המים אל מקום אחד, שהוא בחי' יחו\"ע ביטול במציאות, ועד הוא בחי' עלמא דאתגלייא יחו\"ת בחי' ביטול היש לבד, וכדי שיהי' גילוי בחי' אחד בועד זהו ע\"י בחי' יחיד שהוא בחי' עצמותו ומהותו כו', ועי\"ז יכול להיות שיהי' הגילוי למטה כמו למעלה כו'.\n<b>והנה</b> זהו ג\"כ מה שמצינו בגמ' ב\"ש אומרים שמים נבראו תחילה שנאמר בראשית ברא אלקי' את השמים ואת הארץ, וב\"ה אומרים ארץ נבראת תחלה שנאמר ביום עשות הוי' אלקי' ארץ ושמים, ור\"ש בן יוחאי אומר תמה אני על אבות העולם האיך נחלקו, שמים וארץ כא' נבראו שנאמר קורא אני עליהם יעמדו יחדיו, והיינו שב\"ש אומרים שמים נברא תחילה כי שמים היינו"],[4101400166,"שם מים שהוא בחי' עלמא דאתכסייא, ואדרבא שהוא למעלה גם מבחי' עלמא דאתכסייא כי שמים היינו מים אשר מעל השמים כו', וע\"כ הוא אומר שמים קדמו לפי שבעלמא דאתכסייא שם הוא הביטול בתכלית ונק' נוני ימא רבא, וב\"ה אומרים ארץ נברא תחילה שעיקר המכוון הוא בשביל הארץ וכמ\"ש ואדם עליה בראתי, והיינו כי יתרון האור מתוך החשך דוקא, ולכך לא ניתנה התורה למלאכי השרת כי כלום יצה\"ר יש ביניכם, והיינו לפי שדוקא ע\"י יצה\"ר וחשך עי\"ז נעשה יתרון האור דוקא, כי במחשבה ארץ קדמה שזה הוא עיקר המכוון שיהי' יתרון האור מתוך החשך דוקא, אך זהו רק ע\"פ סדר השתלשלות שיש מעלה בזה, ויש מעלה בזה, אך רשב\"י אומר תמה אני על אבות העולם שהרי כתי' קורא אני עליהם יעמדו יחדיו שכא' נבראו לפי שלמעלה מסדר השתלשלות יכול להיות שניהם כא' ממש ויכול להיות הגילוי שבעלמא דאתכסייא בעלמא דאתגלייא כו'.\n<b>ובזה</b> יובן ג\"כ מ\"ש במד\"ר שקי\"ס הי' בזכות יעקב, והענין הוא דהנה כתי' האל הגדול הגיבור והנורא אל עליון, והנה הגדול הוא בחי' אברהם שהוא בחי' התפשטות גדולתו ית' שמאיר אא\"ס בבחי' גילוי, והנה מה שמאיר אא\"ס בבחי' גילוי זהו רק בעלמא דאתכסייא ששם מאיר אא\"ס בבחי' גילוי וע\"כ הברואים שבים הם בתכלית הביטול, והגיבור הוא בחי' יצחק שהוא בחי' גבורות וצמצומי' שהוא בחי' עלמא דאתגלייא ששם אינו מאיר אא\"ס בגילוי עד שעי\"ז נעשים בחי' נפרדים כו', והנורא הוא בחי' יעקב שמחבר ב' בחי' אלו, כי יעקב הוא בחי' קו האמצעי בחי' ת\"ת שמחבר ב' הקווין כי קו האמצעי עולה עד הכתר, וע\"כ יכול לחבר ב' בחי' אלו, וכמ\"ש המשל ופחד עמו עושה שלום במרומיו, שכדי שיהי' שלום במרומיו בין מיכאל וגבריאל מיכאל שר של מים וגבריאל שר של אש שהם שני הפכים וכדי שיתחברו זהו ע\"י המשל ופחד עמו שמאיר עליהם אור הגבוה משניהם ע\"כ עי\"ז יכולים להתחבר כו', וכך ע\"י והנורא אל אליון שהוא בחי' גבוה מאד, כי וי\"ו דוהנורא שהוא בחי' ת\"ת שעולה עד הכתר ע\"כ יכול לחבר ב' הפכי' אלו וזהו כמו ענין קרי\"ס ממש שהי' ג\"כ התחברות ב' דיעות עלמא דאתכסייא בעלמא דאתגלייא, וע\"כ אמר המד\"ר (שמות פ' ך\"ג) שר\"ע אומר שקרי\"ס הי' בזכות יעקב לפי שהוא מדריגת יעקב, שיש בכחו לחבר ב' הפכים אלו.\n<b>ובזה</b> יובן מ\"ש שקרי\"ס הי' קשה דלכאורה בריאת יש מאין הוא יותר פלא, והיינו לפי שבריאת יש מאין הוא רק מבחי' זיו והארה בעלמא שאינו נוגע אל עצמותו כו', משא\"כ קרי\"ס שהוא התחברות ב' דיעות שיהי' הביטול שבעלמא דאתכסייא בעלמא דאתגלייא שהם שני הפכים, וכדי שיהי' שני הפכים אלו בנושא אחד ממש ביטול שבעלמא דאתכסייא וגם שיהי' בחי' נפרד שא\"א להיות ע\"פ סדר השתלשלות הוצרך להיות ע\"י המשכה שלמעלה מסדר השתלשלות שהוא המשכה מעצמות אא\"ס, וזהו קשה דהיינו המשכה מעצמותו"],[4101400167,"שלמעלה מסדר השתלשלות, לפי שהוא חיבור שני הפכים בנושא אחד כו' וד\"ל. ועתה י\"ל מה שאמרו קשה לזווגם כקרי\"ס מהו ענין הזיווגים שקשה כ\"כ כו'.\n<b>והענין</b> הוא דהנה ע\"פ קבלה [קי\"ס] נק' בשם לידה, והנה מתחלה כדי שיהי' בחי' לידה צריך שיהי' בחי' עיבור וזיווג כו', ולזה א' שגם הזיווג שהוא בחי' לידה קשה ג\"כ כקרי\"ס שהיא הלידה, והענין הוא דהנה כתי' כי על כל כבוד חופה, שיש ב' בחי' כבוד עילאה וכבוד תתאה שהוא בחי' כבוד חתן וכבוד כלה, וענין ב' בחי' כבוד זהו ענין ד\"ע וד\"ת, ד\"ע הוא שכולא קמי' כ\"ח הגם שהתהוות העולמות הוא מבחי' דיבור ודיבור נעשה נפרד, אך באמת למעלה אין לך דבר שחוץ מעצמותו וע\"כ כולא קמי' כ\"ח, וד\"ת הוא שנראה העולם ליש ודבר נפרד כו', וזהו ב' בחי' כבוד. וזהו מ\"ש מכה\"כ וכתי' אי' מקום כבודו, והיינו שכבוד תתאה הוא מכה\"א כבודו, וכבוד עילאה הוא בבחי' אי' מקום כבודו שאינו מושג כלל כו', וזהו בחי' סוכ\"ע וממכ\"ע, וכדי שיהי' הגילוי מבחי' כ\"ע בכ\"ת, זהו ע\"י חופה וכמ\"ש כי על כל כבוד חופה שהוא בחי' מקיף הכללי שלמעלה מב' הבחי' כבוד ועי\"ז יכול להיות הגילוי מבחי' כ\"ע בכ\"ת, וזהו מ\"ש למען יזמרך כבוד ולא ידום נהו\"ת קארי תדיר לנהו\"ע, והנה כדי שיהי' המשכה מבחי' כ\"ע בכ\"ת בחי' ד\"ע בד\"ת זהו ג\"כ קשה לפי שהוא למעלה מהשתלשלות שהוא ע\"י חופה מקיף הכללי וזהו קשה לזווגם כקרי\"ס, ואעפ\"כ קרי\"ס יותר קשה (שהוא רק כקרי\"ס בכף הדמיון לבד), והיינו לפי שענין הזיווגים הוא רק המשכה למעלה כ\"ע בכ\"ת (דהיינו מבחי' ח\"ע במל'), אבל ענין קרי\"ס הוא המשכה למטה בעוה\"ז הגשמי וכמ\"ש זה אלי וע\"כ הוא יותר קשה, לפי שכל שצריך לירד למטה יותר מוכרח שההשפעה נמשך מלמעלה יותר כו'.\n<b>ומתחילה</b> י\"ל מ\"ש החדש הזה לכם שמשה נתקשה בחידוש הלבנה והענין הוא, דהנה ישראל מונים ללבנה ולכאורה אינו מובן זה למה ישראל מונים ללבנה שהרי החמה הוא למעלה הרבה מבחי' לבנה, וכמ\"ש כי שמש ומגן הוי' אלקי' ששם הוי' נמשל לשמש כו', וא\"כ למה ישראל מונים ללבנה ואוה\"ע מונים לחמה דוקא, והענין הוא דהנה איתא בספר נחמד ונעים בשם החכם אבן עז' פ' החדש, שאין לחמה חדשים, כי חדשים הוא ללבנה דוקא, לפי שבכל ל' יום נתחדש הלבנה, ומה שיש גם לאוה\"ע י\"ב חדשים זהו רק שם המושאל, שמחלקי' את השנה לי\"ב חדשים לפי שיש י\"ב מזלות ע\"כ הם מחלקי' את השנה לי\"ב, אבל בחמה עצמה אין בה חדשים, כי חדש הוא ל' התחדשות שנמשך אור חדש ממש וזה ההתחדשות הוא בלבנה דוקא, כי יש ב' בחי' התחדשות דהיינו מה שבכל יום נמשך המשכה לחדש את העולמות מאין ליש, וכמ\"ש המחדש בטובו בכ\"י תמיד מעשה בראשית, אך זהו רק בחי' לחדש את הישנות ואין זה המשכה חדשה לגמרי, משא\"כ חידוש החדש הוא המשכה"],[4101400168,"חדשה לגמרי שמקבלת הלבנה אור חדש ממש שהוא המשכה פנימי' כו'. וזהו מ\"ש בגמ' סנהדרין, ר\"א רמי כתי' טוב ה' לכל, וכתי' טוב ה' לקוויו, משל לא' שיש לו פרדס כשהוא משקה משקה לכולם וכשהוא עודר אינו עודר אלא הטובים שבהם, וכך למעלה כשהוא משקה משקה לכולם דהיינו כשנמשך המשכת אא\"ס לחדש את העולמות מאין ליש, אז הוא נמשך לכולם בשוה לפי שבהארה אחת הוא מחי' את כולם, וזהו טוב ה' לכל כי טוב הוא בגי' שם א' ה' ו' ה' שיוצא מר\"ת בראשית ברא אלקי' את השמים ואת הארץ, ואיתא בזוהר שהוא גושפנקא דחתים בה שמיא וארעא, אמנם זהו בחי' טבע ומדריגות, דלכאורה אינו מובן מהו ענין טבע שהרי הכל נמשך מלמעלה וכמ\"ש המכין לארץ מטר המצמיח הרים חציר הנותן שלג כצמר שהכל נמשך מלמעלה וא\"כ מהו ענין טבע כו'.\n<b>אך</b> הענין הוא דהנה טבע הוא מלשון טבעו בים סוף דהיינו שהחיות אלקי הנמשך הוא מוסתר ונעלם שאינו נראה ונגלה לכל לפי שנמשך תמיד במדריגה א', כמו למשל שהתבואה נגדל מהשמש וכמ\"ש ממגד תבואות שמש וממגד גרש ירחים, והנה אף שהם נגדלים מהשמש, אין הפי' שהשמש מצד עצמו מגדלם, רק שהוא כח אא\"ס מלמעלה, ואין השמש יודע כלל מזה ואין לו בחירה כלל רק כשהשמש מאיר ממילא הם נגדלים ברצון כח אלקי והשמש הוא רק כגרזן ביד החוצב בו שאינו יכול לשנות כלום, רק אעפי\"כ כיון שהשפעה זו נמשך ע\"י השמש אף שהוא השפעה מלמעלה מ\"מ נראה שהוא ע\"י השמש ומחשבים את השמש ליש ודבר כו', וזהו ענין טבע שהחיות אלקי הנמשך בהם הוא בבחי' טביעה שאינו נראה וניכר כלל, וזהו ענין חותם שוקע כמו למשל חותם שוקע שאינו ניכר בתוכו האותיות כלל אף שישנם שם האותיות מ\"מ אינם ניכרים כו', וכך בחי' טוב ה' לכל שהוא גושפנקא דחתים בה שמיא וארעא, שהוא המחדש בטובו בכ\"י תמיד מעשה בראשית, הוא בחי' חותם שוקע שהחיות אלקי מוסתר ונעלם כו', וכמ\"ש אכן אתה אל מסתתר שמוסתר ונעלם כו', אך בחי' טוב ה' לקויו הוא בחי' השפעה פנימי' שנק' חותם בולט, דהיינו שהחיות אלקי הנמשך הוא בבחי' בליטה ונראה ונגלה לעין כל, וכמו קרי\"ס ויצי\"מ שהיו גילוי אותות ומופתים כו' הכל היו רואין את החיות אלקי הנמשך וזהו בחי' חותם בולט שהוא בחי' השפעה פנימי' כו'.\n<b>והנה</b> המשכה זו זהו דוקא לקויו שהוא ע\"י ביטול שא\"א להיות נמשך המשכה זו כ\"א ע\"י ביטול לפי שהוא המשכה חדשה, וכמו שאנו רואים שהלבנה א\"א לה לקבל אור חדש מן השמש כ\"א ע\"י בחי' ביטול מכל וכל, שמתחלה עד ט\"ו יום נתגדלת מעט מעט, ואח\"כ כשצריכה הלבנה להתקרב להשמש מתמעטת מעט מעט עד שנתכסה אח\"כ ואינו נראה כלל, וכמ\"ש שחורה אני אזעירת גרמא כנקודה חדא, לפי ששזפתני השמש שאינו מאיר השמש כו', וע\"כ כדי לקבל המשכה זו צריכה להתבטל, ואח\"כ ע\"י זה יכולה לקבל אור"],[4101400169,"חדש ממש, ונעשה יחוד שמשא וסיהרא, [וע\"י] היחוד נמשך המשכה מלמעלה מב' הבחי', וכדי שיוכל להיות יחוד שמשא בסיהרא זהו ע\"י המשכה שלמעלה משניהם, כי הנה שמש הוא בחי' שמש הוי' שהוא בחי' יחו\"ע ביטול במציאות ממש כביטול זיו השמש בשמש, ולבנה שהוא בחי' מל' נעשה מקור לעולמות הנפרדים כו', וכדי שיהי' התחברות ב' בחי' ויהי' יחוד שימשא בסיהרא זהו ע\"י המשכה שלמעלה משניהם וכמ\"ש לעיל, וע\"י זה נמשך שיהי' המשכה חדשה שלא הי' מקודם כלל, וזהו ענין הזיווגים שהיא המשכה חדשה ממש כמו למשל זיווג גשמי שע\"י זיווג נמשך בחי' הולדה שהוא המשכה חדשה ואינו כמו המאכל שאף שהמאכל ג\"כ הוא מחדש את הגוף שאם לא המאכל הי' הנפש נפרד מהגוף וע\"י המאכל נתחבר הנפש עם הגוף מ\"מ אין זה המשכה חדשה לגמרי רק לחדש את הישנות, אבל הולדה שע\"י זיווג הוא המשכה חדשה ממש, וזהו ענין קשה לזווגם כקרי\"ס, לפי שענין הזיווגים הוא בחי' יחוד שמשא בסיהרא שהוא התחברות ב' דיעות כו' שהוא ממש כמו ענין קרי\"ס כו', אך להיות היחוד א\"א כ\"א ע\"י בחי' ביטול דוקא, וכמו שאנו רואים למשל שהתבואה אם לא ירקב מקודם אזי לא יצמיח כלל וכדי שיהי' בחי' הצמיחה צריכה להרקיב מקודם עד שנעשה בחי' אין ועי\"ז יכולה להצמיח כו', וכך כדי שתקבל המשכה חדשה זהו ע\"י בחי' ביטול כו', וזהו ישראל מונים ללבנה דוקא והיינו שכמו שהלבנה מקבלת אור חדש מהשמש המשכה פנימי' כו' ע\"י בחי' ביטול שלה כך ישראל מקבלים המשכה פנימי' מאא\"ס בחי' חותם בולט, טוב ה' לקויו כו'.\n<b>ובזה</b> יובן הקושיא שמקשים הכותים כיון שר\"ה הוא בחי' ראש לשנים ואיך ניסן ראש לחדשים וכמ\"ש ראשון הוא לכם לחדשי השנה ואיך יכול להיות שניהם וכמבואר הקושיא שלהם בהראב\"ע. אך הענין הוא דמה שר\"ה הוא בחי' ראש זהו בבחי' התחדשות הבריאה מאין ליש ובטובו מחדש בכ\"י תמיד מעשה בראשית בחי' טוב ה' לכל שהוא בחי' טבע כו', אבל א\"ז חידוש גמור רק לחדש את הישנות כי בחמה אין בה חדשים שהוא בחי' התחדשות גמור כו', אך ניסן הוא בחי' ראש לחדשים דהיינו שיהי' התחדשות גמורה גילוי פנימי' בחי' גילוי אותות ומופתים, בחי' טוב ה' לקויו, היטיבה ה' לטובים, לזה הוא ניסן ראש כי בניסן הי' תחילת התגלות אותות ומופתים יצי\"מ וקרי\"ס כו', והמשכה זו א\"א להיות כ\"א העלאה מתחלה כי רוח אייתי רוח ואמשיך רוח.\n<b>וזהו</b> [דאיתא] במדרש ע\"פ זה וידבר ה' אל משה ואל אהרן בא\"מ לאמר החדש הזה לכם ראש כו', טובים השניים מן האחד, טובה פרשה שנאמרה לשנים שהוא משה ואהרן ממה שנאמרה למשה לבד, ולכאו' אינו מובן זה כלל איך שייך לומר בתורה שפרשה זו יותר טובה כו', אך הענין הוא דהנה משה ואהרן הוא בחי' שושבינא דמלכא ואהרן הוא שושבינא דמטרוניתא, כי משה"],[4101400170,"הוא הממשיך מלמעלה למטה ולכך נתן משה דוקא את התורה לישראל, וזהו שהתורה נק' ע\"ש משה וכמ\"ש זכרו תורת משה, ואהרן הוא בחי' שושבינא דמטרוניתא מלמטה למעלה שהוא המעלה את נש\"י מלמטה למעלה וכמ\"ש בהעלותך את הנרות שמעלה את נש\"י שיהי' להם אה\"ר ותשוקה לאא\"ס, והנה ע\"י העלאה זו אזי נמשך המשכה עליונה יותר, כי הגם שע\"י תורה נמשך ג\"כ המשכת אא\"ס, אך מ\"מ אינו דומה המשכה שמצד עצמה מההמשכה שע\"י העלאה מתחילה, כי כל האומר אין לי אלא תורה אפי' תורה אין לו כו', ע\"כ צריך להיות שניהם דוקא.\n<b>ובזה</b> יובן מ\"ש במד\"ר שמהחדש הזה לכם תזכו לכל בחי' לכם, והיינו שפי' החדש הזה לכם היינו שתהיו מונים ללבנה דוקא שהוא בחי' ביטול שחורה אני כו', וכך ישראל שהם מונים ללבנה הם בבחי' ביטול שלהם שהם בטלי' לאלקות, וע\"י שהחדש הזה לכם שתהיו בבחי' ביטול עי\"ז תזכו לכל בחי' לכם, ולהבין זה למה ע\"י החדש הזה לכם תזכו כו', והענין הוא דהנה איתא ברבות ע\"פ אחת שאלתי מאת ה' אותה אבקש ואח\"כ כתי' שבתי בבית ה' כל ימי חיי לחזות בנועם ה' ולבקר בהיכלו, אמר לו הקדב\"ה, דוד מתחלה אתה אומר אחת שאלתי ואח\"כ אתה מבקש שאלות הרבה, וא\"ל דוד ממך למדתי, שמתחלה כתי' ועתה ישראל מה הוי' אלקיך שואל מעמך כ\"א ליראה שמשמע יראה לבד ואח\"כ כתי' ללכת בדרכיו ולדבקה בו כו', ולכאורה אינו מובן זה באמת דא\"כ למה כתי' כ\"א ליראה, אך הענין הוא דהנה באמת עיקר הבקשה הוא ליראה את הוי' וכשיהי' היראה בשלימות אזי ממילא יהיו כל הבחי', דהנה בחי' יראה הוא כמו למשל יסוד שאם היסוד הוא טוב אזי יכולים לבנות על היסוד בנינים הרבה, ויכול להתקיים, ואם היסוד אינו טוב כ\"כ אזי לא יוכלו להתקיים הבנינים שבונים עליו, וכך יראה הוא עיקר היסוד ואם יהי' היראה בשלימות אזי ממילא יהיו כל הבחי' לאהבה את הוי' אלקיך וללכת בדרכיו ולדבקה בו, כי אף שהיראה הוא למטה ממדריגת אלו כי אהבה הוא למעלה מיראה כי היראה היא רק קבעומ\"ש אך אעפי\"כ היראה היא היסוד כי שרש יר\"ת הוא מיר\"ע כו', שלמעלה מבחי' אהבה ואפי' מאה\"ר וא\"כ היראה היא היסוד, וזהו מ\"ש מה הוי' אלקיך שואל מעמך כ\"א ליראה שהעיקר הוא היראה, ובזה יובן ג\"כ מ\"ש החדש הזה לכם שמזה לכם דוקא תזכו לכל בחי' לכם שהעיקר הוא בחי' החדש הזה לכם שהוא בחי' ביטול, וע\"י הביטול דוקא אזי עי\"ז תזכו לכל בחי' לכם שהם למעלה הרבה מבחי' זו אף עפי\"כ ההתחלה צריך להיות דוקא מבחי' יראה בחי' ביטול וכמ\"ש בזאת יבא אהרן אל הקדש דא הוא תרעא לאעלאה כו'.\n<b>והנה</b> כמו שיש בחי' התחדשות בכל חדש שמקבלים הארה חדשה מעצמותו, כך הנה כתי' והיו הדברים האלה אשר אנכי מצוך היום שבכל יום יהיו בעיניך כחדשים ממש והיינו ע\"י התורה נמשך בחי' התחדשות זו בכל יום לפי"],[4101400171,"שאורייתא מח\"ע נפקת, ועי\"ז תזכו אח\"כ לבחי' ראו כי הוי' נתן לכם השבת שלמעלה מבחי' החדש הזה לכם וכמ\"ש שער החצר הפנימי' הפונה קדים סגור יהי' ששת ימי המעשה וביום השבת יפתח וביום החדש יפתח הוא למעלה מבחי' חדש, וזהו ראו כי הוי' נתן לכם השבת שע\"י בחי' החדש הזה לכם שהוא בחי' תורה בכל יום יהיו בעיניך כחדשים עי\"ז הוי' נתן לכם השבת, וזהו כל עיסקא דשבת כפול, והיינו כי כפול הוא בחי' התכללות מב' בחי' וזהו זכור ושמור זכור לדכורא ושמור לנוק', זכור לדכורא הוא בחי' יח\"ע ביטול במציאות, ושמור לנוק' הוא בחי' יחו\"ת ביטול היש, אך זכור ושמור בדיבור א' נאמרו הוא ע\"י בחי' שלמעלה משניהם וע\"כ עי\"ז נעשה בחי' התכללות זו, וזהו כפול, כפול מב' בחי', וזהו ממש כמו ענין חידוש החדש שנעשה יחוד שמשא בסיהרא אך זהו בחי' גבוה יותר כו', וזהו ראו כי הוי' נתן לכם את השבת, שהוא בחי' התכללות מב' בחי' זכור ושמור שני כבשים שמורה על בחי' המשכה מעצמות אא\"ס עד שמאיר למטה כמו למעלה ממש כנ\"ל וד\"ל."],[4101400172,"<h3>ולהבין בתוס' ביאור ענין קשה לזווגם</h3>\n<b>ולהבין</b> בתוס' ביאור ענין קשה לזווגם, איך שייך לומר ל' קשה, יש להבין תחילה מה שאמר ר' יוחנן בן זכאי איני יודע באיזה דרך מוליכין אותי, הלא ר\"י ב\"ז הי' שר התורה, ואיך הי' הספק אצלו לאיזה דרך, ואף בדרך ענוה אינו שייך לומר כן כי גם ענוה צריך שיהי' צד סברא שיכול לומר כן, משא\"כ [ריב\"ז] איך א' איני יודע כו'. אך יובן בהקדים מה שמצינו לפעמים שמעלת התורה היא יתירה על המצות כמאמרם ז\"ל ותלמוד תורה כנגד כולם, ולפעמים מצינו שיש יתרון המעלה בתפלה נגד התורה וכמאמרם ז\"ל והלואי שיתפלל כל היום כולו ואף שלא ילמוד כו', וכמו שמצינו גבי דניאל שמסר נפשו על התפלה כמ\"ש וכוין פתיחין לי' נגד ירושלים.\n<b>אך</b> הענין הוא דהנה כתי' חדלו לכם מן האדם אשר נשמה באפו כי במה נחשב הוא, ולמדו מזה הפסוק שאסור לאכול קודם התפלה, והיינו שקודם התפלה הנשמה באפו ולאחר התפלה הנשמה מתפשטת בכל הגוף, ופי' תפלה הוא ענין תפלה שהוא בכלל גמ\"ח כמ\"ש רש\"י בשבת שענין תפלה הוא בכלל גמ\"ח ע\"ש גומל נפשו איש חסד, וצ\"ל איך ע\"י התפלה מתפשטת הנשמה בכל הגוף. וצ\"ל תחילה מהו ענין הנשמה הלא ע\"כ לומר שיש בחי' נשמה לבד השכל והמדות, וראי' לזה ממה שארז\"ל אבות חביב אדם שנברא בצלם אלקי' והיינו מפני שיש לאדם שכל ומדות וא\"כ מה שא' אח\"כ מעלה מה שנקראו בנים למקום הוא מעלה יתירה על המעלה מה שנבראו בצלם אלקי', א\"כ ע\"כ לומר שמעלת מה שנקראו בנים למקום הוא מצד הנשמה עצמה כו'. ואין"],[4101400173,"לומר שזהו מעלת התורה שהרי אח\"כ אמרו חביבין ישראל שניתן להם כלי חמדה הרי בהכרח לומר שמעלה זו שנקראו בנים הוא יתרון על בחי' הצלם, וגם אינו בחי' התורה, ובלשון הפ' מצינו ג\"כ מה שמו ומה שם בנו, מה שמו ה' צבאות שמו, ומה שם בנו בני בכורי ישראל, בנים אתם להוי' אלקיכם, והיינו כמו שהבן נמשך ממוח האב כמ\"כ יש בכ\"א מישראל חלק אלקה ממעל, ואף כי לא יתכן עליו ית' לומר אב ובן, אך דברה תורה כלשון בנ\"א, וכמ\"ש במדרש אלא שחיבבן הכתוב וקראן בנים.\n<b>וביאור</b> הענין הוא, הנה יש בנפש האדם שני בחי' הא' הוא בחי' ע\"ס הנפש שהם מוחין ומדות, והנה אנו רואים שלפי ערך השכל יהי' המדה, דהיינו אם יתבונן היטב מעניני אלקו' אזי יוליד בחי' מדת אהבה לאלקו' ואם מתבונן בעומק יותר יהי' האהבה יותר חזקה, וכמ\"ש לפי שכלו יהולל איש, שלפי ערך השכל מתנהג האדם, והנה אנו רואים שיש כח בכאו\"א מישראל למסור נפשו לאלקי' אשר זה נגד השכל שע\"פ השכל אינו יכול להיות שימסור נפשו, אך בחי' מס\"נ זהו מחמת שיש כח בכאו\"א מישראל שהוא למעלה מן השכל והטעם וכמ\"ש לאהבה את ה' כי הוא חייך הרי שטעם לאהבה הוא, מפני כי הוא חייך דוקא מה שא\"כ מס\"נ הוא היפוך החיים, ולזה אין טעם כלל, רק שאינו ע\"פ טעם ודעת רק למעלה מן השכל והוא בחי' רצון שהוא למעלה מן השכל המושג ומובן כו', וזהו בחי' צלם, ובחי' בנים, כי הנה צלם הוא בחי' ע\"ס הנפש שהוא חכ' ומדות אבל בחי' בנים הוא הכח ומס\"נ שהוא בחי' הרצון שלמעלה מן השכל, ושרש שני בחי' אלו הוא כי הנה השתל' העולמות הוא מבחי' חכ', כי חכ' הוא ראשית ההשתלשלות, אבל עצמותו ומהותו ית' הוא למעלה מגדר עולמות כו' כמאמר אנת חכים ולא בחכ' ידיעא לאו דאית לך כו' מכל אינון מדות כלל, שהמדות אינם אלא לאחזאה איך מתנהג עלמא, וכמ\"ש והחכ' מאין תמצא שמהות החכ' הוא מאין, והנה אין ערוך בחי' החכ' לגבי האין שנתהווה מאתו בחי' החכ', ומשני בחי' אלו הם שורש שני הבחי' הנמצאי' בכאו\"א מישראל הא' בחי' עשר בחי' הנפש, הב' שיש כח בכאו\"א מישראל למס\"נ אשר זה נגד השכל, ושרשה מבחי' אין שלמעלה מן החכ' כנודע.\n<b>והנה</b> בחי' זו שלמעלה מן השכל מתגלה במדריגת התפלה כי ע\"י התפלה יכול למס\"נ באחד, והיינו כי ע\"י התפלה מתפשטת הארה מכח מס\"נ שיש בכ\"א מישראל לכל בחי' הגוף, כי קודם תפלה הארה זו הוא רק במוחו לבד והיינו כי אף שמשיג בשכלו היטב ענין איך שכולא קמי' כלא חשיבי אבל מ\"מ אינו נוגע כלל לעצמו אבל ע\"י התפלה מתפשטת בגוף ג\"כ שמרגיש ג\"כ בגוף והיינו ע\"י התבוננות תחילה בפ' שמע ישראל. וזהו שהי' ר\"י ב\"ז מסופק שאינו יודע באיזה דרך כו' כי הנה אף שהי' שר התורה אעפי\"כ אינו אלא בבחי' החכ' כי אורייתא מח\"ע נפקת, אבל בחי' ומעלת התפלה יש בה מעלה"],[4101400174,"יתירה נגד בחי' התורה, דהיינו מחמת עצמות הנשמה שהוא בחי' הרצון שלמעלה מן השכל, ובזה הי' מסופק אם הי' עבודתו שלימה גם בבחי' זו. וזהו שארז\"ל בכה רבי ואמר יש קונה עולמו בשעה א' שכל מה שהשיג ע\"י תורתו כל שניו הגיע ראב\"ד בשעה א', והיינו כי בחי' מס\"נ שהוא בחי' רצון פשוט כולל כל בחי' התורה והוא ע\"ד מ\"ש רגלי החיות כנגד כולם קרסולי החיות כנגד כולם, שבחי' אחת ממדריגה הגבוה כוללת כל הבחי' שלמטה הימנה.\n<b>וזהו</b> ג\"כ מה שאמר ר\"י ב\"ז אלמלא הניח ב\"ז את ראשו בין ברכיו כל היום לא היו משגיחין עליו ור\"ח ב\"ד נענה מיד, ואף שריב\"ז הי' גדול הרבה בתורה ממנו, והיינו לפי שע\"י בחי' עצמות הנשמה שהוא בחי' הרצון בזה הי' רחב\"ד גדול. וזהו הוא דומה כעבד לפני המלך ואני כשר לפני המלך, עבד הוא בחי' ביטול הרצון שלמעלה מן השכל, ואני כשר לפני המלך שהוא בחי' ומדרי' חכ' אורייתא מח\"ע נפקת כו'.\n<b>אך</b> הנה ע\"י מה יגיע לבחי' רצון ומס\"נ זה הוא ע\"י התבוננות בק\"ש בפ' שמע ישראל, פי' שמע הוא ל' אסיפה והבנה והיינו שיאסוף ויקלוט בחי' התבוננות אצלו שיתבונן איך שכולא קמי' כ\"ח ואינו תופס מקום כלל, וכשיתבונן בזה היטב בעיון שכלו ובעומק הבנה אזי באמת לא יחפוץ לא בגעה\"ת ולא בגעה\"ע כ\"א לעצמותו ומהותו ית' וכמ\"ש אין לי חפץ אלא בך, ואח\"כ כשיש בחי' רצון זה נק' ישראל, פי' ישראל לי ראש כמו שהראש הוא בחי' מוחין ויש בחי' גלגלתא דחפיא על מוחא, כמ\"כ ע\"י התבוננות זה שהוא בחי' מוחין ממשיך בחי' ומדריגה גבוה מאד בחי' גלגלתא שהוא בחי' רצון, גם פי' ישראל ל' שר בחי' שרית עם אלקי' בבחי' אתכפייא ואתהפכא מחשוכא לנהורא, ואח\"כ כתי' הוי' אלקינו פי' אלקינו שלנו (בל\"א אונזער גאט) וזהו ע\"ד שנאמ' גבי אברהם אלקי אברהם, ולכאורה יפלא מהו אלקי אברהם דוקא הלא הוא ית' אלקי כל הארץ יקרא, והענין הוא דהנה אברהם הוא בטל בתכלי' הביטול לעצמותו ית' ולא הי' לו שום תפיסת מקום כלל וכמ\"ש ואנכי עפר ואפר והי' תמיד בחי' מרכבה לאלקו' ולכן נק' אלקי אברהם וכמו\"כ כשיתעורר האדם בבחי' רצון זה שהוא תשוקה נפלאה לעצמותו ית' אזי נק' הוי' אלקינו, ה' אחד היינו כשנעשה בחי' השתלשלות, כי אחד מורה א' בחי' אאלפך חכ' אאלפך בינה, ח' ז' רקיעים וארץ וד' הוא ד' רוחות העולם.\n<b>והנה</b> רצון זה הוא בתפלה דוקא כי תפלה הוא בחי' העלאה והיינו בחי' רצון וכמ\"ש והנה סלם מוצב ארצה וראשו מגיע השמימה ואמרו בזוהר סולם דא צלותא והיינו כי כמו שבסולם מחבר הגג עם הארץ וע\"י יכולים לעלות למעלה כמ\"כ יכולים לעלות למקום גבוה מאד, אך כיצד יגיע לבחי' זו, פי' אף כי ע\"י התפלה מתעורר ברצון חזק בל ימוט בבחי' מס\"נ אעפי\"כ לא כל הרוצה ליטול את השם יטול, והעצה לזה למצוא ולהשיג בחי' זו הוא ע\"י התורה, כי"],[4101400175,"אורייתא וקודב\"ה כלא חד ונק' איהו וחיוהי וכשלומד התורה לשמה אזי מקשר דעתו ומחשבתו בשכל התורה ונעשה חד (וע' בד\"ה להבין מ\"ש בס' בינונים פ' ך\"ג) וכמ\"ש תלת קשרין מתקשראן דא בדא ישראל באורייתא ואוריי' בקודב\"ה, וכמו\"כ ע\"י עשיית המצות כי רמ\"ח פיקודין רמ\"ח איברין דמלכא ונמצא שצריכין שני בחי' היינו בחי' התפלה ובחי' התורה. וזהו מה שלפעמי' מצינו שהתורה גבוה ופעמי' מצינו שהתפלה גבוה, ובאמת שניהם אמת, כי התפלה הוא בדרך העלאה והתו' הוא בדרך המשכה כי בתורה מלובש רצה\"ע, ובה וע\"י ממשיכים גילוי אלקותו ית' למטה דוקא.\n<b>וזהו\"ע</b> קשה דקרי\"ס כי ים הוא בחי' עלמא דאתכסייא וארץ הוא בחי' עלמא דאתגלייא, והנה כל מה שיש בים יש ביבשה, רק ההפרש כי הנבראי' שבים הם מובלעים ובטלים בים והים מכסה עליהם וזהו שנק' המלאכי' בשם נוני ימא לפי שהם בבחי' ביטול, משא\"כ ברואים שביבשה אף שמקבלים חיות מהארץ וכמ\"ש ארץ אשר ממנה תוצא לחם ואעפי\"כ הם נפרדים מן הארץ, וקרי\"ס הוא שנעשה מים יבשה והיינו שהאיר בחי' עלמא דאתכסייא בעלמא דאתגלייא, והיינו שכמו שהם בחי' נפרדים הלכו בים בחי' עלמא דאתכסייא, שהאיר בהם בחי' הביטול כמו שהיו בגופים בחי' נפרדים, וזהו קשה שמאיר בחי' עלמא דאתכסייא בעולם הנבראים ונפרדים וכמ\"ש באריכות בד\"ה ראו כי הוי' נתן לכם השבת, וזהו ג\"כ בחי' תורה כמ\"ש ר\"ע והמשיל לדגים שבים מה דגים שבים מיד שפורשים הם מתים כך הפורש מן התורה, וע\"י בחי' התורה הוא כמ\"ש וידגו לרב בקרב הארץ שמאיר בחי' עלמא דאתכסייא בעלמא דאתגלייא ויהי' הברואים שהוא בחי' עלמא דאתגלייא כמו דגים שהם ברואים שבים בחי' עלמא דאתכסייא, וזהו לזווג זווגים כקרי\"ס כי הנה ענין הזיווג הוא ע\"י קידושין שמקדשה בטבעת ואומר הרי את מקודשת לי עי\"ז נתקדשה לו ונאסרה על כל העולם, וכמו\"כ יובן למעלה הנה כנס\"י נק' בשם כלה וכמ\"ש לבבתני אחותי כלה והקדב\"ה נק' חתן כידוע ומבואר במ\"א, והקידושין הוא בחי' אשר קדשנו במצותיו שהוא בחי' קידושין, וזהו ג\"כ קשה כי הקידושין נמשך מבחי' סוכ\"ע שהוא מבחי' עגולים כדוגמת הטבעת קידושין שהוא עגול, ומאחר שנמשך מסכ\"ע למטה הוא דבר קשה כי אל דיעות הוי' ד\"ת שלמטה יש ולמעלה אין, וד\"ע שלמעלה היש האמיתי ולמטה הוא אין, וכשיתחבר בחי' ד\"ע בד\"ת והיינו שגם בד\"ת ישיגו בחי' ד\"ע איך דכולא קמי' כ\"ח זהו דבר קשה מפני שהוא בחי' שני הפכים בנושא א', ונמשך מבחי' אל שהוא מקור י\"ג מדה\"ר כמ\"ש מי אל כמוך נושא עון כו', וזהו אל דיעות הוי' שע\"י שם אל יתחברו דיעות הוי' כו' וד\"ל."],[4101400176,"חסר מע' פח עד ע' צג"],[4101400177,"<h3>וידבר ה' אל משה במדבר סיני</h3>\n<b>וידבר</b> ה' אל משה במדבר סיני באוהל מועד כו' שאו את ראש כו' לגלגלתם כו' אתה ואהרן, וצ\"ל ענין נשיאת ראש מהו, דהנה יש ב' בחי', בחי' ראש ובחי' גלגלתא דחפיא על מוחא, ראש הוא בחי' תלת מוחין שבראש שכל וטעם, ובחי' גלגלת הוא בחי' הרצון מפני שהרצון חופה על הטעם והשכל כמו הגלגלת דחפיא על מוחא, עד\"מ כשמגלה רצונו לזולת הרי אינו מגלה לו רק הרצון אבל הטעם כמוס ונעלם בהרצון, וכמו\"כ למעלה איכא ג\"כ בחי' אלו וכמ\"ש נעשה אדם בצלמנו כדמותינו, דאיתא כשישראל עונין אמן יהא שמי' רבא מברך הקב\"ה מנענע בראשו, אמנם אין המשל דומה לנמשל כלל, דהנה המשל מהרצון הנ\"ל הרי עיקר מציאות הרצון וסיבתו הוא הטעם שנולד ממנו, רק שהרצון חופה עליו בהגלותו לזולת, אבל בחי' גלגלתא הנ\"ל למעלה אין הפי' כן, רק הפי' שהוא למעלה ממש מבחי' המוחין, ולא שהיא רק חופה עליו.\n<b>אך</b> הענין הוא כדאיתא בזוהר אית רצון ואית רצון, אית רצון לתתא ואית רצון לעילא, הענין הוא דאיתא בזוה\"ק ע\"פ נודע בשערים בעלה, דא קוב\"ה דאיהו אתיידע ואיתדבק לכאו\"א לפום מה דמשער בלבי', דנודע הוא ל' התחברות כמ\"ש והאדם ידע, והנה יש עוד פי' נודע ל' רצון כמ\"ש כי רק אתכם ידעתי כלומר רציתי, וגם נודע ל' דעת, והפי' שע\"י בחי' בשערים היינו בחי' שערי בינה בחי' התבוננות בגדולת א\"ס ב\"ה איך שמחי' ומהוה מאין ליש תמיד וכמ\"ש שאו מרום עיניכם וראו כו', ופי' וראו היינו בחי' הבנה והשגה, הנה ע\"י בחי' השגה זו יולד לו רצון לאלקותו ית', ופי' לפום כו' היינו לפי\"ע העמקתו בזה ולפי ריבוי התמדתו ודעת שיחשוב בזה תמיד, והיינו בחי' הרצון שמצד הדעת והשגה כו', דעת תחתון, והגם דלית מחתב\"כ, היינו בי' דווקא במהו\"ע, אבל בבחי' השפלתו והתפשטותו להוות ולהחיות הנה ע\"ז כתי' נודע בשערים כו', ובחי' זו הוא רק בחי' נודע מציאותו ולא מהותו, ועד\"מ השמש וזיו השמש, שאי אפשר כלל להסתכל בהשמש עצמה, ואדרבה יקלקל הראות, וההסתכלות הוא רק בהאור והזיו וכמ\"ש וירא אלקים את האור כי טוב, ועד\"ז יובן למעלה וכמ\"ש כי שמש ומגן הוי' אלקים, שבבחי' הוי' עצמותו לית מחת\"ב, וכל בחי' ההבנה והשגה הוא רק בבחי' גילוי האור והזיו להוות כו', ואית רצון לעילא היינו הרצון בנפש מצד עצמותו ומהותו, וההשגה המביאה לרצון זה הוא בחי' ביטול ההשגה בחי' חכמה כ\"ח מ\"ה דהיינו שישיג היטב ענין זה איך דלית מחתב\"כ ואין ערוך אליו כלל שעי\"ז יתבטלו אצלו כל"],[4101400178,"השגותיו הקודמות, כי לגבי העצמות כולא קמי' כלא חשיבי וע\"י ביטול ההשגה יגיע לבחי' הרצון שמצד עצמותו, בחי' הרצון שלמעלה מטעם ודעת והשגה (וע' כ\"ז בלקו\"ת בד\"ז באורך).\n<b>והנה</b> בחי' רצון זה הוא בחי' ובכל מאודך שבק\"ש כמארז\"ל כתי' ואספת דגניך וכתי' ועמדו זרים ורעו צאנכם, לא קשיא כאן בזמן שישראל עושין רצונו של מקום וכאן בזמן שאין ישראל עושין רש\"מ, וקשה הלא ואספת דגניך כתי' בפ' והי' אם שמוע כו' בכל לבבכם ובכל נפשכם, והתירוץ הוא משום דלא כתי' ובכל מאודכם כמו בפרשה הא' לכן נק' אין ערש\"מ, וי\"ל זה. ועפ\"י הנ\"ל יובן, דהנה בנפש יש עשר כחות הנפש שהם בבחי' השגה והבנה, ואפילו בחי' כתר הוא מכלל עשר כחות לפי שהוא רק בחי' הרצון שמצד הבנה וההשגה, ויש בחי' הרצון שמצד עצמות ומהות הנפש שלמעלה מבחי' הגבלת הכחות הנ\"ל שזהו בחי' ובכל מאודך בלי גבול ולמעלה מבחי' השגה והבנה, ולכן זהו דוקא נק' ערש\"מ, כי פי' רש\"מ היינו בחי' הרצון העליון ג\"כ שלמעלה מגדר השגה והבנה שבסדר ההשתל', ולגבי בחי' רצון זה כתי' ועמדו זרים כו' ביטול הרע, ע\"ד ענין השבת, שיש ב' פי', הא' מל' נייחא והב' מל' ביטול כמ\"ש תשביתו שאור, וכמ\"ש והשבתי חי' רעה כו', כי שבת הוא ג\"כ בחי' ובכל מאודך הנ\"ל, שבשבת מאיר נשמה יתירה שהוא בחי' הרצון העליון שלמעלה מדעת וההשגה, וע\"כ בשבת הוא בחי' ביטול הרע וכדאיתא במדרש ע\"פ מזמור שיר ליום השבת, שעתיד הקב\"ה להשבית המזיקין מן העולם, וכנ\"ל בל' ועמדו זרים כו'. ועפי\"ז יובן כפל הענין שבמשנה עשה רצונו כרצונך כו' בטל רצונך כו' כדי שיבטל רצון אחרים כו', שענין עשה רצונך הוא בחי' הרצון שנעשה עפ\"י השגה והבנה, ועי\"ז יבוא לבחי' בטל רצונך ביטול הרצון שלמעלה מגדר השגה כו' שלגבי בחי' זו יתבטלו רצון אחרים ג\"כ, וכך הוא הדבר שא\"א לבוא לבחי' הרצון העליון אם לא ע\"י הרצון התחתון שהוא הכלי כו'.\n<b>ולהבין</b> הענין בתוספות ביאור יובן מענין ריב\"ז שבכה שאיני יודע באיזה דרך מוליכין אותי, ולכאורה יפלא הלא כל ימיו ק\"כ שנה עסק בתומ\"צ, וא\"כ לא שבקת חיי כו', אך הענין שכ\"ז ידע שבירר כל עשר כחות הנפש ע\"י עסק התומ\"צ, אך מצד ענותנותו הסתפק בעצמו אם בירר בכי טוב עצמות נפשו שהוא הרצון שלמעלה כו', וזהו הל' איני יודע שספיקו הי' בענין הרצון שלמעלה מן הדעת כו'. אמנם מצינו בחי' זו בר' חנינא בן דוסא שאמר ריב\"ז אלמלא הטיח בן זכאי את ראשו בין ברכיו כל היום לא היו משגיחין עליו, והאף שלכאורה ריב\"ז גדול הי' מרחב\"ד שמריב\"ז נמצא דינין ופסקי"],[4101400179,"הלכות ומרחב\"ד לא נמצא כלל שום דין, אך הענין הוא כנ\"ל שכל ענין הביטול דריב\"ז הי' רק בענין חכמה התו' שהוא בחי' הרצון שמצד הדעת וההשגה, אבל הביטול דרחב\"ד הי' למעלה יותר מצד ביטול השגה שהוא בחי' הרצון שלמעלה כו', שזהו ענין התפלה יהי רצון, ולכך הי' נענה מיד, וכן אמרינן בגמרא בחסידים הראשונים שהיו שוהין שעה אחת כו' ופריך תורתן אימתי נעשית, אלא מתוך שחסידים הן תורתן משתמרת, הרי שזהו בחי' גבוה יותר מהתורה עד שעי\"ז תורתן משתמרת. וזהו מ\"ש ששים המה מלכות כו' אחת היא יונתי, ששים המה מלכות אלו ס' מסכתות, ואחת היא יונתי היא בחי' עצמות הנפש שדבוקה בעצמות אוא\"ס ב\"ה הוא גבוה יותר מבחי' ששים המה, וזהו שוהין שעה אחת, שהיו מגיעין לבחי' ומדריגה אחת היא יונתי.\n<b>ועפ\"י</b> כל הנ\"ל יובן ענין מ\"ט ספה\"ע ומ\"ת, שענין הספירה היינו המשכת מ\"ט שע\"ב שעי\"ז מגיעין לבחי' הרצון שמצד הדעת וההשגה כו' שבמוח הבינה יש נ' שע\"ב ובהמשכת המוח אל הלב משכן המדות הם זפ\"ז מ\"ט שע\"ב, וענין מ\"ת היינו המשכת והתגלות הרצון העליון שלמעלה כו', וזהו שבעשרת הדברות יש תר\"ך אותיות, ועשרת הדברות כללות כל התורה שבה תרי\"ג מצות דאוריתא וז' דרבנן, בחי' כתר, והגם דאורייתא מח\"ע נפקת, היינו רק נפקת אל הגילוי אבל שרשה ומקורה הוא בחי' כתר. וזהו אנכי ה' אלקיך אשר הוצאתיך מאמ\"צ, שענין מצרים היינו בחי' ההבנה וההשגה בענין סובב וממלא שהוא רק בחי' מצר וגבול דסדר ההשתל', אבל ע\"י בחי' אנכי מי שאנכי הוצאתיך כו'. וזהו מארז\"ל שעל כל דיבור ודיבור פרחה נשמתן, לפי שזהו ידוע שלא כל הנשמה כולה מתלבשת בגוף רק הארה לבד, ובשעת מ\"ת נסתלקה הארה זו ונתכללה בבחי' שורש ועצמות הנשמה כו'.\n<b>ועפ\"י</b> כל זה יובן פי' הכתוב שאו את ראש כו' לגלגלתם, שבחי' ראש הוא בחי' המוחין והרצון הנולד מהם, וצריך לנשאה ולחברה לבחי' גלגלתא דחפיא כו' בחי' הרצון שלמעלה כו'. ובזה יובן כפל הפסוקים שאו שערים ראשיכם כו' ויבוא מלך הכבוד כו' שאו שערים ראשיכם כו' ויבוא מלך הכבוד כו' ה' צבאות הוא מלך הכבוד סלה, ובת\"י פי' ששערים הראשונים קאי על תרעין דבי מקדשא, ושערים השניים קאי על תרעין דגנתא דעדן. והנה עם הנ\"ל יובן דפי' שערים היינו מ\"ט שע\"ב ופי' שאו הוא ע\"ד שאו מרום עיניכם, ופי' ראשיכם הוא בחי' התבוננות, והענין שישאו המ\"ט שע\"ב לבחי' מוח הבינה עד שיולד לו רצון שמצד ההבנה, ושאו שערים [הב'] הוא ע\"ד שאו את ראש כו' והפי' שישאו בחי' הראשים לבחי' לגלגלתם הרצון שלמעלה כו', ועי\"ז ימשיכו הב' בחי' מלך הכבוד. והענין הוא כמארז\"ל מנין שהקב\"ה מתפלל שנאמר והביאותים כו' בבית תפילתי תפלתם לא נאמר אלא תפילתי כו' מאי מצלי יר\"מ שיכבשו רחמי את כעסי ויגולו רחמי על מדותי, ופי' התפלה למעלה, דפי' הקב\"ה הוא בחי' קדוש וברוך סובב וממלא, דפי' קדוש מובדל"],[4101400180,"ולא כמו שהנשמה מחי' את הגוף שמחייהו בדרך התלבשות אבל חיות אלקי בעולמות אינו כן רק שהוא קדוש ומובדל בחי' סובב כל עלמין, ובחי' ברוך הוא בחי' ההמשכה שבתוך העולמות בחי' ממכ\"ע, והממוצע המחברם הוא בחי' המדות שבהם הוא התנהגות העולמות כמ\"ש כי אמרתי עולם חסד יבנה וכן צ\"ל דין ורחמים, וזהו הקב\"ה מתפלל הוא בחי' ההמשכה ממהו\"ע שלמעלה מגדר סובב וממלא, דלית שמאלא בהאי עתיקא ולאו מכל אילין מדות איהו כלל אני הוי' לא שניתי, וזהו יר\"מ שיכבשו רחמי את כעסי שעי\"ז הוא המתקת הדינין ויגולו רחמי על מדותי דלאו מכל מדות כו', והתהוות החכמה למעלה הוא ע\"י תפילה של מטה וכמארז\"ל מט\"ט קושר כתרים לקונו מתפילותיהן של ישראל וד\"ל, וזהו פי' מלך הכבוד הא' היינו בחי' סובב וממלא בחי' הקב\"ה וכבוד בגימ' ל\"ב נ\"ח, שאז האופנים אומרים ברוך כבוד ה' כו', והמשכה זו הוא ע\"י בחי' הרצון התחתון, ומלך הכבוד הב' היינו בחי' הקב\"ה מתפלל, ומלך הוא ע\"ד המלך המרומם לבדו, ולכן הזכיר כאן ה' צבאות ומלך הכבוד סלה שכל מקום שנאמר נצח סלה ועד אין לו הפסק בחי' נצחיות דא\"ס עד שיומשך גם בבחי' צבאות למטה, והמשכה זו הוא ע\"י בחי' שערים הב' הרצון העליון.\n<b>נמצא</b> שיש ב' בחי' רצון שזהו ג\"כ הפי' דשאו את ראש כו' לגלגלתם, ומקודם נאמר באוהל מועד, והענין דפי' אוהל הוא בחי' מקיף וכמ\"ש אחזתיו ולא ארפנו עד שהביאתיו אל בית אמי ואל חדר הורתי, בית אמי תושב\"כ חדר הורתי תושבע\"פ, ופי' אחזתיו הוא כשמגיעים לבחי' רצון העליון שמצד עצמות הנפש שדבוקה בעצמות אוא\"ס ב\"ה וכמאמר ישראל מתקשראן באורייתא ואורייתא בקוב\"ה, וצ\"ל ולא ארפנו, והענין כמארז\"ל ויסעו ישראל מרפידים ויבוא עמלק כיון שרפו ידיהם מן התו' מיד ויבוא עמלק וכדאיתא ע\"פ הקול קול יעקב והידים ידי עשו שבזמן שהקול קול יעקב אין הידים ידי עשו, כי עיקר יניקת החיצונים הוא מהידים כמ\"ש שממית בידים תתפש כו', וזהו ולא ארפנו שלא יהי' בחי' רפיון ידים, וזהו ע\"י התורה שהתורה פועלת ב' בחי' הא' החיבור דשאו את ראש בנ\"י והב' בחי' ולא ארפנו, וזהו עד שהביאתיו כו' ואל חדר הורתי ופי' הורתי כמ\"ש אשר כתבתי להורותם, ויש בזה ב' פי' ל' הוראה ול' הריון שהתו' פועלת ג\"כ בנשמה ליכלל בבחי' עיבור באלקות, וזהו ג\"כ הבחי' דאוהל מועד בחי' מקיף המסמא עיני החיצונים שלא יהי' בחי' רפיון ידים ויניקת החיצונים, לפי שהתורה הוא בחי' לבוש המלביש המשכת אוא\"ס שלא יומשך רק במקום הראוי.\n<b>ואמר</b> אח\"כ תפקדו כו' אתה ואהרן, לפי שצ\"ל העלאת הנפש מתחילה וזהו ע\"י בחי' הלוים וכמ\"ש ובחנות המשכן יקימו אותו הלוים, ובכלל יש ג' בחי' לוים גרשון ומררי וקהת שזהו בחי' קו השמאל בג\"ה העושים העלאה וכמ\"ש שמאלו תחת לראשי כו', גרשון הוא בחי' גירוש הרע ויגרשהו וילך לו וכמ\"ש גרש האמה הזאת כו', וכענין איזהו גבור הכובש את יצרו, שזהו בחי'"],[4101400181,"מעולה יותר מבחי' יצי\"מ שנאמר שם כי ברח העם לפי שהי' הרע עדיין בתוקפו וברחו מהרע אבל כאן צ\"ל שיגרש הרע ממנו, ומררי בחי' מרירות, ויש כמה בחי' מרירות, מרירות פשוטים על חטאותיו חטאת נעורים, ועוד יש מרירות על העדר הבחי' דגלגלתם שזה נק' בחי' כרת כמ\"ש ונכרתה הנפש ההיא מקרב עמה, שהארת הנפש נכרתה משרשה בחי' גלגלותם הנ\"ל מצד כי עונותיכם מבדילים כו', ועי\"ז יבוא ג\"כ לבחי' קהת מל' ולו יקהת עמים ות\"א ולו יתכנשון עממיא וזהו פי' קהת ל' קיוהא ג\"כ, שזהו בחי' אתהפכא, וכ\"ז הוא בחי' העלאה ממטלמ\"ע שמאלו תחת כו', ועי\"ז הוא בחי' כהנים וימינו תחבקני המשכה מלמעלמ\"ט וזה\"ע אהרן ג\"כ לשון הריון, והא' הוא המשכת בחי' אלופו ש\"ע בתו' כי כל האומר אין לי אלא תורה כו', ובכהנים קו הימין ג\"כ ג' בחי' כה\"ג וכהן הדיוט וסגן בחי' חח\"ן, ובחי' משה הוא הבחי' המחבר ההעלאה וההמשכה בחי' קו האמצעי, וזהו אתה ואהרן."],[4101400182,"<h3>וידבר גו' במדבר סיני - הוספה שהוסיף ר' הלל</h3>\n<b></b><b>[ההוספה שהוסיף לר' הלל]</b>\n<b>בענין</b> ב' בחי' מלך הכבוד, שזהו ב' בחי' כ\"ע וכ\"ת, וכבוד הא' הוא בחי' כ\"ת מל' מכ\"ע, ומלך הכבוד פי' מלך על הכבוד בחי' ז\"א, וכמו\"כ מלך הכבוד הב' דכבוד כ\"ע ל\"ב נ\"ח ומלך הכבוד פי' מלך על הכבוד בחי' עתיק.\n<b>ובענין</b> אחזתיו, הקשו לו למה אינו די בתפלה לבד שמגיעין ג\"כ לבחי' הרצון שלמעלה. ואמר שזהו כענין שבקש משה ונפלינו אני ועמך, ולמה הי' צריך לבקש הלא בלא\"ה אין אוא\"ס שורה אלא במי שבטל אליו, אך הענין לפי שהגיע אז למדריגת י\"ג מדה\"ר בחי' נושא עון ועובר כו' דשם כחשיכה כאורה ויכול לימשך ג\"כ בבחי' ההיפוך, לכן ביקש שמבחי' זו לא יומשך ג\"כ רק בבחי' הביטול וזהו ונפלינו כו', וזהו ג\"כ ענין התו' שהוא בחי' חכ' קו המדה למדוד ההמשכה שע\"י התפלה שלא יומשך רק בבחי' הביטול וכמ\"ש בענין או\"א שהלבישו לזרועות דא\"א בענין ויוציאנו ה' אלקינו משם וד\"ל."],[4101400183,"<h3>והתהלכתי בתוככם</h3>\n<b>והתהלכתי</b> בתוככם, משמע ב' מיני הילוך, וקאי על הקדב\"ה, והיינו בבחי' הגילוי אא\"ס מלמעלה למטה, והענין כי בעבודה באדם יש ג\"כ ב' מיני הילוך מלמעלמ\"ט ומלמטלמ\"ע, הא' ע\"ד מ\"ש אחרי הוי' אלקיכם תלכו שההילוך הוא בבחי' אחורים וחיצוניו' וע\"ד שנאמר במשה וראית את אחורי, רק שהי' אצלו זה בבחי' ראי', ובישראל נאמר רק תלכו, וזהו ההילוך מלמטלמ\"ע, והב' הוא כמ\"ש באברהם הלוך כו' התהלך לפני, וכן בחזקי' נאמר אשר התהלכתי לפניך, שההילוך הוא בבחי' פנים, וזהו מלמעלמ\"ט, ושני הבחי' הם בעבודה בנפש.\n<b>וביאור</b> ענין הילוך זה מהו, הנה באברהם נא' פסוק זה גבי מצות מילה, והיינו כי מילה הוא בחי' ברית שהוא בחי' יסוד שהוא בחי' המקשר ב' הפכים, והו\"ע יחוד עליון פי' שאור עליון יתגלה למטה כמו שהוא למעלה, שגם למטה לא יהי' יש ודבר נפרד, וזהו נקרא ג\"כ הילוך, וכמ\"ש קול הוי' אלקים מתהלך בגן וכמ\"ש בעה\"ק שכל הליכה האמורה למעלה הוא בבחי' התפשטות והמשכת המדריגה להאיר למטה, וזהו בחי' ההילוך שבבחי' הפנים שמלמעלמ\"ט, וזהו ג\"כ מ\"ש בחזקי' אשר התהלכתי לפניו והטוב בעיניך עשיתי, ארז\"ל שסמך גאולה לתפילה, והיינו כי גאולה היא מעלמא דדכורא בחי' יסוד וכמ\"ש אם יגאלך טוב וכתי' אמרו לצדיק כי טוב שהוא בחי' התגלות אא\"ס, וסמיכות גאולה לתפילה הוא חיבור בחי' זו בבחי' תפילה שהוא בחי' מל', וזהו היחוד עליון.\n<b>ולהבין</b> זה י\"ל מ\"ש והיו הדברים האלה אשר אנכי מצוך היום, וארז\"ל בכל יום יהי' בעיניך כחדשים, וי\"ל איך יכול להיות בכל יום כחדשים,"],[4101400184,"הענין הוא כי יש שני בחי' ממכ\"ע וסוכ\"ע, ממכ\"ע הוא מה שאלקו' מאיר בבחי' התלבשות והתגלות בפנימי' בנבראים ולכן יש בבחי' זו בחי' התחלקות המדריגות, כמו עד\"מ הנשמה שמתלבשת בגוף מתחלקת לכמה בחי', שכל במוח ומדות בלב הילוך ברגל, והיינו מפני שהנשמה מתלבשת בפנימי' בהגוף לכן יש לכל בחי' כלי לפי ערכו, כמו\"כ ארז\"ל מה הנשמה ממלא את הגוף כך הקדב\"ה ממלא את כל העולם בבחי' התלבשות, ולכן יש חילוקי מדריגות כל עולם לפי ערכו כמו געה\"ע שנמשך בו התגלות זיו השכינה בבחי' גילוי יותר מבחי' געה\"ת. וכן בעלמין יש בחי' עלמין סתימין שמאיר שם אלקות בבחי' גילוי עד שהם בתכלית הביטול, ובחי' עלמין דאתגליין שאינו מאיר שם אלקות בבחי' גילוי כ\"כ (וכמו שאנו רואים למטה שיש התחלקות בבחי' דצח\"מ שבדומם מצומצם בו החיות יותר ובצומח מלובש בו חיות יותר שמלובש בו נפש הצומחת ובחי יש יותר חיות שיש בו נפש החיונית כו', וכך למעלה ד' עולמות אבי\"ע נק' דצח\"מ שבאצי' יש יותר גילוי אא\"ס וזהו שנק' ממכ\"ע שאא\"ס מתלבש בכל עולם לפי ערכו), אבל בחי' סוכ\"ע הוא בחי' אא\"ס שאינו יכול להיות בבחי' התלבשות בפנימיות בגילוי כ\"א בבחי' העלם ומקיף, ולכן הוא סוכ\"ע בשוה בלי שום חילוק המדריגות, מעלה ומטה ואצי' ועשי' שוים לפניו ממש, וכמ\"ש והקדוש בשמים ובארץ שהוא קדוש ומובדל מבחי' שמים כמו מבחי' ארץ, ואין שום התחלקות מעלה ומטה כלל, וכמ\"ש ומתחת זרועות עולם שמבחי' סוכ\"ע יכול להיות הגילוי אפי' מתחת זרועות עולם.\n<b>והנה</b> ע\"י המצות ממשיכים גילוי אא\"ס מבחי' סוכ\"ע, וכמו שאנו אומרים אשר קדשנו במצותיו, שע\"י המצות ממשיכים מבחי' קדש העליון, וזהו מ\"ש והיו הדברים האלה אשר אנכי מצוך היום, אנכי מי שאנכי עצמותו ומהותו ממש מצוך לשון צותא וחיבור בבחי' פנימי' וזהו מצוך היום, היינו שהמשכה זו א\"א להמשיך כ\"א היום דוקא בעוה\"ז היום לעשותם שהוא עולם המעשה ע\"י מעשה המצות, ולכן בכל יום יהי' בעיניך כחדשים כי כשמתבונן שע\"י המצות נמשך גילוי מבחי' סובב בפנימי' ושזה א\"א כ\"א היום דוקא בעוה\"ז א\"כ יהי' בעיניו כחדשים. וזשארז\"ל יפה שעה אחת בתומע\"ט בעוה\"ז מכל חיי העוה\"ב, כי חיי העוה\"ב עם היות שיושבין ונהנין מזיו השכינה ומוטב דלידייני' וליתי לעלמא דאתי, עכ\"ז הוא רק בחי' זיו והארה בחי' ממכ\"ע וגם זה בחי' זיו והארה מבחי' ממכ\"ע, ולכן אין שם בחי' תשובה כי להיות שם הגילוי בבחי' פנימי' לכן צ\"ל כסדר המדריגות, כף הקלע וגיהנם וגעה\"ת וגעה\"ע וא\"א להשתנות שם כמו שא\"א להשתנות מבחי' ראש רגל ורגל ראש כמ\"ש בלק\"ת בד\"ה צו את בנ\"י, אבל בעוה\"ז שמאיר בחי' סוכ\"ע ע\"י מעשה המצות שייך בחי' תשובה לשנות את עצמו.\n<b>וזהו</b> מ\"ש בחסד ואמת יכופר עון, חסד ואמת הם תו\"מ חסד הוא בחי' מצות בחי' גמ\"ח ואמת הוא בחי' תורה אין אמת אלא תורה, וע\"י נמשך גילוי"],[4101400185,"אא\"ס סוכ\"ע ששם אם צדקת כו' ולכן יכופר עוון כו'. אך לכאורה י\"ל כי עם אמת שע\"י תו\"מ נמשך גילוי סוכ\"ע אשר מחמת זה הגילוי שייך תשובה אך הרי המצות הם רצון העליון דסוכ\"ע וכך הוא הרצון בתו\"מ שנתלבש הרצון שזה ירצה וזה לא ירצה שזהו היפוך מבחי' אם צדקת כו', והעון הוא נגד רצונו ית' וא\"כ איך עי\"ז שנמשך ע\"י המצות סוכ\"ע יכופר עון. אך הענין הוא כי הנה כתי' תען לשוני אמרתיך כי כל מצותיך צדק, פי' שכל המצות הם מבחי' צדקה, והענין כי הנה הרצון למעלה אינו כמו למטה באדם שהרצון הוא להשלים איזה חסרון אבל למעלה הרי אנת שלימותא דכלא וכלום חסר, וזה שיהי' לו רצון בתו\"מ הנה רצון אותיו' צנור פי' שהוא המשכה מבחי' אם צדקת כו' שיהי' בחי' רצון זה, וגם צינור הוא צמצום שנתצמצם שיהי' הרצון בתו\"מ דוקא, וזהו כי כל מצותיך צדק שזהו צדקה מאתו ית' שיחפוץ בזה, והנה אעפי\"כ מלובש בבחי' רצון זה פנימי' אא\"ס ממש, ובזה יובן איך שיכול להיות ג\"כ ע\"י הרצון של תו\"מ נושא עון כו' ע\"י תשובה כי מצות תשובה היא מצוה כללית שמגיע בבחי' מקור הרצון, דהיינו שהרצון של תו\"מ נמשך באמת מבחי' אם צדקת כו' ומשם נמשך להיות נושא עון, אך מ\"ש בחסד ואמת יכופר עון שמשמע שע\"י תו\"מ דוקא נתכפר היינו לפי שמבחי' אם צדקת כו' רק שנתצמצם בבחי' רצון זה של תו\"מ ותשובה מגיע בבחי' מקור הרצון דהיינו בבחי' אם צדקת כו', ומשם יכול להיות נמשך לכולם בשוה, אבל כשההמשכה הוא ע\"י צינור של תו\"מ אזי נמשך ההמשכה בסט' דקדושה דוקא.\n<b>והנה</b> כשיתבונן בכל זה איך שזה הכח הוא דוקא בעוה\"ז עי\"ז יהי' בעיניו כחדשים ממש, ועוד י\"ל כי להיות המשכה מסוכ\"ע לכן ההמשכה שממשיך בכל יום ע\"י מעשה המצות הוא המשכת אור חדש שאין המשכה שממשיך היום שוה לשל אתמול, כי הנה כתי' אין כל חדש תחת השמש, ופי' תחת השמש היינו אפי' בבחי' שמש ומגן הוי' אלקי', והיינו אפי' מבחי' שם הוי' שנק' שמש אין כל חדש המשכת אור חדש כ\"א לחדש את הישנות, אבל לעילא מן שמשא דהיינו מבחי' אור הגנוז שהוא בחי' אור שבעת הימים שהוא למעלה מבחי' שם הוי' שהוא בחי' חכ' דהיינו בחי' פנימי' יסוד אבא שהוא פנימי' ע\"י משם דוקא נמשך המשכה חדשה, והוא בחי' אור המאיר בשם הוי', וכשארז\"ל אור שנברא ביום ראשון הי' מביט בו מסוף העולם ועד סופו עמדו וגנזו, וירא אלקי' את האור כי טוב כי טוב לגנוז, וע\"ז נאמר מה רב טובך אשר צפנת כו', משם נמשך המשכה חדשה לגמרי דהיינו הולדת נשמות חדשות. ובזה יובן מה שבשבת הוא היחוד להוליד נשמות חדשות, כי בשבת מאיר ג\"כ אור חדש, ולכן אומרים בשבת טוב להודות לפי שמתגלה בחי' רב טובך, וזהו אור חדש, ובכל השבוע המשכה זו ע\"י המצות, כי אשר צפנת ליראיך ס\"ת תר\"ך שהם תר\"ך מצות, ונמשך ע\"י בחי' רב טובך, וכן בתורה נגנז האור וכמ\"ש היכן גנזו בתורה."],[4101400186,"<b>והנה</b> בזה יובן הקושיא שבגמ', כתי' ועמדו זרים ורעו צאנכם וכתי' ואספת דגנך כו' ומשני ל\"ק כאן בזמן שישראל עושין רצונו של מקום וכאן בזמן שאין ערש\"מ, והקשה בתוס' שהרי ואספת דגנך כתי' בפ' והי' אם שמוע ואיך הוא אין ערש\"מ, ותי' הה\"מ ז\"ל נ\"ע דלכך נק' פ' שני' אין עושין רצונו של מקום לפי שלא נאמר בה בכל מאדך, וגם זה עדיין אינו מובן וכי מפני שלא נאמר בה בכל מאדך יהי' נק' אין עושין רצונו של מקום שהרי נא' בכל לבבכם ובכל נפשכם. והנה להבין זה י\"ל מקודם פי' מקום, דהנה כתי' הנה מקום אתי, דהנה מקום הוא כולל ו\"ק מעלה ומטה מזרח מערב צפון ודרום, והנה כמו שיש למטה ו\"ק כמו\"כ למעלה יש ג\"כ בחי' מקום שהוא שרש של המקום בחי' ו\"ק מעלה ומטה, ופי' מעלה היינו מה שלמעלה מהשגה נק' מעלה ומה שבא בהשגה נק' מטה, וכמו געה\"ע וגעה\"ת שלכך נק' געה\"ע לפי שהוא למעלה מהשגה לנשמות שבגעה\"ת, וכן צפון ודרום הוא בחי' חו\"ג ושרש המקום הוא בחי' ו' מדות עליונות לך ה' הגדולה כו', והנה כ\"ז הוא בחי' ממכ\"ע שנעשה מקור לעולמות שנק' מקום והיינו שמאיר בבחי' התלבשות אבל אא\"ס הסוכ\"ע הוא למעלה מגדר מקום לפי שמאיר בבחי' העלם ומקיף אין שייך מעלה ומטה כלל וכמ\"ש והקדוש במשים וארץ בשוה, והנה פי' עושין רצונו של מקום היינו שממשיכים מבחי' רצון שהוא בחי' סוכ\"ע בבחי' מקום שהוא בחי' ממכ\"ע שיאיר בבחי' פנימי' ממש אור הסוכ\"ע ויהי' גם המקום בבחי' ביטול כשיאיר במקום מבחי' למעלה מהמקום, וכמו מקום הארון אינו מהמדה אף שהי' אמתיים וחצי אעפי\"כ לא הי' תופס מקום כלל לפי שהי' מאיר מבחי' שלמעלה מהמקום במקום, ועד\"ז הוא פי' ערש\"מ, והמשכה זו היא ע\"י אהבה דבכל מאדך כי בחי' מאדך הוא בלי גבול דהיינו בלי שום מונע ומעכב כלל, והוא לפי שמגיע בפנימי' ותוכיות הלב ממש דהיינו שבחי' מקיף הנפש שהוא בחי' יחידה שבנפש מתגלה בבחי' פנימי' לכן עי\"ז גורם למעלה ג\"כ שיומשך בחי' סוכ\"ע שהוא בחי' מקיף בבחי' ממכ\"ע בפנימי', וזהו ערש\"מ וזהו שפ' ראשונה לפי שנא' בה בכל מאדך נק' ערש\"מ.\n<b>וזהו</b> ג\"כ מ\"ש בזהר פ' בשלח ע\"פ ממעמקים קראתיך הוי' ומי אמר דוד הכי והא כתי' בכל לבי דרשתיך ודא קרא סגי מאי בעי ממעמקי', אלא הכי תאנא כל ב\"נ דבעא בעותי' קמי מלכא בעי לכוונא דעתא ורעותא מעיקרא דכל עיקרין לאמשכא ברכאן מעומקא דבירא בגין דינגיד ממבועא דכלא, א\"כ מבואר שכדי להמשיך מעומקא דבירא ומבועא דכלא שזהו בחי' סוכ\"ע לא די בבחי' בכל לבי דרשתיך שהיא אהבה דבכל לבבך כ\"א בבחי' ממעמקי' קראתיך שזהו אהבה דבכל מאדך, ולכן נק' זה ערש\"מ, אבל פ' שני' שלא נא' בה בכל מאדך נק' אין ערש\"מ, והגם שבודאי ע\"י מעשה המצות ממשיך המשכת סוכ\"ע שהרי נאמר אם שמוע תשמעו אל מצותי, וע\"י המצות נמשך סוכ\"ע, אך הענין הוא שאין ההמשכה בבחי' פנימי' כ\"א בבחי' מקיף לבד, ומה שנמשך המשכה בפנימי' ע\"י מעשה המצות אינה מעצמיות סובב כ\"א רק הארה מבחי' סובב"]]});
